quests[11251] = { id = 11251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Abschnitt", description = "Der Preis war hoch, aber wir konnten die Untersuchung der Ausgrabungsstätte beenden.\n\nKeine guten Neuigkeiten - fast jeder wurde erschlagen oder gefangen genommen. Es werden nur ein paar Wächterveteranen vermisst.\n\nWir Späher haben alles getan, was wir hier tun können. Ihr müsst dort weitermachen, wo wir aufgehört haben.\n\nVom Hügel im Nordosten aus dringen Geräusche eines Gefechts herüber. Seht einmal nach, {class}. Wir können nur darauf hoffen, dass es ein paar Überlebende gibt und dass sie Informationen haben, die wir gegen diesen Feind verwenden können.", sourceObjective = "Kundschafterin Valory möchte, dass Ihr den Geräuschen nachgeht, die vom nordöstlichen Teil von Wyrmskol herstammen.", completion = "Ihr mögt vielleicht spät dran sein, doch es ist gut, jemanden freundlich Gesinnten zu sehen.\n\nNun hört auf herumzustehen und in der Nase zu bohren. Es gibt viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11252] = { id = 11252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Utgarde!", description = "Zugehört, <Junge/Mädchen>. Ich habe meinen Teil dieser Kreaturen erledigt - und auch Euren Teil, was das betrifft. Was Ihr wissen müsst, ist folgendes...\n\nDie Vrykul sind furchtlose Kämpfer. Scheint so, als sehnten sie sich danach, im Kampf zu sterben. Ihre Zahl und Wildheit bedeutet für uns den Untergang - um es einfach auszudrücken.\n\nEs gibt jedoch einen, den sie hoch schätzen. Man nennt ihn Ingvar. Ich weiß nicht, wieso sie um seine Gunst werben, aber wenn Ihr ihn tötet, wird das ihr Selbstbewusstsein erschüttern.\n\nVielleicht werden wir dann eine Chance haben...", sourceObjective = "Verteidiger Mordun hat Euch mit der Exekution von Ingvar dem Brandschatzer, der tief in Utgarde wohnt, beauftragt.\n\nAnschließend sollt Ihr dessen Kopf zu Vizeadmiral Keller bringen.", progress = "Es freut mich, zu sehen, dass Ihr wohlauf seid.\n\nWir hatten bis jetzt in etwa genau so viele Verluste, wie wir verschmerzen können.", completion = "Hervorragend!\n\nDas könnte die Glückswende sein, auf die wir alle so lange gehofft haben.\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11253] = { id = 11253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind ausschnüffeln", description = "Nun, da der Bengel einen vollen Magen hat, wird er vielleicht eher dazu geneigt sein, zu kooperieren. Hier ist seine Leine. Ihr müsst ihn dann nur noch aus seinem Käfig holen, sobald Ihr bereit seid.\n\nIch weiß zwar nicht, welchen Fund sich Anselm von Euch verspricht, aber sucht nach Hinweisen, wo auch immer der Hund Euch hinführen mag.", sourceObjective = "Benutzt die Seuchenhundleine in der Nähe der Seuchenhundkäfige im Hafen der Vergeltung und sucht dort nach Hinweisen, wo der Seuchenhundfährtenleser Euch hinführt.\n\nBereitgestellter Gegenstand:", completion = "Die schuppige Schriftrolle ist mit schlicht gezeichneten Bildern bedeckt. Ihr habt das Gefühl, dass dies genau das ist, woran der Hüter des Zwingers gedacht hat, als er Euch darum bat, nach Hinweisen zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11254] = { id = 11254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karte aus Drachenhaut", description = "Nach genauerer Untersuchung scheint es sich bei der Schriftrolle um eine Karte des Fjords zu handeln, die mit vielen Bildern versehen ist. Die Lage verschiedener Dörfer wird mithilfe von Markierungen dargestellt, die wie Stammessymbole aussehen.\n\nDer Standort des Hafens der Vergeltung wird mit einem unverhältnismäßig großen Totenschädel markiert.\n\nFür Hochexekutor Anselm wird diese Karte höchstwahrscheinlich von militärischem Wert sein.", sourceObjective = "Bringt die Karte aus Drachenhaut zu Hochexekutor Anselm im Hafen der Vergeltung.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt, {class}?", completion = "<Der Hochexekutor betrachtet aufmerksam die Karte und lässt ab und an den Blick schweifen, um im Fjord nach Landmarken zu suchen.>\n\nDa drüben befindet sich der östliche Küstenstrich. Die Dörfer der Drachenschinder und Winterskorn befinden sich hier und hier... und das hier oder diejenigen, die zum Töten freigegeben sind, sind wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[11255] = { id = 11255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene in Wyrmskol", description = "Diese Schlacht ist noch lange nicht vorbei, {name}. Wenn unsere Leute, die sich in dem Dorf befinden, noch immer am Leben sind, dann muss jemand dort hingehen und sie befreien.\n\n<Vizeadmiral Keller nickt Euch zu.>\n\nGeht nach Wyrmskol im Norden und seht Euch nach unseren Leuten um, sobald Ihr dort seid. Sollten sie irgendwo eingesperrt sein, dann müsst Ihr einen Weg finden, sie zu befreien.\n\nVielleicht haben sie etwas mehr Kunde über das, was wir hier wirklich bekämpfen.", sourceObjective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr 3 Gefangene aus Valgarde befreit.", completion = "Die Soldaten, die Ihr befreit habt, konnten uns einiges berichten. Diese Monster nennen sich 'Vrykul'. Der Stamm, der sich in Wyrmskol niedergelassen hat, wird von einem Mystiker namens Yanis angeführt, ein Untergebener von Ingvar dem Brandschatzer - auch ein Vrykul.", sourceObjectiveStatus = "unverified-source-field" }
quests[11256] = { id = 11256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorn muss fallen!", description = "{name}, gen Süden befindet sich die Vrykulfestung Skorn. Die seltsamen Riesen, die dort wohnen, sind vor Kurzem erwacht und haben damit begonnen, uns anzugreifen, wo auch immer es ihnen möglich ist.\n\nMeine Späher berichten mir, dass sie kurz davor sind uns hier anzugreifen. Wir sind jedoch nicht stark genug, um solch eine Streitmacht abzuwehren. Stattdessen werden wir uns aufmachen und gen Norden, in weniger gefährliche Lande, ziehen.\n\nIch bitte Euch, dass Ihr Euch etwas Schlaues einfallen lasst, um uns etwas Zeit zu verschaffen. Einen Mutigen, der über Näheres in Kenntnis gesetzt ist, habe ich schon vorgeschickt. Wenn Ihr dieses Emblem in Skorn vorzeigt, wird er sich zeigen und Euch so gut wie möglich zur Seite stehen.", sourceObjective = "Häuptling Aschtotem möchte, dass Ihr das Emblem der Winterhufe in Skorn benutzt und dann mit dem Helden der Winterhufe sprecht.\n\nBereitgestellter Gegenstand:", completion = "Es wird interessant sein, an Eurer Seite zu kämpfen und etwas über Euer Volk zu lernen, {class}.\n\nWollen wir fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[11257] = { id = 11257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausam, aber notwendig", description = "Unsere Ältesten erzählen uns, dass die Vrykul womöglich von den Toten auferstehen können - ähnlich den wandelnden Toten, die Ihr Geißel nennt, doch eine andere Art des Untodes.\n\nWir sollten kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr zerstückelt die Überreste der von uns erschlagenen Vrykul.\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also selbst den dicksten Knochen spalten.", sourceObjective = "Der Held der Winterhufe möchte, dass Ihr mit der Machete des Kriegerhelden 20 Vrykul des Winterskornstammes in Skorn zerstückelt.", completion = "Habt Ihr das schon einmal gemacht? Ihr scheint im Umgang mit der Machete geübt zu sein.\n\n<Der Held sieht Euch misstrauisch an.>\n\nIch werde sie Euch jetzt wieder wegnehmen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11258] = { id = 11258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenne, Skorn - brenne!", description = "Häuptling Aschtotem hat mir befohlen, viele Gebäude hier zu zerstören.\n\nIhr habt aber die Verantwortung, also ist es auch Eure Aufgabe, {name}.\n\nIch schlage vor, wir brennen die zwei Langhäuser und die Baracken ab, die im tieferen Bereich von Skorn stehen. Alles, was wir zu tun haben, ist in jedes hinein zu gehen und sie mit dieser Fackel in Brand zu stecken.", sourceObjective = "Der Held der Winterhufe schlägt vor, dass Ihr mit der Fackel des Helden die zwei Langhäuser im Nordosten und -westen und die Baracken in Skorn in Brand setzt.", completion = "<Der Held nickt Euch zu, von Eurem guten Umgang mit der Fackel überzeugt>\n\nLasst diese Vrykul die Hitze dieses Landes spüren. Lasst sie die Furcht kennenlernen, die sie anderen aufzwingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11259] = { id = 11259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme des sicheren Untergangs", description = "Wenn wir durch Skorn ziehen, müssen wir die Türme zerstören.\n\nWenn Ihr sie Euch genau anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah heranzuwagen bedeutet den sicheren Tod.\n\nWir können jedoch Windreiterunterstützung aus dem Lager der Winterhufe anfordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran.", sourceObjective = "Der Held der Winterhufe meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Kriegerhelden die Türme in Skorn für Luftangriffe markiert.", completion = "Ihr habt einen starken Arm, {name}.\n\nSieht so aus, als würden sich die Windreiter endlich einmal nützlich erweisen anstatt den ganzen Tag nur rumzustehen und zu trinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11260] = { id = 11260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert seinen Aufstieg!", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", sourceObjective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Großmutter Ankha an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Sie befindet sich im Lager der Winterhufe.", progress = "Ja? Wie kann ich Euch behilflich sein, Kind?", completion = "Ja, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich werde herausfinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11261] = { id = 11261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bezwinger von Skorn!", description = "Ihr habt alles getan, wofür wir hierher ausgesandt wurden, {class}. Ich muss zugeben, dass Ihr gut kämpft. Eure Leute sind nicht so merkwürdig, wie ich es zu Anfang dachte.\n\nHäuptling Aschtotem will sicherlich von Eurem Erfolg erfahren, aber solltet Ihr Euch entscheiden aus irgendeinem Grund hier zu bleiben, werde ich weiter an Eurer Seite kämpfen.", sourceObjective = "Bringt das Zeichen der Winterhufe zu Häuptling Aschtotem im Lager der Winterhufe zurück.", progress = "Welche Neuigkeiten aus Skorn bringt Ihr, {name}?", completion = "Das sind in der Tat gute Neuigkeiten! Ihr habt uns etwas mehr Raum zum Atmen verschafft, nun können wir unsere Abreise weiter vorbereiten.\n\nBitte, nehmt etwas davon als Zeichen unserer Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11262] = { id = 11262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingvar muss sterben!", description = "Von unserer gesamten Aufklärungstruppe bin nur ich übrig geblieben.\n\nDiese Vrykul sind erbarmungslose Kämpfer. Angesichts ihrer Zahl und brutalen Taktiken ist es unsere einzige Hoffnung, ihren Anführer zu erschlagen. Beten wir dafür, dass sie das ins Chaos stürzen wird.\n\nIngvar ist sein Name. Bringt mir seinen Kopf!", sourceObjective = "Dunkelläuferin Marrah möchte, dass Ihr Ingvar den Brandschatzer in Burg Utgarde tötet.", progress = "Wappnet Euch, {race}. Es gibt viel zu tun. Das ist sozusagen nur die Spitze des Eisbergs.", completion = "Ausgezeichnete Arbeit, {name}. Nun da sie keinen Anführer mehr haben, sollte unser Kampf gegen die Vrykul von größerem Erfolg gekrönt sein.\n\nDienste wie dieser dürfen nicht unbelohnt bleiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11263] = { id = 11263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gjalerbron fertig werden", description = "Meine Fernläufer, die überlebten und zurückkehren konnten, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung im Westen erwacht sind.\n\nEs ist ein verbotener Ort, der als Gjalerbron bekannt ist. Die Langläufer sagen, dass die Vrykul dort seltsame Rituale durchführen.\n\nWir können nicht gestatten, dass das so weitergeht.\n\nWärt Ihr bereit, uns weiter zu unterstützen? Werdet Ihr die Vrykul am Gjalerbron töten, bevor sie ihr Vorhaben beenden und uns hier angreifen?", sourceObjective = "Häuptling Aschtotem hat Euch gebeten, 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron zu töten. Kehrt im Anschluss zu ihm im Lager der Winterhufe zurück.", completion = "Ihr habt meinen Dank, {name}. Ich weiß, dass Ihr weder mir noch meinem Volk verpflichtet seid.\n\nWas Ihr über diesen Ort sagt, besorgt mich noch immer und ich spüre, dass unser Feldzug noch nicht beendet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11264] = { id = 11264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrogroßfürst Mezhen", description = "Die Toten sind am Gjalerbron und sie haben Nekromanten bei sich?\n\nWir müssen den Anführer dieser Nekrolords beseitigen.\n\nWie auch immer Ihr es fertig bringt, {name}, aber stellt sicher, dass Nekrogroßfürst Mezhen und sein Vorhaben ausgelöscht werden.\n\nWir können es uns nicht leisten, dass die Vrykul Erfolge verbuchen, was auch immer sie mit diesen Untoten anstellen!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", sourceObjective = "Tötet Nekrogroßfürst Mezhen. Kehrt danach zu Häuptling Aschtotem im Lager der Winterhuf zurück.", completion = "<Häuptling Aschtotem atmet erleichtert durch.>\n\nDas sollte den Druck etwas mildern.\n\n{name}, wieder und wieder habt Ihr Euren Wert für das Lager der Winterhufe bewiesen. Bitte, wählt etwas von unseren Gaben. Ich bestehe darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11265] = { id = 11265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Schlüsseln und Käfigen", description = "Das Wenige, was wir wissen, ist, dass die Vrykul im westlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsrituals sind.\n\nSie bedienen sich lebendiger Opfer für ihre Rituale.\n\n{name}, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nDie Vrykul stellen eine Gefahr für uns dar, und das Letzte, was wir gebrauchen können, sind noch mehr dieser seltsamen Kreaturen - oder schlimmer: dass sie Etwas erwecken, das noch böser ist...", sourceObjective = "Großmutter Ankha möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihr zurück, sobald Ihr damit fertig seid. Sie befindet sich im Lager der Winterhufe.", completion = "Mir fällt ein großer Stein vom Herzen, zu hören, dass Ihr erfolgreich wart. Und es bereitet mir Freude zu wissen, dass einige der Befreiten Taunka sind.\n\nBitte, nehmt dies als Gegenleistung für Eure Taten. Ich werde mich um die Wunden der Befreiten kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11266] = { id = 11266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne von Gjalerbron", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf das Lager der Winterhufe bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nCelea Frostmähne könnte in dieser Sache sicherlich behilflich sein. Überbringt ihr die Pläne. Ihr findet sie im Lager im Osten.", sourceObjective = "Übergebt die Angriffspläne von Gjalerbron an Celea Frostmähne. Sie befindet sich im Lager der Winterhufe.", progress = "Was?! Pläne für einen Angriff auf unser Lager?\n\nEIN ANGRIFF AUS DER LUFT?! EIN GROSSER WYRM?!!!", completion = "{name}, wir dürfen das nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11267] = { id = 11267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Frostwyrm und sein Meister", description = "Das hier zu mir zu bringen, war die richtige Entscheidung - Euer Instinkt hat Euch gut beraten. Meine Windreiter würden jedoch mit einem Drachen nicht fertig werden. Ihr müsst zum westlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nDer Frostwyrm könnte sich schon auf den Weg gemacht haben!\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Vernichtet die Kreatur, nachdem sie gelandet ist!\n\nUnd {name}: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", sourceObjective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Celea Frostmähne zurück. Sie befindet sich im Lager der Winterhufe.", progress = "Ist der Angriff abgewehrt? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Dieses Horn ist so kalt wie das Land... vielleicht sogar kälter!\n\nIhr habt das Lager der Winterhufe vor seinem sicheren Untergang bewahrt - was jedoch nicht heißen soll, dass wir hier noch viel länger bleiben werden. Was für ein eigenartiger Mann Ihr seid, {name}. Vielleicht ist Euer Volk von der anderen Seite des Ozeans im Grunde genommen doch nicht so böse.\n\nDas verlangt nach einer Belohnung. Was würdet Ihr vorziehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11268] = { id = 11268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wandelnden Toten", description = "Ihr wart uns eine riesengroße Hilfe, {name} - es gibt jedoch Etwas, das mir Sorgen bereitet: die sogenannte Geißel.\n\nDie Geister der Erde und Luft, des Wassers und des Feuers im Inneren der Welt würden zwar ihre Anwesenheit nicht dulden, scheinen jedoch nichts dagegen zu unternehmen. Wir werden dafür sorgen, dass man sich um sie kümmert!\n\nVielleicht ist es zu viel verlangt, aber ich hätte es gerne, dass Ihr zurück gen Westen nach Gjalerbron geht und die unnatürlichen Kreaturen der Geißel in diesem abscheulichen Nest vernichtet. Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht!", sourceObjective = "Tötet 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Bringt anschließend Nachricht Eures Erfolgs zu Großmutter Ankha im Lager der Winterhufe.", completion = "<Die Großmutter nickt zustimmend angesichts Eurer Taten.>\n\nIch danke Euch, {name}, Ihr habt das Richtige getan und uns damit ein wenig mehr Zeit verschafft, um unseren Abmarsch vorzubereiten. Wir werden schon bald gen Norden ziehen.\n\nIch bin zu alt - wenn es soweit ist und wir gehen, werde ich nicht alles mit mir tragen können. Hättet Ihr hiervon gerne etwas?", sourceObjectiveStatus = "unverified-source-field" }
quests[11269] = { id = 11269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daunen in letzter Minute", description = "Die Vorhut der Truppen der Allianz wird in ein paar Tagen eintreffen. Die Soldaten werden ihre Winterausrüstung erwarten und ich hab' noch nicht alle Umhänge angefertigt, die sie benötigen.\n\nFür das Futter der Umhänge verwende ich die Daunen von gefleckten Hippogryphen, doch mein Vorrat wird nicht ausreichen!\n\nIhr müsst mir helfen, {name}. Hauptmann Adams wird sich mir vorknüpfen, wenn die Umhänge nicht rechtzeitig fertig sind! Bringt mir alle Daunen, die Ihr dort draußen finden könnt. Sie werden von mausernden Hippogryphen, die in der Wildnis um das Fort herum anzutreffen sind, fallengelassen.", sourceObjective = "Gil Grisert möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", progress = "Habt Ihr mir ein paar Daunen gebracht? Ich könnte sie wirklich gut gebrauchen...", completion = "Gott sei Dank! Dies sollte genügen, um die bestellten Umhänge noch rechtzeitig herzustellen. Bevor die Truppen ankommen, werde ich natürlich keinen Schlaf finden, doch das ist noch immer um einiges besser, als Hauptmann Adams' Zorn ertragen zu müssen.\n\nIch kenne die Geschichten, die man über ihn erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11270] = { id = 11270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg ist die Hölle", description = "Wir beseitigen langsam die Überbleibsel von Sturmwinds Nordflotte, die an dieser Küste vor Anker lag. Die Leichen im Westen sind ein Zeichen dafür, wie brutal die Konfrontation gewesen ist.\n\nEs berührt zwar meinen feinen Sinn für Ästhetik nicht im Geringsten, stellt jedoch eine Gefahr für unser aller Leben dar.\n\nIm Reich des Lichkönigs sind die Toten eine Waffe, die jederzeit gegen uns verwendet werden kann. Nehmt diese Fackel - Ihr werdet dafür sorgen, dass das nicht geschieht.", sourceObjective = "Hochexekutor Anselm im Hafen der Vergeltung möchte, dass Ihr mithilfe der brennenden Fackel 10 der Leichen, die westlich des Orts herumliegen, verbrennt.", completion = "Ich bin froh, dass Ihr Befehle befolgen könnt. Wenn man mir ein Kupferstück für jeden arroganten Narren in glänzender Rüstung gäbe, der hierher kommt und denkt, dass er tun und lassen kann, wie ihm beliebt... tja, dann hätte ich schon ein paar Goldstücke beisammen.\n\nNun, da Ihr einen gewissen Grad an Disziplin bewiesen habt, hätte ich ein paar Aufgaben anzubieten, die für jemanden wie Euch besser geeignet wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[11271] = { id = 11271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hastige Vorbereitungen", description = "Die Daunen des gefleckten Hippogryphen werden von meinem Volk hoch geschätzt und werden bei uns für alles verwendet - von der Pfeilmacherei, bis hin zu zeremoniellen Gewändern. Wir bereiten uns darauf vor, diesen Posten zu verlassen, also ist das meine letzte Chance in dieser Saison, sie zu sammeln.\n\nMit Eurer Hilfe werde ich genug zusammenbekommen, um jedem die nötige Ausrüstung für den Marsch durch die Hügel bieten zu können. Die Bedingungen verschlechtern sich sehr schnell dort oben und jederzeit könnte ein Sturm ohne Vorwarnung aufziehen.\n\nDie Daunen liegen rings um den Posten herum auf dem Boden.", sourceObjective = "Ahota Weißfrost im Lager der Winterhufe möchte, dass Ihr ihm 10 Büschel Daunen eines gefleckten Hippogryphen bringt.", progress = "Habt Ihr schon ein paar Daunen gesammelt?", completion = "Dank Eures Beitrags werden wir gut auf die Reise vorbereitet sein. Ich habe nicht viel, das ich Euch für Eure Hilfe anbieten könnte, aber ich werde Euch etwas aus meiner übrigen Kampfausrüstung aussuchen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11272] = { id = 11272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rechnung begleichen", description = "Glaubt dieser Elfenprinz etwa, dass er in meine Stadt kommen, meine Königin beleidigen, meine Leute töten und mit all dem davonkommen kann? Glaubt er, dass wir untätig zusehen werden, wenn Utgardes Horden sich auf einen Angriff vorbereiten?\n\nNicht in einer Million Jahre.\n\nIhr werdet direkt nach Utgarde gehen und ihn töten. Ich will, dass Arthas von unserer Ankunft erfährt und weiß, dass wir es ernst meinen.\n\nMeldet Euch bei der Dunkelläuferin Marrah in der Burg Utgarde, wenn Ihr die Tat vollbracht habt, und sie wird sich um eventuelle Folgen kümmern.", sourceObjective = "Hochexekutor Anselm möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", progress = "Habt Ihr etwas zu berichten, {name}?", completion = "Rache ist süß. Und dies ist nur ein Vorgeschmack dessen, was Arthas noch bevorsteht.\n\nEr wird früh genug das bekommen, was er verdient hat. Dann und nur dann werde ich glücklich sterben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11273] = { id = 11273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Menschenliga", description = "Wir waren kurz davor, einen sensationellen archäologischen Fund zu machen, als wir von diesen Monstern angegriffen wurden! Leider war ich der Einzige, der es zurück nach Valgarde schaffte. Nun weiß ich nicht, ob meine Mannschaft tot oder am Leben ist, aber die Artefakte, die wir damals ausgruben, müssen gefunden werden!\n\nFalls Ihr nach Wyrmskol gehen solltet, würdet Ihr dann nach meiner Mannschaft Ausschau halten? Wenn es noch Hoffnung gibt, dass die Informationen geborgen werden können, müssen wir versuchen, sie zurückzubekommen!\n\nSucht zuerst nach Pulroy. Ihn habe ich als letzten gesehen, bevor ich flüchtete.", sourceObjective = "Sucht Wyrmskol nach Pulroy ab.", completion = "Ihr habt Pulroy gefunden - jedoch ein wenig zu spät wie es aussieht.\n\nWährend Ihr den Leichnam genauer betrachtet, fällt Euch ein Tagebuch auf, das fest von Pulroys totenstarrer Hand umklammert wird. Ihr seht Euch das Buch genauer an und stolpert über Etwas, das wie das Gekritzel eines sterbenden Zwergs aussieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11274] = { id = 11274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zedd ist wahrscheinlich tot", description = "An den Finder dieses Tagebuchs:\n\nDiese blutrünstigen Scheusale haben sich in den Ruinen von Wyrmskol eingenistet. Was genau sie wollen und wieso sie hier sind, ist ein Rätsel. Auf jeden Fall sind die Artefakte nicht sicher, solange sich diese Menschenbestien hier herumtreiben.\n\nZedd und ich haben etwas entdeckt, als wir uns versteckt haben: eine Glyphe, mit der man die Schrifttafeln entziffern kann! Unglücklicherweise wurden Zedd und ich letzte Nacht voneinander getrennt. Er hatte die Glyphe. Glorenfeld und Daegarn hatten die Schrifttafeln bei sich. Wo sie sind, weiß ich nicht...\n\nFindet Zedd.\n\n-Pulroy", sourceObjective = "Sucht Wyrmskol nach Zedd ab.", completion = "Ihr habt Zedd gefunden. Ihr seid zwar kein Doktor, aber die Prognose für Zedd würde sicherlich negativ ausfallen.\n\nEs sieht so aus, als hätten sie versucht, ihn an die Worge zu verfüttern. Scheußlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11275] = { id = 11275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn schnitzen", description = "Mein Volk jagt schon seit Generationen die Riesenyeti in diesen Hügeln und dieses Jahr werde ich zum ersten Mal daran teilnehmen. Es wird wahrscheinlich die letzte Jagd sein, bevor wir den Posten für immer verlassen.\n\nUm mich auf die Jagd vorzubereiten, muss ich ein lautes Blashorn aus den Geweihen der Frosthornböcke herstellen, die durch die verschneite Gegend in der Nähe unseres Lagers streifen. Die Ältesten meinen, dass der Ton des Horns dem Paarungsruf der weiblichen Yetis ähnelt, aber ich hab' da so meine Zweifel.\n\nBringt mir die besten Hörner der Frosthornböcke, die Ihr finden könnt, {name}, und ich werde mir eines davon aussuchen.", sourceObjective = "Nokoma Schneeseher im Lager der Winterhufe möchte, dass Ihr ihr 6 unbeschädigte Widderhörner bringt.", progress = "Habt Ihr brauchbare Hörner finden können?", completion = "All diese Hörner sind großartig, {name}. Lasst sie mich einmal näher betrachten, damit ich mir dasjenige aussuchen kann, welches ich auf der Jagd benutzen werde.\n\nDen Rest gebe ich dann den Handwerkern, damit sie daraus etwas schnitzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11276] = { id = 11276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und da waren es Zwei...", description = "Ihr untersucht Zedd, doch von der Glyphe fehlt jede Spur. Nachdem Ihr überall in der Gegend nachgesucht habt, entdeckt Ihr ein paar auf den Boden geschriebene Zeichen:\n\n\"Glor und Dae in den Katakomben. Haben Glyphe und Tafeln.\"\n\nVielleicht solltet Ihr Euch in die Katakomben im Norden begeben und nach Glorenfeld und Daegarn suchen. Die Brücke über die Worgengrube wird Euch direkt zum Tunnel und zum Eingang der Katakomben führen.", sourceObjective = "Sucht in den Katakomben von Utgarde nach Glorenfeld.", completion = "Wurde verdammt noch mal Zeit! Pulroy und Zedd sind tot.\n\nUnd Daegarn...\n\n<Glorenfeld schüttelt den Kopf.>\n\nEr wurde vom Anführer der Drachenschinder gefangen genommen und Tief ins Innere der Katakomben verschleppt. Ich konnte mitanhören, wie dieser zu groß geratene Bastard etwas über ein Opfer an den \"Schreckenskönig\" sagte.\n\nDaegarn hat die Glyphe in seinem fettigen Bart versteckt.\n\nWie bitte? Zwerge verstecken immer Dinge in ihrem Bart!", sourceObjectiveStatus = "unverified-source-field" }
quests[11277] = { id = 11277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefen des Anrüchigen", description = "Sie halten Daegarn in 'nem Käfig im großen Kampfring gleich hier in der Nähe gefangen. Soviel ich mitbekommen habe, lassen die Drachenschinder ihre Gefangen gegen ihre stärksten Gladiatoren kämpfen. Die Verlierer werden danach ins untere Geschoss geworfen, um dort von Nekromanten der Geißel in Ghule verwandelt zu werden! Grauenhaft ist das!\n\nAber eins nach dem anderen! Die Tafeln liegen überall im Kerker verstreut. Lasst uns die erstmal einsammeln, bevor Ihr versucht, den Helden zu spielen.", sourceObjective = "Glorenfeld in den Katakomben von Utgarde möchte, dass Ihr 10 Wyrmskoltafeln einsammelt.", progress = "Überprüft jede Nische und Ritze!", completion = "Gut gemacht, mein Freund. Da wir nun die Tafeln in Händen halten, können wir versuchen Daegarns Leben zu retten und die Glyphe zurückzubekommen, damit wir endlich das Geheimnis dieser uralten Relikte lüften können!\n\nIch behalte erst einmal die Tafeln und Ihr befreit Daegarn.", sourceObjectiveStatus = "unverified-source-field" }
quests[11278] = { id = 11278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Valgarde", description = "Was für 'ne Schande, dass wir zwei unserer besten Zwerge bei der Ausgrabung der Relikte verloren haben. Sie gaben ihr Leben hin, um diese Kunde sicher zu verwahren.\n\n<Glorenfeld wickelt die Glyphe und Tafeln in einen Lumpen Stoff ein.>\n\nBringt sie nach Valgarde zurück. McSorf wird wissen, was mit diesem Fund zu tun ist.\n\nWas mich angeht? Ich werde alleine schon zurechtkommen - bin schließlich in einem Stück bis hierhergekommen!", sourceObjective = "Bringt Glorenfelds Päckchen zu Beltrand McSorf im Hafen von Valgarde.", progress = "Ihr seid zurück!", completion = "Diese Tafeln zu sortieren, wird einige Zeit dauern. Alles, was ich bei einer ersten Untersuchung herausfinden konnte, ist, dass das, was auch immer einmal hier gewesen ist, ein Vorfahre der Menschen war. Diese Vrykuldinger haben sie wahrscheinlich bis auf den letzten umgebracht. Wie immer dem auch sei, wir werden mehr wissen, sobald ich diese Relikte geordnet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11279] = { id = 11279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Eier und Welpen", description = "Diese neue Seuche, an der wir gerade arbeiten, ist formidabel. Ich denke, wir sollten ihre Tests ausweiten.\n\nWie wäre es damit, sie an den Proto-Welpen auszuprobieren?!\n\nStellt Euch nur die Möglichkeiten vor. Wir könnten nicht nur Humanoide, sondern alle Kreaturen anstecken!\n\nHier, ich habe mir einen Seuchenkanister für den richtigen Zeitpunkt aufbewahrt - und Ihr scheint mir die richtige Person zu sein.\n\nBesprüht damit die Eier in der Glutstätte im Nordwesten und fangt anschließend ein paar Exemplare der ausgeschlüpften verseuchten Proto-Welpen ein.", sourceObjective = "Seuchenbringer Tillinghast möchte, dass Ihr 10 Exemplare verseuchter Protowelpen einsammelt und sie anschließend bei ihm abliefert. Er befindet sich in Neu-Agamand.", progress = "Wie soll ich ohne diese Proben herausfinden, ob dieser letzte Stamm unseres Erregers auf alle möglichen Kreaturen angewandt werden kann?", completion = "Was?! Nein, das kann nicht stimmen.\n\nVERDAMMT!\n\nDiese Version der Seuche scheint die Protowelpen bis auf den grünen Leuchteffekt nicht wirklich zu beeinflussen!\n\nMein Traum davon, alles was wir berühren mit der Seuche anzustecken, scheint sich in Luft aufgelöst zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11280] = { id = 11280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconis Gastritis", description = "Wartet, da kommt mir eine Idee! Was wäre, wenn die Welpen nur deswegen nicht gestorben sind, weil sie auf die Schale der Eier gesprüht wurde?\n\n{name}, wir müssen die Seuche irgendwie in sie hineinbekommen!\n\nIch weiß! Ich habe hier ein wenig verseuchtes Fleisch. Nehmt es, geht zur Glutstätte und bringt sie dazu, es zu fressen!\n\nHalt, wir denken hier nicht groß genug. Bringen wir einen der Protodrachen, die hoch am Himmel fliegen, dazu, herunterzukommen und es zu essen.\n\nGenau!\n\nBleibt in der Nähe des Fleischs und betrachtet das Geschehen. Ja, es könnte Euch angreifen - aber das ist nun mal der Preis des Fortschritts.", sourceObjective = "Seuchenbringer Tillinghast in Neu-Agamand möchte, dass Ihr mit Tillinghasts verseuchtem Fleisch einen Protodrachen anlockt und verfolgt, wie er auf das gefressene Zeug reagiert.", completion = "NEEEEIIIIIIIN!\n\n<Der Seuchenbringer fängt an zu weinen.>\n\nAlle meine Hoffnungen... alle meine Träume - zerstört!\n\nGeht, {name}. Geht und überlasst mich meinem Trübsal. Ich bin ein Nichts.\n\nHier, Ihr könnt ebenso gut all mein Hab und Gut an Euch nehmen. Wenn der Rest der Apotheker von meinem Versagen erfährt, dann bin ich sowieso erledigt und werde es nicht mehr brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11281] = { id = 11281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ruf der Natur nachahmen", description = "Die grobe Form des Horns ist nun fertig, doch bevor ich die traditionellen Muster in die Oberfläche kerbe, möchte ich sichergehen, dass es auch funktioniert. Ahota hat mir gesagt, dass er seine Hörner immer am Fuße des gefrorenen Wasserfalls nördlich des Lagers testet. Er hat mir auch gesagt, dass unsere Jäger die Akustik des gefrorenen Wassers schon seit Generationen zu diesem Zweck verwenden. Ich kann es kaum erwarten, noch mehr darüber zu erfahren!\n\nWerdet Ihr mir dabei helfen, das Horn zu testen? Wenn ich alles richtig gemacht habe, dann werdet Ihr sogar einen Yeti anlocken - also macht Euch darauf gefasst! Bringt das Horn zurück, sobald Ihr es getestet habt.", sourceObjective = "Testet das geschnitzte Horn und kehrt anschließend mit den Ergebnissen zu Nokoma Schneeseher im Lager der Winterhufe zurück.", completion = "<Nokoma hört sich Euren Bericht über den Test an.>\n\nDa bin ich erleichtert, dass das Horn so gut funktioniert hat... vielleicht etwas zu gut, wenn das, was Ihr sagt, stimmt. Seid Ihr Euch sicher, dass das Biest gesprochen hat? Wenn das wahr sein sollte, dann bin ich mir nicht sicher, ob ich mit auf die Jagd gehen kann. Ich werde mit Häuptling Aschtotem darüber sprechen müssen.\n\nKann sein, dass dieses Horn am Ende nur dekorativen Zwecken dienen wird - was seinen Wert jedoch nicht mindert. Vielen Dank für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11282] = { id = 11282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Angst", description = "Wenn du so viele Kämpfe gemacht hast wie Gorth, dann weißt du, dass man den Bösewichten sehr viel Angst machen muss, wenn man sie gut verhauen will!\n\nDiese Vrykul aber keine Angst. Du machst einen nieder, aber sofort kommt ein anderer... und der brüllt dann lauter und hat eine größere Waffe als der davor.\n\nDas Einzige, wovor Vrykul Angst haben, ist, wenn wir den größten und bösesten Vrykul von allen töten.\n\nGeh und murks so lange Winterskorn auf der anderen Seite der Blockade, bis Vrykulhelden auftauchen! Du machst sie dann alle tot und bohrst Flagge der Königin in sie hinein. Die müssen lernen, Angst zu haben!", sourceObjective = "Gorth möchte, dass Ihr Ulf den Aderlasser, Oric den Elenden und Gunnar Thorvardsson tötet und das Banner der Verlassenen durch ihre Körper rammt. Erschlagt solange Vrykul auf der anderen Seite der Blockade der Verlassenen, bis die Drei auftauchen.", completion = "Du hast dort drüben ein paar gute Murkser gemacht. Ich habe gesehen, wie Vrykul fallen und mit Sylvanas Flagge gestochen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11283] = { id = 11283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahl der Toten in Quälheim", description = "Vrykul kommen aus dem Ort da im Westen - hört gar nicht mehr auf und kein Ende in Sicht!\n\nGorth hat da eine Idee. Du gehst HINEIN in die Stadt und murkst Winterskorn. DANN werden sie nicht mehr rüberkommen!", sourceObjective = "Unteroffizier Gorth möchte, dass Ihr nach Quälheim geht und 16 Vrykul des Winterskornstammes tötet.", completion = "Du musst viel Übung im Murksen haben. Du bist fast so gut wie Gorth!", sourceObjectiveStatus = "unverified-source-field" }
quests[11284] = { id = 11284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Yeti von nebenan", description = "Wenn die Schildwachen mir schon nicht helfen können, würdet Ihr? Ich bin der Vorarbeiter der Mine hinter der Brücke dort. Meine Männer schürfen Erz für die Waffen, die unsere Expeditionstruppe brauchen wird, um einen Pfad durch die Grizzlyhügel zu schlagen.\n\nEin riesiger Yeti ist in die Mine eingedrungen und blockiert den Tunnel, den wir brauchen, um weiter zu arbeiten! Wir haben versucht, ihn durch Schreie zu verscheuchen und aus seinem Unterschlupf zu vertreiben, aber nichts hat geholfen.\n\nVielleicht könntet Ihr ihn wecken, mit einer Portion Fleisch von den Frosthornböcken aus den schneebedeckten Gegenden um die Stadt herum? Bitte... Wir sind verzweifelt!", sourceObjective = "Vorarbeiter Colbey bei Fort Wildervar möchte, dass Ihr Schmetterhorn besiegt.", completion = "Ihr habt es geschafft? Beim Licht, Ihr seid ein wandelndes Wunder! Ich hatte mich schon mit dem Gedanken abgefunden, Hauptmann Adams persönlich erklären zu müssen, warum die Waffen seiner Männer nicht rechtzeitig fertig geworden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11285] = { id = 11285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quälheim muss brennen!", description = "Die Winterskorn töten vielleicht nicht genug. Vielleicht verbrennen wir einfach auch ihre Häuser! Eh.... und ihre Brücken. Wir sollten sichergehen und die ganze Stadt mit Feuer kaputt machen!\n\nDu nimmst diese Fackel. Geh nach Quälheim, im Westen, und verbrenn ALLES! Wird ihnen eine Lehre sein.", sourceObjective = "Unteroffizier Gorth will, dass Ihr nach Quälheim geht und Gorths Fackel benutzt, um 1 Behausung der Winterskorn, 1 Wachturm der Winterskorn, 1 Brücke der Winterskorn und 1 Kaserne der Winterskorn in Brand zu stecken.", completion = "Ich schätze, du hast alles mit Feuer kaputt gemacht. Ich seh' ein paar Stellen, die nicht brennen... aber für Gorth ist das nah genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[11286] = { id = 11286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Artefakte des Stählernen Tores", description = "Ich bin aus einem anderen Grund hier in dieser Gegend - ein alter Freund hat mich in meinen Träumen gerufen. Es bringt jedoch mein Blut zum Kochen, mit ansehen zu müssen, wie diese kleinen Dinger mit ihren Maschinen ein großes Loch in den Boden graben.\n\nSo wie ich das sehe, graben diese sogenannten Zwerge Artefakte aus - Artefakte, die wichtige Zeugnisse unserer Vergangenheit sein könnten.\n\nIch möchte, dass Ihr dort hinunter geht und diese Dinger zu mir bringt. Lasst Euch von keinem dieser Zwerge aufhalten.", sourceObjective = "Weiser Nebelläufer möchte, dass Ihr 10 Artefakte vom Stählernen Tor aufsammelt. Kehrt zu ihm zurück, sobald Ihr alle habt. Er befindet sich am Stählernen Tor.", progress = "Wie viele Artefakte habt Ihr an diesem Stählernen Tor finden und aufsammeln können?", completion = "<Der Weise knurrt als Zeichen seiner Anerkennung für das, was Ihr auf sein Geheiß unternommen habt.>\n\nVielleicht werde ich mir schon bald die Zeit nehmen können, um diese Artefakte zu untersuchen und herauszufinden, welche Bedeutung sie für uns haben.\n\nEs gibt jedoch wichtigere Angelegenheiten, um die wir uns jetzt kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11287] = { id = 11287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Weisen Nebelläufer", description = "<Verehrter/Verehrte:c> {class}, ich mache mir zunehmend Sorgen um meinen Sohn Weiser Nebelläufer - er ist nun schon so lange fort. Das Land ist grausam und tödlich.\n\nEr sprach von einer immer wiederkehrenden Vision und brach dann mit einer kleinen Gruppe Fernläufer in Richtung Westen auf, um ihrem Ursprung nachzugehen. Er erwähnte einen Namen - 'Stählernes Tor', glaube ich, war es.\n\nWerdet Ihr nach ihm suchen? Ich möchte sichergehen, dass ihm auch nichts Schlimmes zugestoßen ist.", sourceObjective = "Großmutter Ankha hat Euch gebeten nachzusehen, in welcher Verfassung sich der Weise Nebelläufer befindet. Sie glaubt, dass er sich am oder in der Nähe des Stählernen Tores befindet.", completion = "Meine Mutter soll sich keine Gedanken um meine Sicherheit machen. Ich danke Euch jedoch dafür, dass Ihr gekommen seid, Fremder.\n\nDa Ihr nun schon einmal da seid - könntet Ihr mir vielleicht bei ein paar Angelegenheiten helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11288] = { id = 11288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das strahlende Licht", description = "<Ares liegt im Sterben. Er versucht zu sprechen und keucht.>\n\nIch bin ein Abgesandter des Argentumkreuzzugs und wurde mit einer heiligen Aufgabe beauftragt.\n\nUnsere Streitkräfte in den Pestländern wurden dezimiert. Mit dem Licht der Morgendämmerung, läuterten sie das Artefakt, machten es wieder rein. Die Erlösung... so viele gaben ihr Leben für sie.\n\nDoch es gibt immer noch Hoffnung... noch ist Zeit.\n\nDas Artefakt wurde in die Grube der Gefallenen geschleudert - tief unter uns, von den grausamen Toten bewacht.\n\n<Ares' Körper erglüht in einem blendenden Licht.>\n\nDas - Licht - wird - Euch - beschützen.", sourceObjective = "Ares der Schwurgebundene in den Katakomben von Utgarde möchte, dass Ihr das geheiligte Artefakt bergt.\n\nDiese Aufgabe ist zeitlich begrenzt.", progress = "<Ares ist bewusstlos.>", completion = "Ihr fühlt Euch dazu verpflichtet, das heilige Schwert neben Ares zu legen.\n\nNachdem Ihr dies getan habt, werdet Ihr noch einmal vom Licht geblendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11289] = { id = 11289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Ehre geleitet", description = "<Ares lächelt.>\n\nEhre dem Licht. Ihr habt es geschafft!\n\n<Ares hustet.>\n\nNehmt das Artefakt und bringt es nach Valgarde zurück. Lord Irulon Wahrklinge erwartet dessen Rückkehr.\n\nKämpft mit Ehre. Immer - Ehre.\n\n<Ares stirbt.>", sourceObjective = "Bringt das geheiligte Artefakt zu Lord Irulon Wahrklinge zurück. Er befindet sich in Valgarde.", progress = "Beim Licht!", completion = "Viele Männer und Frauen mussten ihr Leben lassen, um dieses Schwert zu bergen. Ach, ich fürchte, dass der tapfere Ares nicht der Letzte sein wird.\n\nDoch aus Euren Taten spricht das Licht, o Held. Dieses heilige Schwert wird Lord Tirion Fordring höchstpersönlich tragen. Selbst jetzt arbeitet sich der Argentumkreuzzug zur Eiskrone vor. Lord Fordring hat geschworen, dass er die Mauern dieser verfluchten Stätte mit seinen eigenen Händen niederreißen wird! Und mit dem Schwert könnte er sich sogar gegen den Lichkönig behaupten.\n\nLord Fordring bleibt unsere größte Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11290] = { id = 11290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der Drachenschinder", description = "Wir konnten zwar nur sehr wenig über Ingvars Aufenthaltsort erfahren, doch was wir wissen, ist, dass Yanis in einer Höhle in der Nähe der Worggrube in Wyrmskol wohnt.\n\nInformationen, die wir von den geretteten Soldaten erhalten haben, deuten darauf hin, dass Yanis die Schlachtpläne der Drachenschinder bewacht.\n\nIch möchte, dass Ihr zurück nach Wyrmskol geht und diese Schlachtpläne beschafft.", sourceObjective = "Vizeadmiral Keller im Hafen von Valgarde im Heulenden Fjord möchte, dass Ihr ihm die Schlachtpläne der Drachenschinder bringt.", progress = "Habt Ihr die Schlachtpläne der Drachenschinder bei Euch?", completion = "<Vizeadmiral Keller überfliegt kurz die Pläne.>\n\nHervorragend! So wie es aussieht, gibt es noch viel mehr Vrykuldörfer im Fjord. Ein anderer Vrykulstamm bereitet sich auf einen Angriff auf Westwacht vor. Verdammt! Soweit ich es beurteilen kann, ist es vielleicht schon zu spät. Wir haben seit Tagen keine Nachricht mehr aus Westwacht erhalten. So oder so - wir müssen Westwacht warnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11291] = { id = 11291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Westwacht!", description = "<Vizeadmiral Keller rollt die Schlachtpläne aus.>\n\nWir wissen nun genug, um Valgarde weiterhin zu schützen. Ihr müsst diese Schlachtpläne nach Westwacht bringen. Westwacht befindet sich oben auf den Klippen im Westen des Fjords. Sprecht mit der Flugmeisterassistentin Emilune Winterwind. Sie wird Euch auf einen Greifen in Richtung Westwacht setzen.\n\nFindet Hauptmann Adams, sobald Ihr angekommen seid. Er hat dort das Sagen. Adams wird wissen, was mit diesen Plänen anzufangen ist.", sourceObjective = "Bringt die Schlachtpläne der Drachenschinder zu Hauptmann Adams. Er befindet sich in Westwacht im Heulenden Fjord.", progress = "Valgarde wurde nicht vernichtet? Welch Überraschung.\n\nMuss an unserer Hilfe gelegen haben. Keller hat damit sicherlich nichts zu tun.", completion = "<Hauptmann Adams nimmt Euch die Pläne ab.>\n\nIch freue mich, dass Ihr Euch dazu entschlossen habt, hierher zu kommen. Meine Berater und ich werden diese Pläne eine Zeitlang untersuchen. In der Zwischenzeit können wir jede Hilfe gebrauchen, die wir kriegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11292] = { id = 11292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Schwachen Jagd machen", description = "Es freut mich, Euch kennenzulernen. Ich komme von den Grizzlyhügeln, um mit Euresgleichen Geschäfte zu machen. Mein Volk unterhält dort einen großen Außenposten. Ihr wärt gut damit beraten, ihn zu besuchen, falls Ihr nach Norden ziehen solltet.\n\nIch habe in den Wäldern und Schneegebieten in der Gegend Fallen aufgestellt. Mit dem Fleisch und Fell der Kreaturen, die in die Falle gehen, werde ich genug haben, um mit dem Stadtvolk Handel betreiben zu können.\n\nSolltet Ihr gewillt sein, mir dabei zu helfen die gefangene Beute zu sammeln, könnte ich Euch einen Teil meines Gewinns anbieten. Seid jedoch gewarnt: Dort draußen seid Ihr nicht das einzige Raubtier.", sourceObjective = "Fallensteller Jethan in Fort Wildervar möchte, dass Ihr ihm aus 8 Fallen gefangene Beute bringt.", progress = "Ich hoffe, Ihr seid nicht mit leeren Händen zurückgekommen. Ich dachte, wir hätten ein Abkommen.", completion = "<Fallensteller Jethan begutachtet die Kreaturen, die Ihr ihm gebracht habt.>\n\nGut gemacht. Einige davon werden einen besseren Preis erzielen als andere - aber ich sollte genug haben, um mit den Ansässigen handeln zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Gerstenbräus!", description = "Lasst alle wissen, dass die Gerstenbräus auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält! Ich werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder und Widderrennzügel für 4 Minuten borge. Verwendet die Zügel, um ihn anzutreiben, aber achtet drauf, ihn nicht zu sehr zu erschöpfen.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gut gemacht! Die Ankündigung wird unser Geschäft bestimmt ins Rollen bringen.\n\nWir hatten Euch ja auch eine Belohnung versprochen, hier ist sie. Die Gerstenbräus halten ihr Wort.\n\nOh, wenn Ihr die gute Kunde von den Gerstenbräus noch einmal verbreiten wollt, könnt Ihr gerne an einem anderen Tag wieder kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Donnerbräus!", description = "Wir müssen die Leute wissen lassen, dass die Donnerbräus ihre Bitte nach gutem Gebräu erhört haben. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält!\n\nWir werden Euch das Ganze etwas erleichtern, indem wir Euch einen Rennwidder UND passende Zügel 4 Minuten lang borgen.\n\nAchtet darauf, nicht zu schnell zu reiten, denn Ihr werdet keine Apfelkisten in Eisenschmiede finden und wir können es nicht riskieren, den Marktschreiern der Gerstenbräus behilflich zu sein.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gute Arbeit! Das wird es diesen arroganten Gerstenbräus aber zeigen.\n\nNa dann, wir haben Euch eine Belohnung versprochen und hier ist sie. Wir Donnerbräus belohnen Euch mit Preisen, die Gerstenbräus belohnen Euch mit faulen Sprüchen und falschen Versprechen.\n\nIhr habt Euch weise entschieden.\n\nWenn Ihr auch weiterhin den richtigen Weg einschlagen wollt, dann kommt an einem anderen Tag noch einmal vorbei und verbreitet die Kunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11295] = { id = 11295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offensive beginnt", description = "Niemand scheint sehr viel über die Vrykul zu wissen. Unsere Aufzeichnungen deuten darauf hin, dass sich seit Jahrhunderten nichts mehr in ihren Landen geregt hat. Dennoch sind sie ausgerechnet jetzt, wo wir gegen Arthas ins Feld ziehen, hier.\n\nDie Karte, die Ihr geborgen habt, verdeutlicht, dass wir sie besiegen müssen, wenn wir unsere Truppen tiefer ins Landesinnere von Nordend bewegen wollen.\n\nEiner meiner besten Unteroffiziere, eine Monstrosität namens Gorth, wacht über die Blockade in der Nähe des Aufzugs. Unterstützt ihn dabei, einen Präventivschlag gegen Quälheim vorzunehmen. Wenn die Vrykul einen Angriff starten, dann wird er von dort aus geführt.", sourceObjective = "Sprecht mit Unteroffizier Gorth bei der Blockade in der Nähe des Aufzugs westlich vom Hafen der Vergeltung im Heulenden Fjord.", completion = "Du kommst, um zu helfen? Gut... gut...\n\nGorth wurde schon müde vom ständigen Vrykulmurksen. Hilfe ist gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[11296] = { id = 11296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen im Bruchwald", description = "Irgendetwas - höchstwahrscheinlich waren es die wandelnden Toten der Geißel - hat die Kreaturen in dieser Gegend in Unruhe versetzt.\n\nAls wir den Weisen hierher eskortierten, verloren wir den Großteil unseres Jagdtrupps an die Bruchwitwen, die im Norden des Bruchwaldes vorkommen.\n\nIch muss hier bleiben und die Wenigen, die von uns übrig geblieben sind, beschützen - doch Ihr... Ihr könntet nachsehen, ob meine Fernläufer noch immer am Leben sind. Sie sind in Bruchwitwenkokons eingeschlossen.\n\nWürdet Ihr das tun, <Fremder/Fremde>?", sourceObjective = "Fernläufer Himmelswolke möchte, dass Ihr 7 seiner Fernläufer der Winterhufe befreit. Meldet Euch wieder bei ihm, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich am Stählernen Tor.", completion = "Das war eine sehr mutige Tat, {class}. Ich wusste nicht, dass jemand Eures Volkes zu solch einem selbstlosen Akt fähig ist.\n\nDas nächste Mal werde ich die Warnungen meiner Ältesten beherzigen und einen großen Bogen um den Bruchwald machen. Ich rate Euch, dasselbe zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11297] = { id = 11297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Eindringlingen Ausschau halten", description = "Selbst die Erde kann die Flut des Todes nicht eindämmen, die über sie hinwegschwappt. Leichen wandeln umher und verbreiten Fäulnis mit alarmierender Geschwindigkeit.\n\nEine kleine Expedition hat sich auf den Weg die westlichen Klippen hoch gemacht und in der Nähe der Flüsterschlucht ihr Lager aufgeschlagen. Doch seht für Euch selbst, {name}. Versucht herauszufinden, aus welchem Grund sie dort sind, und haltet sie davon ab, ihre Gifte in unser Land zu bringen. Reist vom Posten aus gen Südwesten in Richtung der Klippen, die den westlichen Strand säumen. Ihr Lager wird sich westlich des Ausgrabungsortes am Stählernen Tor befinden.", sourceObjective = "Sprecht mit Apotheker Malthus im Apothekerlager.", completion = "Ah, ja, das zurückgezogene Bisonvolk des Nordens. Ich habe gesehen, wie sie herumschleichen - im Glauben, man würde sie nicht sehen. Ich nehme einmal an sie bilden sich ein, dass dieses Land ihnen gehört? Nun, das ist nur eine der vielen Veränderungen, die sich in Kürze ergeben werden.\n\nIch habe zwar nicht damit gerechnet, Gesellschaft zu bekommen, aber wenn Ihr schon einmal im Auftrag des Narren hier seid, könnt Ihr Euch genauso gut nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11298] = { id = 11298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist in dem Gebräu?", description = "Im Südosten gibt es einen Landstrich namens Flüsterschlucht. In ihr wimmelt es nur so von verrückt gewordenen Forscherligisten! Sie griffen unsere Karawane an, als wir durch diese Gegend zogen, und außerdem attackieren sie ununterbrochen unsere Jagdtrupps.\n\nIch muss wissen, was der Grund dieses Wahnsinns ist! Ich vermute einmal, dass was auch immer sie aus diesen Fässchen, die überall in der Schlucht verstreut herumliegen, trinken, zu ihrem Wahnsinn beiträgt. Ich möchte, dass Ihr die Fässchen dieser Zwerge stehlt, während sie mit Schürfen beschäftigt sind.", sourceObjective = "Apotheker Malthus im Apothekerlager möchte, dass Ihr ihm 5 zwergische Fässchen bringt.", progress = "Habt Ihr nun die Fässchen bei Euch oder nicht?", completion = "<Der Apotheker schenkt sich einen Krug voll des Gebräus ein.>\n\nTja, zum Wohl!", sourceObjectiveStatus = "unverified-source-field" }
quests[11299] = { id = 11299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Richturteils", description = "Ihr habt vielleicht schon den Raum, in dem Daegarn gefangen gehalten wird, gesehen, als Ihr dabei wart, die Tafeln zu sammeln. Er befindet sich am Ende dieses Korridors und dann ein paar Stufen hinunter. Daegarn befindet sich in dem Raum am Ende dieser Treppen - fest hinter Gittern verschlossen!\n\nBegebt Euch dorthin und findet ihn. Vielleicht könnt Ihr wenigstens die Glyphe von ihm bekommen.", sourceObjective = "Findet Daegarn. Sucht im Ring des Richturteils im Inneren der Katakomben von Utgarde.", completion = "Jap - Ihr habt mich gefunden. Jippi-jei!\n\nUnd nein, ich hab' die Glyphe nicht. Mein Bart war das Erste, was diese Biester durchsucht haben! Oluf hat sie jetzt - er ist der Häuptling der Gladiatoren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11300] = { id = 11300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigende Niederlage im Ring", description = "Oluf wird erst dann rauskommen, wenn Ihr die anderen Gladiatoren besiegt habt. Das ist so gut wie unsere einzige Möglichkeit, an diese Glyphe heranzukommen. Schnappt Euch Eure beste Klopp-Ausrüstung und dann ab mit Euch in den Ring des Richturteils und auf geht's. Geht zu Glorenfeld drüben am Eingang zu den Katakomben und gebt ihm die Glyphe, falls Ihr sie zurückbekommen könnt.\n\nIch? Macht Euch um mich keine Sorgen! Wir sind kurz davor, das fehlende Bindeglied zu entdecken, das die Herkunft der Menschheit klären wird.", sourceObjective = "Besiegt die Gladiatoren im Ring des Richturteils und stellt Euch Oluf dem Gewalttätigen. Besiegt Oluf und nehmt ihm die uralte Glyphe ab.\n\nBringt die uralte Glyphe zu Glorenfeld am Eingang zu den Katakomben von Utgarde.", progress = "Daegarn? Die Glyphe?", completion = "Faszinierende Geschichte! Da gibt es tatsächlich etwas, das über die Dinger richtet? Wozu?! Zu welchem Zweck?\n\nNun, vergesst diesen Unsinn. Das soll irgendwer anderes herausfinden. Wir haben Glyphe und Tafeln wieder - und die ganze Tortur hat nur zwei Todesopfer gefordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11301] = { id = 11301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehirne! Wir wollen Gehirne!", description = "Hat Euch Malthus mit seiner Faselei über Bierkrüge und verrückte Zwerge schon in seinen Bann gezogen?\n\nIch will ja nicht in Frage stellen, dass Zwerge verrückt sind, aber ich denke, dass es zu nichts führt, ihr Bier zu stehlen.\n\nWas wir brauchen ist Köpfchen - beziehungsweise etwas aus dem Köpfchen. Und zwar viel davon. Wir werden diesem Rätsel im Nu auf den Grund gehen und vielleicht sogar eine neue Zutat für unsere Seuche finden.\n\nNehmt diese Säge, geht nach Südosten zum Flüsterschlund und tötet ein paar Zwerge. Mithilfe der Säge könnt Ihr die Gehirne sammeln. Bringt sie dann hierher.", sourceObjective = "Apotheker Grick im Apothekerlager möchte, dass Ihr ihm 12 verwirrte Forscherhirne bringt.", progress = "Konntet Ihr die Gehirne bekommen? Falls nicht, dann will ich meine Säge zurückhaben. Und versucht bloß nicht, mit der Säge abzuhauen.", completion = "Oh, diese Gehirne sind schön! Sogar wunderschön! Genau das, was ich brauche.\n\nDanke für Eure Hilfe, {name}. Nun werde ich Malthus mal die Wahrheit zeigen, die er durch seine rosarote Brille nicht sehen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11302] = { id = 11302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvollen Frostnymphen", description = "Als wir das erste Mal nach geeigneten Stellen für das Fort suchten, begegneten wir auf zwei der Lichtungen hier im Norden feindlich gesinnten Kreaturen. Doch als wir über die schneebedeckte Lichtung, die direkt südlich der Stadt liegt, liefen, wurden wir von den dortigen Dryaden nur mit Interesse beäugt, jedoch nicht angegriffen.\n\nWir waren müde und vom Wetter mitgenommen. Sie hätten mit Leichtigkeit mehrere von unseren Männern töten können, taten es jedoch nicht.\n\nVielleicht könnten sie ganz unerwartet zu unseren Verbündeten werden, wenn wir uns ihnen nur nähern würden. Seid Ihr dazu bereit, zur Gefrorenen Lichtung zu reisen und mit ihnen Kontakt aufzunehmen?", sourceObjective = "Sprecht mit Lurielle auf der Gefrorenen Lichtung.", completion = "<Ihr stellt Euch vor und Lurielle lauscht Euren Worten.>\n\nWie gut, Euch endlich kennenzulernen, {name}. Wir haben lange darauf gehofft, dass Ihr und die anderen Neuankömmlinge Repräsentanten schicken würdet. Wir wagen uns nicht sehr oft aus unseren Lichtungen heraus, zumal dieses Land derzeit einige Veränderungen erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11303] = { id = 11303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hinterhalt", description = "Die Vrykul in Quälheim sind endgültig platt gemacht, daran ich keinen Zweifel. Doch ihr Anführer noch immer in der Stadt und will nicht aufgeben.\n\nGorth schickt Lydell und seine Helfer, um guten Hinterhalt im Nordwesten zu machen. Du redest mit Lydell und findest heraus, wie man Vrykulhäuptling herauslockt. Dann tötest du ihn - machst ihn richtig platt.", sourceObjective = "Geht zu Lydells Hinterhalt und sprecht mit Lydell.", completion = "Wir sind alle dabei gewesen, nur der Ehrengast blieb Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11304] = { id = 11304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu-Agamand", description = "Ich befürchte, dass die Ausrüstung hier im Hafen der Vergeltung nicht wirklich die beste ist. Dabei soll das hier ein militärischer Außenposten sein.\n\nIhr müsst eine Probe dieses Erregerstammes für mich zum obersten Seuchenfürsten Harris in Neu-Agamand bringen - folgt der Straße außerhalb von Quälheim nach Süden und dann nach Westen. Dort haben sie bessere Ausrüstung - er wird wissen, was zu tun ist.\n\nIhr müsst Euch beeilen, {name}. Unsere Feinde sind stärker und zahlreicher als wir. Wir müssen eine wirksame Waffe gegen sie entwickeln!", sourceObjective = "Bringt Lysanders Erregerstamm zum obersten Seuchenfürsten Harris. Er befindet sich in Neu-Agamand im Westen des Heulenden Fjords", progress = "Ja, {name}?", completion = "Dieser Erregerstamm ist alles andere als nutzlos, mein Freund! Die Narren im Hafen der Vergeltung! Die Antworten lagen die ganze Zeit direkt vor ihrer Nase!", sourceObjectiveStatus = "unverified-source-field" }
quests[11305] = { id = 11305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine maßgeschneiderte Formel", description = "Wir haben das Vrykuldorf Halgrind nun schon seit Wochen mit dem Zeugs besprüht, aber die Dreckskerle wollen einfach nicht tot umfallen.\n\nSeien wir doch mal ehrlich, {name}, inzwischen wurde fast alles unserer Seuche ausgesetzt: Menschen, Zwerge, Hunde, selbst das Vieh... Während unsere Erregerstämme sich an ihren Wirt anpassen, wird die Mischung noch weiter verunreinigt. Was wir brauchen, ist ein Erreger, der speziell an die Körper der Vrykul angepasst ist.\n\nDer Anführer Halgrinds flüchtete aus der Stadt, nachdem wir sie einnahmen - er befindet sich westlich von hier. Der Fakt, dass er ein Patriarch des Drachenschinderklans ist, macht sein Blut ideal für unsere Zwecke.", sourceObjective = "Geht zu Thorvalds Lager, erschlagt Thorvald, nehmt das Blut des Patriarchen der Drachenschinder an Euch und bringt es zum obersten Seuchenfürsten Harris in Neu-Agamand.", progress = "Konntet Ihr die nötige Probe beschaffen, {name}?", completion = "Das wird reichen. Zeit für ein wenig echte Apothekerarbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11306] = { id = 11306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufkochen und umrühren", description = "Ihr habt bis jetzt gute Arbeit geleistet, {name}. Ich würde Euch gerne ein paar meiner Techniken zeigen - sie sind weiter fortgeschritten und werden Euch ein besseres Verständnis von der Seuche vermitteln.\n\nNehmt diese leere Flasche und füllt sie mit dem Blut aus dem Kessel zu meiner Linken. Nehmt dann die Seuchenproben zu meiner Rechten und gebt so viel zum Blut hinzu, bis Ihr eine ausgewogene Mischung erhaltet.", sourceObjective = "Füllt die leere Apothekerflasche im Kessel mit Vrykulblut auf und vermischt ihren Inhalt so lange mit Harris' Seuchenproben, die sich in der Nähe befinden, bis Ihr eine ausgewogene Mixtur erhaltet.\n\nSprecht wieder mit dem obersten Seuchenfürsten Harris, sobald Ihr die Aufgabe erledigt habt.", progress = "Wie geht es Eurem Experiment, {name}? Lasst es mich wissen, falls Ihr Fragen bezüglich des wissenschaftlichen Aspekts hinter dem Ganzen haben solltet!", completion = "Ausgezeichnet! Ihr seid ein begabter Schüler, {name}.\n\nNun zum spaßigen Teil: die Anwendung!", sourceObjectiveStatus = "unverified-source-field" }
quests[11307] = { id = 11307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldversuch", description = "Da wir nun über einen an vrykulsche Wirte angepassten Seuchenerreger verfügen, müssten wir ihn eigentlich an unseren Exemplaren in Halgrind austesten. Wenn alles nach Plan verläuft, sollten sie augenblicklich zerfallen, da die Seuche ihre Eingeweide zersetzt!\n\nHalgrind befindet sich nördlich von hier. Unsere Seuchenbringer verbreiten dort gerade den alten Erreger - sollte nicht zu übersehen sein.", sourceObjective = "Geht nach Halgrind und wendet das Seuchenspray auf 10 Verseuchte Vrykul der Drachenschinder an. Kehrt anschließend zum obersten Seuchenfürsten Harris zurück und erstattet ihm über die Ergebnisse Bericht.", completion = "Die Seuche ließ unsere Subjekte nicht zerfallen? Seid Ihr Euch sicher, {name}??!\n\nEs muss einen externen Faktor geben, den wir nicht berücksichtigen... vielleicht ist es die niedrige Temperatur, die in diesem Klima herrscht? Vielleicht... eine Mutation unseres Erregers!", sourceObjectiveStatus = "unverified-source-field" }
quests[11308] = { id = 11308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit aufzuräumen", description = "Da ich nun einmal ein praktisch veranlagter Mann bin, erkläre ich hiermit unsere Forschung an diesem Ort für erfolgreich. Schließlich lässt sich noch jede Armee aufhalten, wenn man nur unter ihren eigenen Reihen Zwietracht sät?\n\nIch werde dafür sorgen, dass man im Hafen der Vergeltung bald genug Nachrichten unserer Errungenschaften erhalten wird. Aber zuerst müsst Ihr Euch um die Säuberung unserer Teststätte kümmern.\n\nFragt \"Eisensäge\" Jenny, ob sie eine Monstrosität nach Euren Wünschen anfertigen kann - eine mit explosionsartiger Kraft, wenn Ihr versteht, was ich meine.", sourceObjective = "Sprecht mit \"Eisensäge\" Jenny in Neu-Agamand.", completion = "Was wollt Ihr? Könnt Ihr nicht sehen, dass ich gerade beschäftigt bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[11309] = { id = 11309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Teile", description = "So, Harris will also, dass der Ort demoliert wird, hä? Ja, ich kann aushelfen.\n\nIhr werdet mir jedoch ein paar Teile besorgen müssen. Ich kann es mir nicht leisten, meine kostbarsten Komponenten für etwas zu verwenden, das in die Luft gejagt werden soll.\n\nAls Allererstes brauche ich Schaufelhauerbänder... viel besser als die der Menschen.\n\nAußerdem brauche ich noch ein Pfund Fleisch. Ein Kerl namens Anton verkauft billiges Fleisch. Er ist entlang der Straße gen Westen anzutreffen.", sourceObjective = "\"Eisensäge\" Jenny in Neu-Agamand möchte, dass Ihr 6 Schaufelhauerbänder und 1 Pfund frisches Fleisch besorgt.", progress = "Habt Ihr die Komponenten schon?", completion = "Ausgezeichnet! Ja, ja, das wird völlig ausreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11310] = { id = 11310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung: Ein wenig Montage benötigt", description = "Nun gut, hier, bitte schön! Unser Freund wird etwas... instabil sein - also schlage ich vor, dass Ihr ihn erst zusammenbaut, wenn Ihr in Halgrind seid.\n\nTreibt, wenn Ihr dort seid, mithilfe der Monstrosität so viele Vrykul wie nur möglich zusammen, bevor die Selbstzerstörung ausgelöst wird.\n\nKommt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt mir, was auch immer übrig geblieben ist. Körperteile kann ich immer gut gebrauchen!", sourceObjective = "Benutzt den Monstrositätenbausatz in Halgrind und tötet mithilfe der hirnlosen Monstrosität 20 verseuchte Vrykul. Kehrt nach Neu-Agamand zu \"Eisensäge\" Jenny zurück, sobald Ihr fertig seid.", completion = "Großartige Arbeit, {name}. Ihr würdet nicht zufällig nach etwas... langfristigem suchen, oder? In dieser Gegend gibt es viel zu tun, ich könnte definitiv Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11311] = { id = 11311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elemente bekämpfen", description = "Wenn Ihr hier überleben wollt, so wie wir es bisher getan haben, müsst Ihr den Herausforderungen der Natur direkt ins Auge blicken. In Anbetracht der starken Zunahme der Elementare in dieser Gegend würde Unachtsamkeit gegenüber den Elementen Euer Leben fordern.\n\nWir müssen die Zahl der Elementare ein letztes Mal reduzieren, bevor wir diesen Ort verlassen können. Seid Ihr willens, uns zu helfen, während wir uns um die Vorbereitungen kümmern?\n\nIhr müsst sämtliche Eissplitterelementare oder heulende Zyklone töten, die Euch in den verschneiten Hügeln rings um den Außenposten herum begegnen.", sourceObjective = "Windzähmer Kagan im Lager der Winterhufe möchte, dass Ihr 8 Bergelementare tötet. Zu töten sind entweder heulende Zyklone oder Eissplitterelementare.", completion = "Der Einfluss der Elementargeister ist geschwunden, doch sie werden ihn wiedererlangen. Wir haben uns die nötige Zeit verschafft, um unsere Aufgabe hier zu Ende zu bringen und Abschied zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11312] = { id = 11312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefrorene Lichtung", description = "Seit Generationen erzählt mein Volk sich Geschichten über Frostnymphen, die sich auf verborgenen Lichtungen in der Wildnis tummeln. Als Kind war ich entgegen des Rates meiner Eltern auf der Suche nach ihnen und wäre zum Schluss beinahe erfroren.\n\nHeutzutage muss man jedoch nicht mehr die Wälder durchkämmen, um sie zu finden. Sie haben sich aus mir unerklärlichen Gründen dazu entschlossen, ans Licht zu treten, und ich denke nicht, dass diese Veränderung ignoriert werden kann. Begebt Euch auf die riskante Reise zur Gefrorenen Lichtung gen Südosten und sucht nach den Nymphen - doch seid gewarnt: Euer Weg führt Euch durch die Siechende Lichtung.", sourceObjective = "Sprecht mit Lurielle in der Gefrorenen Lichtung.", completion = "<Ihr stellt Euch vor und Lurielle lauscht Euren Worten.>\n\nWie gut, Euch kennenzulernen, {class}. Meine Schwestern haben oft beobachtet, wie die Taunka in den Wäldern nach uns suchen, doch unsere Königin hat uns jeglichen Kontakt mit Fremdlingen verboten. Ihr könnt uns nur sehen, weil das Land in Aufruhr ist und viele meiner Schwestern in Gefahr sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11313] = { id = 11313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Eises", description = "Einst waren die Eiselementare, die unsere Lichtung umgeben, unsere Gefährten, doch dann wurde das Land von einem Sturm unberechenbarer, zerstörerischer Macht erfasst, der sie zu unseren Feinden machte!\n\nUnd dieses Gräuel ist nur eines von vielen, die meine Schwestern und ich bis jetzt ertragen mussten. Wir haben uns Euch gezeigt und hoffen nun, dass Ihr den Verfall, von dem unsere Lichtungen beschlichen und unsere Schwestern vergiftet wurden, abwenden könnt!\n\nWir haben die Kerne der Eiselementare gesammelt und sicher verwahrt, damit wir sie eines Tages vielleicht wieder zurückrufen können. Werdet Ihr helfen?", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihr 15 eisige Kerne bringt.", progress = "Habt Ihr die Kerne gefunden?", completion = "<Lurielle nimmt schweigend die Kerne entgegen.>\n\nIch danke Euch, {name}.\n\n\n\nIch verspreche, meine Freunde, dass ich alles in meiner Macht stehende tun werde, um Euch zurückzurufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11314] = { id = 11314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefallenen Schwestern", description = "Gen Südwesten befand sich einst eine Lichtung, die dieser hier sehr ähnlich sah. Geheimnisvolle Kräfte und fremde Magie formen das Land neu. Das Eis der Lichtung ist aufgetaut und die Schwestern, die dort wohnen, wurden von der plötzlichen Veränderung in den Wahnsinn getrieben.\n\nWir wollten Kontakt mit ihnen aufnehmen, doch sie griffen uns an. Ich befürchte, dass viele von ihnen nicht mehr zu retten sind, allerdings kann ich die Hoffnung nicht aufgeben.\n\nNehmt meinen Anhänger, reist zur südwestlich gelegenen Lebendigen Lichtung und versucht, mit seiner Hilfe meine Schwestern zu befreien.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr ihren Anhänger auf 7 Eisnymphen verwendet.", completion = "Es besteht also Hoffnung für meine Schwestern?\n\n<Lurielle wendet ihren Blick von Euch ab und richtet ihn dann auf den Boden.>\n\nIch fühle mich schuldig, nicht früher an den Anhänger gedacht zu haben. Wir hätten vielleicht noch mehr Schwestern retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11315] = { id = 11315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Ranken", description = "Die Schwestern, die auf der Lebendigen Lichtung gen Südwesten leben, hegten einst wunderschöne Beete mit scharlachrotem Efeu, doch dieselbe Kraft, die sie in den Wahnsinn trieb, verwandelte auch ihren geliebten Efeu.\n\nDie Ranken greifen nun nach den Füßen jedes Unbesonnenen oder schlingen sich um jeden, der sich der Lichtung nähert. Bevor wir sie wieder kultivieren können, müssen die Ranken gezähmt und entwurzelt werden.\n\nBeseitigt so viele Exemplare des Efeus wie Ihr nur könnt. Die Sache ist schon außer Kontrolle geraten.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 8 Exemplare des scharlachroten Efeus tötet.", completion = "Vielen Dank für Eure Hilfe, {name}. Die Lebendige Lichtung war einst ein wunderschöner Ort, und wenn wir zurückkehren, werden wir es wieder zu dem machen, was es einmal war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11316] = { id = 11316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflechte der Siechenden Lichtung", description = "Die Lichtung im Westen wurde in einen grässlichen Ort verwandelt, der nun Siechende Lichtung genannt wird. Zwischen den Bäumen, Steinen und ihrem Teich hausen nun schreckliche Biester.\n\nMir ist es ein Rätsel, wo diese Kreaturen herkamen oder welche ungeheuren Kräfte sie zum Leben erweckten, doch man muss sich um sie kümmern!\n\nLieße man ihnen die Lichtung, dann fürchte ich, dass ihr Gift sie ein für alle Mal verderben wird. Säubert die Lichtung von den Kreaturen, die unsere Schwestern töteten.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr 10 Dornrankenkriecher tötet.", completion = "Gut gemacht, {name}. Hätten wir Verbündete wie Euch gehabt, als sich die ersten Veränderungen im Land regten, dann hätten wir vielleicht einiges, das uns verloren ging, erhalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11317] = { id = 11317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Läuterung", description = "Der Grund, wieso wir dem Bruchwald trotzen konnten, hat seinen Ursprung in den sorgenschweren Träumen von Ulfang dem Worgen. Er ist mein Freund und ruft um Hilfe. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgen zu wandeln. Ich kenne einen Weg.\n\nZuerst müsst Ihr Euch von Eurem inneren Aufruhr befreien.\n\nAuf der Spitze des Frostklingengipfels, nordöstlich vom Lager der Winterhufe, gibt es einen Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort und kehrt zu mir zurück.", sourceObjective = "Weiser Nebelläufer am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Nun, ich hoffe, Ihr seid auf Geschwindigkeit gefasst. Bevor ich Euch auf die Welt loslasse, müsst Ihr mir erst einmal beweisen, dass Ihr mit diesen feinen Tieren auch wirklich umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Rennzügel und lasse Euch auf einem Widder reiten. Zeigt mir, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten. Sprecht mit meinem Lehrling, Pol Bernruh, falls Ihr Anweisungen für den Umgang mit den Widdern benötigt.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Nicht schlecht! Es dauert meist ein wenig, bis man seinen Widder zu kontrollieren versteht. Hat man den Dreh erstmal raus, würde man sich wünschen, dass jeder Widder ein Rennwidder wäre.\n\nWie bitte? \"Wo ist meine Belohnung?\". Ha, ha, ha... Ihr dürft mit dem schnellsten Widder am Rennen teilnehmen! Ihr wollt noch mehr? Na, wie wäre es damit...\n\nAls Belohnung dürft Ihr anderen hier auf dem Braufest aushelfen. Es gibt jede Menge zu tun... und Belohnungen für eifrige, junge Widderrennmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[11319] = { id = 11319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samen der schwarzbeseelten Bewahrer", description = "Der Ort im Nordwesten, den man nun Siechende Lichtung nennt, war einst das Zuhause etlicher Bewahrer der Lichtung. Gemeinsam mit den Schwestern kümmerten sie sich um deren Pflege.\n\nDie Lichtung veränderte sich und die Schwestern starben, doch irgendwie konnten die Bewahrer überleben. Nun säen sie giftige Sporen im Land und sorgen auf diese Weise dafür, dass das gesunde Grün verwelkt.\n\nIch werde Euch einen der Kerne von den Eiselementaren geben. Sobald Ihr einen Sporen zerstört habt, sollt Ihr ihn mithilfe des Eiskristalls einfrieren und ihn auf diese Weise davon abhalten, sich zu regenerieren.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass ihr 8 Sporen einfriert.", completion = "Der Eiskristall hat Euch gut gedient? Das werde ich mir merken müssen. Einmal die Arbeit der Bewahrer zu zerstören, wird sie jedoch nicht aufhalten, da bin ich mir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11322] = { id = 11322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Läuterung", description = "Seit einiger Zeit habe ich Alpträume, die sich um den Worg Ulfang drehen. Er hat um Hilfe gerufen. Ihr müsst zu ihm gehen.\n\nJedoch habt Ihr nicht die Möglichkeit, mit ihm zu reden oder unter den anderen Worgen zu wandeln, aber ich kenne einen Weg.\n\nDoch zuerst müsst Ihr Euch durch Meditation von Eurem inneren Aufruhr befreien, Euch läutern.\n\nAuf der Spitze des Frostklingengipfels weit im Nordosten befindet sich ein Schrein, zu dem vom westlichen Fuß des Berges aus ein einziger Pfad führt.\n\nMeditiert dort, befreit Euch und kehrt zu mir zurück.", sourceObjective = "Behüterin Mondblatt am Stählernen Tor hat Euch geraten, Euren inneren Aufruhr durch Meditation am Frostklingenschrein zu besänftigen.", completion = "Ich kann die Veränderung in Euch bereits spüren.\n\nSeid Ihr bereit für den nächsten Schritt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11323] = { id = 11323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Worgpelz", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds aufhält.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, es sollte Euch jedoch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, {class}, findet ihn und helft ihm.", sourceObjective = "Der Weise Nebelläufer hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zum Weisen Nebelläufer zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand:", completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11324] = { id = 11324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphaworg", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszureißen!\n\n{race}, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Nebelläufer, sobald du ihn getötet hast, und sag ihm, dass ich wieder der Alphaworg bin!", sourceObjective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zum Weisen Nebelläufer am Stählernen Tor zurück und bringt die Worgverkleidung mit.", progress = "{name}, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Ich kenne diese Kreaturen... sie werden Worgen genannt.\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11325] = { id = 11325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Worgpelz", description = "Aus meinen Träumen weiß ich, dass Ulfang sich in einer Höhle am schneebedeckten nordwestlichen Ende des Bruchwalds befindet.\n\nEr ist in großer Gefahr.\n\nIch habe eine magische Verkleidung erschaffen, die Euch wie ein Worg aussehen lassen wird, während Ihr im Bruchwald seid. Die Verkleidung ist schwach und hängt von der merkwürdigen Magie dieses Geisterwaldes ab. Sie wird zwar nur die Worgs überzeugen, doch es sollte Euch ermöglichen, nah zu Ulfang zu gelangen.\n\nBitte, {class}, findet ihn und helft ihm.", sourceObjective = "Behüterin Mondblatt hat Euch gebeten, Ulfang im Bruchwald zu suchen und ihm zu helfen.\n\nKehrt zu Behüterin Mondblatt zurück, um einen Ersatz zu erhalten, solltet Ihr die Worgverkleidung verlieren.\n\nBereitgestellter Gegenstand:", completion = "Du siehst anders aus und riechst auch anders... Du bist nicht aus meinem Rudel. Erzähl mir deine Geschichte. Ich habe mehr als genug Zeit, solange ich hier gefangen bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11326] = { id = 11326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphaworg", description = "Wenn du die Augen von Klauenwürger gegessen hast, sollte es dir möglich sein, Garwal zu sehen und ihm seine Kehle herauszerreißen!\n\n{race}, such nach Garwal im westlichen Bruchwald und töte ihn. Geh zu Mondblatt, sobald du ihn getötet hast, und sagt ihr, dass ich wieder der Alphaworg bin!", sourceObjective = "Ulfang hat Euch gebeten, Garwal zu erschlagen. Kehrt danach zu Behüterin Mondblatt am Stählernen Tor zurück und bringt die Worgverkleidung mit.", progress = "{name}, Ihr seid zurück. Was gibt es Neues von Ulfang?", completion = "Garwal war überhaupt kein Worg! Das Ding, in das er sich verwandelt, hört sich schon viel eher wie ein Worgen an!\n\nDoch Ulfang meinte, dass es aus den Grizzlyhügeln kam und gen Süden ging? Seltsam. Hier gibt es gar keine Worgen.\n\nIch danke Euch, dass Ihr Ulfang geholfen habt, seinen wahren Platz in seinem Rudel zurückzuerhalten. Nun werden wir beide friedlich schlafen können.\n\nBitte, Ihr müsst das als Zeichen des Dankes akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11327] = { id = 11327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Paket beschaffen'", description = "Tja, verdammt, wir brauchen ein wenig von dem Seuchenzeugs.\n\nIch weiß!\n\nWährend Ihr die Bottiche zerstört habt, konnte ich sehen, wie einer der Apotheker aus Neu-Agamand von den Vrykul nach Halgrind verschleppt wurde. Armer Hund.\n\n{name}, ich könnte wetten, dass der Apotheker das Gut bei sich trägt. Meint Ihr, dass Ihr nach Halgrind gehen und dieses Paket besorgen könntet?", sourceObjective = "Kundschafter Wisslich möchte, dass Ihr nach Halgrind geht und das Paket des Apothekariums beschafft. Kehrt zu ihm zurück, sobald Ihr das getan habt. Er befindet sich am Glutspeerturm.", progress = "Dieser Ort könnte einem Alptraum entstammen. Vrykul oder nicht - niemand hat es verdient, ein Opfer der königlichen Apothekervereinigung zu sein.\n\nIch bin froh hier drüben in Sicherheit zu sein. Habt Ihr das Paket schon gefunden?", completion = "Heiliger... was zum Teufel?! Seht Euch dieses Zeugs an!\n\nWir müssen es so schnell wie möglich zurück zur Wache bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11328] = { id = 11328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Kunde über die Verlassenen'", description = "Gut, nun ich denke, dass Ihr das Zeugs zu Peppy Falschdüse in der Wache bringen solltet. Sie ist so was wie ein Alchemistenamateur - aber der einzige den wir haben.\n\nEins noch zu Peppy: Sie trinkt für ihr Leben gerne. Ihr werdet sie also höchstwahrscheinlich in der Taverne finden - die 'Atmosphäre aufsaugen'.\n\nIch bin mir sicher, dass sie wissen wird, was zu tun ist.", sourceObjective = "Kundschafter Wisslich möchte, dass Ihr das Paket des Apothekariums zu Peppy Falschdüse bringt. Sie befindet sich in der Taverne in Westwacht.", progress = "J-aa, w's wilsd du... hicks?", completion = "Hoppla... das'is was anderes!\n\nNun guud, las misch maal das Scheugs seh'n. Isch liebe es mit Alchemie herumsuufuschn!\n\nInteressaant, interessant... hier, ich denge, isch weiß, was wir mach'n müssn. Ein weenich davon, vermischd mit genauu der rischdischn Menge hiervoon.\n\nWeisd du, isch denke, ein wenig von dem Fusel wäre auch nich schleschd ...hicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[11329] = { id = 11329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich werde alles versuchen!", description = "In meinem ganzen Leben will ich nie wieder ein Fass mit gesalzenem Fisch sehen! Jeden Tag fülle ich hier Fässer und es sind noch so viele zu füllen!\n\nIch wünschte, ich hätte nicht alle Köder aufgebraucht, die ich von Nat Pagle gekauft habe. Haben wie von Zauberhand funktioniert. Jetzt habe ich Glück, wenn ich einen Fisch pro Stunde fangen kann!\n\nIch habe gehört, Nordbarben wären gute Köderfische, aber wer wäre verrückt genug, um in einen eiskalten See zu tauchen und die Wasserpflanzen nach ihnen zu durchwühlen? Ich nicht... aber vielleicht, nur vielleicht, kann ich Euch ja überreden...", sourceObjective = "Christopher Sloan bei Fort Wildervar möchte, dass Ihr ihm 5 Nordbarben bringt.", progress = "Ihr seht aus, als wärt Ihr noch in einem Stück. Etwas von den Ködern bekommen?", completion = "Naja, die sind mit Sicherheit hässlich genug, aber ich schätze, mir ist es egal, ob es tatsächlich funktioniert. Ich werd' froh sein, sobald die Expedition hier durchgezogen ist und ich einfach nur noch für mein Abendessen angeln muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11330] = { id = 11330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dasch wird auf jeden Fall... funzen!", description = "Voila, schofortwirkender Seuschenimpfstoff!\n\nAber ich werde dasch hundertpro nicht an mir selbscht austeschten - und ich weisch, dass du nicht mein Verschuchskaninchen spielen wilscht!\n\nO'isch hab'... isch hab' eine Idee!\n\nDa ischt ein Vrykul, der wird von unsch im Keller der Burg gefangen gehalten. Wiescho nimmscht du nicht einfach diesen Mix - hab ihn schelbst gemischt! - und gehscht da runter und gibscht's dem Ries'n zu trinken... hicks?!", sourceObjective = "Peppi Falschdüse in Westwacht schlägt vor, dass Ihr dem gefangenen Vrykul der Drachenschinder Peppis Spezialmix verabreicht, um zu sehen, welche Wirkung er hat.", completion = "Hä? Echt ätzend! V'dammt, ich hab' die Schache verschlimmert - oder vielmehr hab' ich ihre Scheuche für schie perfektioniert... hicks!\n\n<Peppi verzieht ihr Gesicht und nimmt einen kräftigen Schluck von dem übel riechenden Gebräu, das sie schon die ganze Zeit trinkt.>\n\nNun, isch hatte gehofft, dass'esch nicht soweit kommen wird, aber s'sieht so ausch, als hätten wir keine andere Wahl... hicks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11331] = { id = 11331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Du sagst's ihm... hicks!", description = "So sieht's ausch: Ich werde es dem Hauptmann nicht sagen. Ich bin nur ein Amateur in Sachen Alchemie - das ischt nicht mein Aufgabengebiet und ich hab' gerade Pause!\n\nAuscherdem ist er ein mortzmäßiger Griesgram... und du kennscht ihn besser wie ich!\n\nAlscho geh' zu ihm in die Burg und sag's ihm. Bin mir schicher, dass er die Sache nüchtern betrachten wird... hicks.\n\n<Peppi wendet sich wieder dem Trinken zu.>", sourceObjective = "Peppi Falschdüse hat Euch dazu gebracht, Hauptmann Adams die schlechten Nachrichten über die Seuche der Verlassenen zu überbringen. Ihr findet ihn in Westwacht.", completion = "Ja, {name}, was denn schon wieder?\n\nWAS?!! Eine Seuche der Verlassenen, die ihre Opfer im Nu zerfrisst?\n\nIhr habt meinen Vrykul in Schleim verwandelt?\n\n\n\nNun gut, ich weiß, was wir tun müssen - oder besser gesagt, was IHR tun müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11332] = { id = 11332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Verseucht mal das hier!", description = "Die Königliche Apothekervereinigung denkt also, sie könnte eine perfekte, neue Seuche erschaffen und uns alle auf der Stelle in Schleim verwandeln?!\n\nNicht so lange ich hier kommandiere!\n\nGeht hinaus auf den Hof und sprecht mit Greer Erzhammer. Er hält einen Greifen und ein paar Bomben für Euch bereit. Ich möchte, dass Ihr die Seuchenkessel bei Neu-Agamand in Stücke sprengt!", sourceObjective = "Hauptmann Adams hat Euch befohlen, 5 Bomben auf die Seuchenkessel bei Neu-Agamand abzuwerfen. Kehrt erst zu ihm zurück, sobald Ihr die Aufgabe erledigt habt. Er befindet sich in Westwacht.", completion = "Gut gemacht, {name}, gut gemacht!\n\n\n\nDas wird diesen nichtsnutzigen Verlassenen schon zeigen, was passiert, wenn man sich mit uns anlegt!\n\nIch würde einmal behaupten, dass Ihr Euch etwas aus der Schatzkammer verdient habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11333] = { id = 11333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in die Welt der Geister", description = "Es mag zwar sein, dass die Forscherliga mithilfe ihrer archäologischen Funde dies und jenes über die Vergangenheit herausfinden und der Vizeadmiral mit purer Gewalt Antworten auf gegenwärtige Fragen erhalten kann, doch die Wahrheit an sich liegt in den Geistern.\n\nMit den richtigen Reagenzien kann ich in die Welt der Geister blicken; denn dies ist der Ort, an dem sich Vergangenheit, Gegenwart und Zukunft von Nordend befinden.\n\nWenn Ihr mehr darüber erfahren wollt, werde ich meinen Reagenzienbeutel benötigen. Er kam mir auf einem Schiff abhanden, das nun auf dem Grund der Dolchbucht gen Osten liegt.", sourceObjective = "Thoralius der Weise in Valgarde möchte, dass Ihr seinen Reagenzienbeutel findet.", progress = "Habt Ihr meinen Reagenzienbeutel gefunden?", completion = "Sieht ein bisschen mitgenommen aus, erfüllt jedoch seinen Zweck.\n\n<Thoralius greift in den Beutel und zieht ein paar seltsam aussehende Wurzeln heraus.>\n\nMan lege sie ins Feuer und inhaliere!\n\n<Thoralius atmet tief ein. Sein Körper fängt an zu zittern.>\n\nWa... Was... Es kann nicht sein... Ich kann es nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Der Kampf gegen die Horde kennt keine Grenzen, {name}. Sogar in der Scherbenwelt gibt es beständig Streitigkeiten über Gebietsansprüche und alter Hass wird von Neuem entfacht. Krieg ist allgegenwärtig!\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz, genau wie in Azeroth, obsiegen wird.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Ihr seid schon zurück? Bringt Ihr Nachricht von Sieg?", completion = "Ihr habt der Horde heute ehrenvoll gedient, {name}. Der heutige Sieg sichert uns tausend weitere Siege!", sourceObjectiveStatus = "unverified-source-field" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Wo auch immer wir dem Feind begegnen, werden wir ihn bekämpfen und vernichten. Egal ob dies in Azeroth, in der Scherbenwelt oder irgendwo sonst auf der Welt getan werden muss.\n\nWir dürfen nicht zulassen, dass die Allianz ihre Position im Auge des Sturms weiter festigt. Bringen wir den Kampf also zu ihnen... denn morgen ist es vielleicht schon zu spät.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Ihr ehrt uns alle, {name}. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Die Horde steht in Eurer Schuld, {name}. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11343] = { id = 11343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Echo von Ymiron", description = "Die Geisterwelt ist unter den Einfluss des Lichkönigs geraten. Furcht erregende Kreaturen, aus Alpträumen geformt, wachen nun über das Reich der Elemente. Ich spüre, dass diese Val'kyr ein schreckliches Geheimnis wahren.\n\nIch bin zu alt und schwach, um eine weitere Reise zu überstehen. Ihr müsst an meiner statt gehen, {name}.\n\nNehmt dieses Räuchergefäß, geht nach Wyrmskol und begebt Euch mit seiner Hilfe ins Geisterreich. Geht nach Nordosten! Dort befindet sich der Ort. Meidet die Val'kyr um jeden Preis, damit Ihr nicht ihr Schicksal teilen müsst und auf ewig in ihrer Welt gefangen seid.", sourceObjective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Wyrmskol nach Informationen über die Geheimnisse von Wyrmskol durchsucht.", progress = "Was habt Ihr entdeckt?", completion = "Ich verstehe nicht. Die Kreaturen, die Ihr gesehen habt, sahen genauso aus, wie die Vrykul, die Valgarde angreifen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11344] = { id = 11344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qualen von Niffelvar", description = "Alles, was wir über die Vrykul wissen, deutet darauf hin, dass sie erst vor Kurzem in Nordend auftauchten. Wie kann es dann sein, dass wir Visionen von Vrykul sehen, die 15.000 Jahre zurückreichen? Hätten die Vrykul zuvor schon in Nordend existiert, wüssten wir mit Sicherheit davon.\n\nSetzt Eure Reise fort und begebt Euch nach Niffelvar. Der Weg, den Ihr nehmen müsst, führt Euch nach Nordosten, durch Wyrmskol hindurch und den Pfad hoch in Richtung Damm. Auf der anderen Seite des Dammes, auf den Klippen, befindet sich schließlich Niffelvar.\n\nMacht von dem Räuchergefäß Gebrauch, sobald Ihr dort angekommen seid, und sucht in der Gegend nach Hinweisen.", sourceObjective = "Thoralius der Weise möchte, dass Ihr die Geisterwelt betretet und Niffelvar nach Informationen über die Geheimnisse von Niffelvar durchsucht.", completion = "Menschenkinder, die von Vrykul in die Welt gesetzt wurden? Und Ymiron gab Befehl, alle menschlichen Nachkommen zu töten?\n\n<Thoralius verstummt für einen Moment.>\n\nSo sehr ich es leugnen möchte, was mir so deutlich vor Augen geführt wurde: ich kann es nicht. Es gibt kein ausgestorbenes \"fehlendes Bindeglied\", das die Herkunft der Menschen klären würde. Die Vrykul sind das fehlende Bindeglied - sie sind die Vorfahren der Menschheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise für Kugeln" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Das Plateau der Riesen, das weite steinige Gebiet im Südosten, wurde von Eisenzwergen regelrecht überflutet. Späher haben von Zwergen berichtet, die Steinriesen aus dem Boden locken, um dann Runen in ihre Haut zu meißeln.\n\nWas sie dazu treibt ist mir unerklärlich, aber ich vermute, dass sie irgendwie versuchen, aus den Riesen Waffen zu machen. Die Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch, {name}.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Ausgrabungsleiter Belvar blättert durch das Buch der Runen.>\n\nHmm... hier steht so viel geschrieben. Ich werde eine Weile brauchen, um mich eingehend damit zu befassen - und wenn wir diese Runen verstehen wollen, dann werden wir versuchen müssen, unsere eigenen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Ausgrabungsleiter Belvar in Fort Wildervar möchte, dass Ihr die Rune des Befehls austestet und Binder Murdis besiegt.", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nUnser Wissen darüber, wie sie Runen handhaben, hat sich stark vergrößert. Womöglich werden wir bei der nächsten Begegnung mit den Zwergen daraus einen Vorteil ziehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich habe eine Reihe von Hacken, Hämmern und Meißeln bei mir, die jedoch nicht dazu geeignet sind, die Runen in den Stein zu hauen. Die Werkzeuge der Eisenzwerge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das über bloße Wörter hinausgeht. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nIch meine zu wissen, wie es funktioniert, doch ohne diese Werkzeuge, bin ich mir nicht sicher, ob es klappen wird. Sucht in der Nähe der Eisenzwergzelte auf dem Plateau der Riesen nach Sets, die so aussehen wie meins hier, und bringt sie mir.", sourceObjective = "Bringt Ausgrabungsleiter Belvar in Fort Wildervar ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Belvar nimmt die Werkzeuge vorsichtig in die Hand.>\n\nIch werde sie einmal ausprobieren. Wenn wir die Motive der Eisenzwerge ergründen und sie besiegen wollen, dann muss ich mir über die Wirkung der Runen im Klaren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der Runen", description = "Ich wurde von Häuptling Aschtotem zum Plateau der Riesen geschickt, einem breiten, felsigen Plateau im Südosten, auf der anderen Seite der Gefrorenen Lichtung.\n\nDie Gegend wurde von den Eisenzwergen erobert, die allem Anschein nach die Riesen umwandeln, die aus dem Boden brechen.\n\nDie Eisenrunensteinrufer und -binder tragen große Folianten bei sich, in denen sich die Runen, die sie in die Haut der Riesen ritzen, befinden müssten.\n\nErbeutet die einzelnen Teile dieses Buches, fügt sie zusammen und bringt mir das Buch. Es ist unsere einzige Möglichkeit, wie wir hinter ihre Pläne kommen können.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr ihm das Buch der Runen bringt.", progress = "Habt Ihr das Buch bei Euch?", completion = "<Der Fernläufer blättert durch das Buch der Runen.>\n\nIch bin zwar kein Geschichtskundiger, jedoch mit der Sprache der Eisenzwerge vertraut. Ich denke, dass die Runen, die sie in die Haut der Riesen ritzen, ihrer Sprache entstammen - nur gibt es da ein paar Unterschiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runen meistern", description = "Ich denke, dass ich herausgefunden habe, was die Eisenzwerge dort machen: Ihre Werkzeuge werden während des Schmiedeprozesses mit Magie erfüllt.\n\nMeißelt man mit ihnen die Runen in den Stein, wird aus den Symbolen etwas, das mehr ist als nur bloße Wörter. Diese Runen besitzen die Macht des Bindens, Zwingens und Umkehrens.\n\nWenn ich ein Set mit solchen Werkzeugen hätte, könnte ich die Runen dieses Buchs nachmachen. Ich konnte zwar einen dieser Kästen in den Zelten auf dem Plateau der Riesen finden, doch er war leer. Haltet nach ähnlichen Kästen Ausschau, sucht nach einem Set dieser Werkzeuge und bringt es mir.", sourceObjective = "Bringt Fernläufer Pembe im Lager der Winterhufe ein Set mit Eisenrunenwerkzeugen.", progress = "Seid Ihr mit den Werkzeugen zurückgekehrt?", completion = "<Pembe sieht sich die Werkzeuge genauer an.>\n\nSie sind zerbrechlicher als ich dachte. Gebt mir einen Augenblick, damit ich sie ausprobieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rune des Befehls", description = "Könnt Ihr sie spüren, die Kraft, die von den Runen ausgeht, die ich in diese Tafel gemeißelt habe? Es sind dieselben Runen wie sie die Eisenzwerge verwenden, nur kleiner. Mit ihrer Hilfe werden wir ihre Operation zum Stoppen bringen.\n\nNehmt die Tafel, geht zum Plateau der Riesen und bezaubert mit ihrer Hilfe diejenigen der Steinriesen, die von den Zwergen noch nicht verändert wurden.\n\nDer Riese sollte Euch gehorchen - jedoch habe ich die Runen so gefertigt, dass sie den Bezauberten nach einer gewissen Zeit wieder in seinen ursprünglichen Zustand zurückversetzen. Der Riese mag sich als wertvoller Verbündeter gegen Binder Murdis, den Anführer der Eisenzwerge auf dem Plateau der Riesen, erweisen.", sourceObjective = "Fernläufer Pembe im Lager der Winterhufe möchte, dass Ihr die Rune des Befehls ausprobiert und Binder Murdis besiegt.", progress = "Habt Ihr versucht, die Rune einzusetzen?", completion = "Binder Murdis zu besiegen, war gute Arbeit, aber die Eisenzwerge werden nicht so leicht aufgeben.\n\nMein Volk wird den Eisenzwergen auf seinem Zug gen Norden sicherlich noch einmal begegnen. Doch das nächste Mal werden wir bereit sein und ihre Pläne durchkreuzen, bevor sie richtig loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Nazans Reitgerte", description = "Der heutige Käufer interessiert sich für ein Stück, das sich momentan noch im Besitz des Reittiers von Illidans Herold befindet. Ich spreche natürlich von Vazruden dem Herold und seinem Drachenreittier Nazan.\n\nWenn Euch der Finderlohn angemessen erscheint, solltet Ihr Euch zum Bollwerk der Höllenfeuerzitadelle aufmachen und mir die Reitgerte des Drachen beschaffen.\n\nMeine Quellen versicherten mir, dass sich die Reitgerte im Besitz des Drachen höchstpersönlich befindet. Anscheinend verbot dieser seinem Herren die Benutzung der Gerte.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Nazans Reitgerte zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Reitgerte, bitte!", completion = "Wieder ein zufriedener Kunde. Der Gegenstand scheint in gutem Zustand zu sein, hervorragend. Ihr werdet entsprechend entlohnt werden.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11355] = { id = 11355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Was genau ihr endgültiges Reiseziel ist, weiß ich nicht.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung.\n\nDeaktiviert mithilfe dieser Hacke die Runen auf den Leichen der Riesen und kehrt mit Euren Funden zu mir zurück.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr mithilfe der runensuchenden Hacke die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Forscher Aderan lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Hier wird also nachdrücklich befohlen, in diese Richtung zu ziehen, doch die Runen sind mehr als nur Antrieb. Irgendetwas zieht sie an, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostümierte Waisenmatrone", description = "Während der Schlotternächte werden von den Waisenhäusern der Menschen Ausflüge für die Waisenkinder organisiert. Die Kinder sollen Allianzdörfer auf dem Land besuchen. Die armen Kleinen würden so gerne einen wahren Helden wie Euch sehen!\n\nWarum stattet Ihr ihnen keinen Besuch ab? Ihr findet die Waisenkinder in Goldhain im Wald von Elwynn, in Kharanos in Dun Morogh und bei der Azurwacht auf der Azurmythosinsel. Sprecht mit der Aufsicht der Kinder, einer kostümierten Waisenmatrone, sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer kostümierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", completion = "Ihr seid hier, um die Kinder zu besuchen! Wie wundervoll! In ihrem kurzen Leben ist ihnen so viel Kummer widerfahren. Es ist gut, dass sie einen wahren Helden wie Euch sehen. Es hellt ihr Gemüt wirklich auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maskierte Waisenmatrone", description = "Während der Schlotternächte werden mit den Orcwaisenkindern Ausflüge zu zahlreichen Dörfern der Horde unternommen. Die Waisenmatronen dachten, dass es vielleicht gut für die Kinder wäre, wenn sie wahren Helden einmal bei der Arbeit zusehen könnten.\n\nWarum besucht Ihr sie nicht? <Ein mutiger/Eine mutige:c> {class} wie Ihr könnte ihre Gemüter mit Geschichten Eurer Heldentaten aufhellen! Geht entweder nach Klingenhügel in Durotar, Brill in Tirisfal oder zum Falkenplatz im Immersangwald. Sprecht mit der maskierten Waisenmatrone und sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer maskierten Waisenmatrone in Klingenhügel, Brill oder beim Falkenplatz.", completion = "Die Kinder lieben es, wenn sie Helden bei ihrer Arbeit zusehen können. Ich hoffe, dass ein jedes dieser Kinder einmal ein starkes Mitglied der Horde sein und letztendlich in einer glorreichen Schlacht sterben wird!\n\nAh, der Gedanke an ein solch ehrbares Schicksal rührt mich zu Tränen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wenn wir ausfindig machen könnten, was die Riesen nach Nordwesten zieht, könnten wir sie vielleicht aufhalten, bevor sie ihr Ziel erreichen.\n\nIch konnte zwar viele der Runenprobestücke, die Ihr mir gebracht habt, entziffern, doch diejenigen, die ich nicht kenne, beunruhigen mich am meisten. Als ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt dieses Probestück, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Forscher Aderan in Fort Wildervar möchte, dass Ihr das Probestück einer Rune mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Aderan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nNatürlich! Dieser Megalith muss der Schlüssel zu den Plänen der Eisenzwerge sein. Wir müssen ihn zerstören, bevor sie ihren Plan in die Tat umsetzen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis den Mächtigsten unter den mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Nachdem die Expeditionskorps eingetroffen sind, werden unsere Soldaten die restlichen Riesen isolieren und besiegen können und auf diese Weise ihre eisenzwergischen Meister aus ihren Lagern vertreiben.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Forscher Aderan in Fort Wildervar zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort, der diesen Namen trägt, ist mir zwar unbekannt, doch es klingt wie ein Wort titanischen Ursprungs. Was haben die Eisenzwerge mit solch einem Ding vor? Wir sollten die Sache im Auge behalten, {name}, denn wir müssen das Ding finden, bevor die Eisenzwerge ihren Plan in die Tat umsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind alle Helden von Goldhain bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nEinige Wachen haben nördlich von hier ein kleines Lager für Übungen der Brandwache errichtet. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen oder das in der Nähe der Feuer stehende Fass verwenden.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", progress = "Hallo, {name}. Habt Ihr Euch im Feuerlöschen geübt? Vergesst das Übungslager im Norden nicht!", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Grunzer haben ein Übungslager zum Feuerlöschen außerhalb des Dorfes aufgebaut. In letzter Zeit fangen die Gebäude in Klingenhügel rasch Feuer - Ihr solltet helfen und Euch im Feuerlöschen üben!\n\nVerlasst Klingenhügel in Richtung Westen und biegt rechts ab, wenn Ihr an der Stadtmauer vorbei seid. Haltet nach dem Übungslager Ausschau. Schnappt Euch Wassereimer und löscht damit die Übungsfeuer.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Klingenhügel.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Werdet alle so stark und mutig wie er, dann werdet auch Ihr eines Tages für die Horde kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Keli'dans gefiederter Stab", description = "Die Geschmäcker sind sehr verschieden, nehmt zum Beispiel meinen neuesten Käufer.\n\nIn der Höllenfeuerzitadelle residiert ein Blutorc namens Keli'dan der Zerstörer. Dieser Orc ist im Besitz eines recht gewöhnlichen Stabes; nichts, was einen zweiten Blick wert wäre. Und doch ist es genau dieser Stab, den mein Kunde wünscht.\n\nWer bin ich schon, dass ich diesen Auftrag ablehnen könnte?\n\nAlso, wenn Ihr von mir entlohnt werden wollt, solltet Ihr Euch in den Blutkessel begeben, dort werdet Ihr Keli'dan und seinen Stab finden.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Keli'dans gefiederten Stab zu beschaffen. Bringt ihn zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ihr seid wieder hier... also müsst Ihr den Stab bei Euch tragen!", completion = "Möglicherweise werde ich noch einige frische Federn an den Stab anbringen lassen, bevor ich ihn seinem Käufer übergebe. Mit den ganzen Arakkoas in dieser Gegend sollte das jedoch kein großes Problem darstellen. Ein eher unwichtiges Detail und nichts, das mich davon abhalten könnte, Euch angemessen zu entlohnen.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Messerfausts Siegel", description = "Am heutigen Tage ist ein sehr reicher Sammler an mich herangetreten, dem es nach etwas besonders Einzigartigem verlangt.\n\nKriegshäuptling Kargath Messerfaust trägt sein persönliches Siegel, mit dem er alle offiziellen Dokumente abzeichnet, stehts bei sich. Ich möchte, dass Ihr es für mich beschafft.\n\nIhr findet ihn tief in den Zerschmetterten Hallen. Es besteht kein Zweifel, dass Ihr Euch zunächst durch eine recht beeindruckende Armee kämpfen müsst, bevor Ihr das Siegel in den Händen haltet. Aber ich glaube fest an Euren Erfolg!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Messerfausts Siegel zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich hörte Gerüchte, nach denen der Kriegshäuptling seine Hände durch Waffen hat ersetzen lassen. Ist das wahr?", completion = "Wahrlich eine beeindruckende Akquisition; eine, die es wert ist, dass die Barden noch in Jahrzehnten darüber berichten. Hier, Ihr habt Euch diese Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zenturionen der Zerschmetterten Hand", description = "Zweifelt Ihr an Eurem Meister? Gut, dann verstehen wir uns, ja?\n\nEs ist das Blut der Zenturionen der Zerschmetterten Hand, nach dem es mich verlangt. Sucht sie in den Zerschmetterten Hallen der Höllenfeuerzitadelle.\n\nWenn Euch die Belohnung lieb ist, werdet Ihr erst zurückkehren, nachdem Ihr sie alle getötet habt.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Zenturionen der Zerschmetterten Hand zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ihr habt Euch Eure Belohnung in der Tat verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Riesen", description = "Im Osten, auf dem Plateau der Riesen, haben mit Runen übersäte Riesen damit begonnen, gen Norden in Richtung Frostklingengipfel zu ziehen. Ich weiß nicht, was sie vorhaben, noch wohin sie wollen.\n\nDie leuchtenden Runen, die in das steinerne Fleisch der Riesen gemeißelt wurden, weisen ihnen auf ihrer Reise die Richtung. Streckt ein paar dieser Riesen nieder - dadurch werden die Runen aufhören zu leuchten, so dass man Proben aus dem Körper der Riesen brechen kann.\n\nNehmt diese Hacke mit Euch und bearbeitet mit ihrer Hilfe die runenbeschriebenen Steinriesen. Dadurch werden die Runen deaktiviert. Kehrt mit Euren Funden zu mir zurück, sobald Ihr Euch mit genug Riesen gemessen habt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr mithilfe der Hacke zum Runensuchen die Leichen von 4 runenbeschriebenen Steinriesen bearbeitet.", completion = "<Der Weise lauscht Euren Worten, als Ihr von Euren Funden berichtet.>\n\nDie Runen für \"Norden\" und \"Westen\" tauchen mehrmals auf? Ich bin zwar kein Experte, was diese Runen angeht, aber dass sie sich wiederholen deutet darauf hin, dass es ein ausdrücklicher Befehl ist.\n\nDiese Gravuren sind jedoch mehr als nur Wegweiser. Es scheint, als steuerten sie die Riesen auf etwas zu, nur was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leitstein", description = "Wir müssen herausfinden, was die Riesen nach Nordwesten zieht, damit wir sie aufhalten können, bevor sie ihr Ziel erreichen.\n\nDie Runenproben gaben uns zwar einige Anhaltspunkte, doch es sind die unbekannten Runen, über die ich mir Sorgen mache.\n\nAls ich das Plateau der Riesen besuchte, bemerkte ich eine große, zerbrochene Tafel, die an der Stelle aus dem Boden herausragte, wo der nordöstliche Teil der Gegend auf den Schnee am Fuße des Frostklingengipfels trifft. Nehmt diese Probe, vergleicht die Runen mit der Tafel und seht nach, was Ihr herausfinden könnt.", sourceObjective = "Weiser Edan im Lager der Winterhufe möchte, dass Ihr die Runenprobe mit der zerbrochenen Schrifttafel vergleicht.", completion = "<Edan hört Euch aufmerksam zu, als Ihr Eure Entdeckung schildert.>\n\nMegalith? Es ist Wort für Wort das, was auf der Schrifttafel steht! Dieser Megalith muss das Herzstück der rätselhaften Pläne der Eisenhaften darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megalith zertrümmern", description = "Mit Megalith schuf Binder Murdis eine Art Schlussstein in der Hierarchie der mit Runen versehenen Riesen und somit den Leiter ihrer Mission. Besiegte man Megalith, wären sie verloren und orientierungslos. Ich werde Häuptling Aschtotem ersuchen, auf unserem Marsch gen Norden ein paar unserer Männer zur Beseitigung des letzten Rests dieser mit Runen versehenen Riesen einzusetzen.\n\nSucht auf den Ausläufern des Frostklingengipfels nördlich des Plateaus der Riesen nach Megalith und bezwingt ihn!", sourceObjective = "Bezwingt Megalith und kehrt anschließend zu Weiser Edan im Lager der Winterhufe zurück.", completion = "Megalith zu Fall zu bringen, war gute Arbeit, doch ich frage mich, was wohl seine letzten Worte zu bedeuten haben.\n\nSeid Ihr Euch sicher, dass er die Steinschmiede erwähnte?\n\nEin Ort mit diesem Namen ist meinem Volk unbekannt, doch es klingt, als wäre es von den \"Titanen\" geschaffen, von denen die Außenstehenden sprechen. Die Eisenzwerge waren schon immer ein gerissener und gefährlicher Feind, {name}. Wir müssen diese Riesen im Auge behalten und Steinschmiede finden, bevor sie ihre Pläne verwirklichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Das Herz von Quagmirran", description = "Ich habe einen recht ungewöhnlichen Auftrag für Euch. Eine bestimmte wohlhabende Persönlichkeit, mit der ich in außerweltlichem Kontakt stehe, interessiert sich für ein besonders makaberes Stück.\n\nGenau genommen verlangt sie das Herz von Quagmirran.\n\nWie ich hörte, verfügt dieses Biest gleich über drei Herzen, doch ich denke, eines dürfte für unsere Zwecke ausreichend sein. Soweit ich informiert bin, ruht Quagmirran in einem tiefen See in den Sklavenunterkünften des Echsenkessels.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm das Herz von Quagmirran zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich vertraue darauf, dass Ihr eine Möglichkeit findet, das Herz sicher hierher zu bringen!", completion = "Wenn ich es mir recht überlege, dann ist es eigentlich eine Schande, dass ich Euch nicht darum gebeten habe, mir alle Herzen zu bringen. Vielleicht beim nächsten Mal. Wie auch immer, Ihr habt Euch Euren Anteil redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Ei der Schattenmutter", description = "Unter den Marschenläufern in den Zangarmarschen gibt es stets nur eine oberste Mutter. Man nennt sie die Schattenmutter und wenn sie stirbt, schlüpft ihre Nachfolgerin aus einem der hinterbliebenen Eier.\n\nEiner meiner Käufer interessiert sich für eben diese Eier. Beiläufig erwähnte er etwas davon, dass das geschlüpfte Wesen eine hervorragende Ergänzung für seinen Zoo wäre.\n\nWenn Euch meine Bezahlung angemessen erscheint, solltet Ihr in den Tiefensumpf aufbrechen und die Schattenmutter töten, um an das Ei zu gelangen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm ein Ei der Schattenmutter zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Sprechen wir uns wieder, weil Ihr das Ei habt? Fantastisch, lasst es mich sehen!", completion = "Ist es nicht fantastisch, wie sehr man das Leben in diesem Ei spüren kann? Ich werde mich beeilen und es rechtzeitig zu seinem Käufer bringen müssen. Wir wollen doch nicht, dass es hier bei uns schlüpft, nicht wahr?\n\nEure Bezahlung steht bereit.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Aufzeichnungen des Kriegsherren", description = "Vielen ist bekannt, dass Kriegsherr Kalithresh ein hervorragender Stratege ist, doch nur wenige wissen, dass er sein gesamtes Wissen auch niedergeschrieben hat.\n\nEiner meiner Kunden hat davon erfahren und nun wünscht er diese Aufzeichnungen in seinen Besitz zu bringen.\n\nDaher möchte ich Euch bitten, in die Dampfkammer des Echsenkessels einzudringen, um das Buch für mich zu beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Aufzeichnungen des Kriegsherren zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Mein Kunde wird langsam ungeduldig. Ich nehme an, er möchte das strategische Wissen des Kriegsherren zur Lösung eines seiner laufenden Konflikte einsetzen.", completion = "Tatsächlich glaube ich, dass mein Kunde nicht genügend Zeit aufbringen kann, um das Buch in seiner Gesamtheit zu studieren. Nun gut, überlassen wir das ihm. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Myrmidonen des Echsenkessels", description = "Mah'duun hat gehört und verstanden. Jetzt sollt Ihr sein Werkzeug sein.\n\nMir wurde offenbart, dass die Myrmidonen des Echsenkessels vernichtet werden müssen. Sucht in den klammen Räumen der Dampfkammer unter dem Echsenkessel nach ihnen.\n\nIch erwarte nichts Geringeres als ihre vollständige Vernichtung.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 14 Myrmidonen des Echsenkessels zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ich nehme an, es war ein Kampf ganz nach Eurem Geschmack? Die Belohnung wird Euch ebenfalls zusagen.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Kopfschmuckfedern von Ikiss", description = "Kürzlich ist eine Taurenfrau an mich herangetreten, deren Ehemann schon bald in den Stand eines Häuptlings erhoben wird. Sie würde ihn gerne mit einer besonderen Verzierung für seinen Federkopfschmuck überraschen.\n\nGenau genommen hätte sie gerne die Kopfschmuckfedern des niederträchtigen Klauenkönigs Ikiss.\n\nWenn Euch meine ausgesetzte Belohnung angemessen erscheint, solltet Ihr zu den Sethekkhallen von Auchindoun aufbrechen und Ikiss einen Besuch abstatten.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Kopfschmuckfedern von Ikiss zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Häuptlingszeremonie findet bald statt, beeilt Euch.", completion = "Diese Federn werden dem Kopfschmuck des Häuptlings den letzten Schliff geben. Ihr habt Euch Eure Bezahlung redlich verdient, {class}.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Shaffars wundersames Amulett", description = "Heute möchte ich Euch mit einer persönlichen Angelegenheit beauftragen. Aber keine Sorge, die Belohnung macht die Gefahr wieder mehr als wett.\n\nMeine Familie hat noch eine Rechnung mit Nexusprinz Shaffar und seinen Anhängern offen. Sollte mir sein Amulett in die Hände fallen, wäre dies ein sicheres Zeichen dafür, dass sich jemand seiner angenommen hat.\n\nWenn Euch meine Belohnung angemessen erscheint, solltet Ihr zu seinen Gemächern in der Managruft von Auchindoun aufbrechen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Shaffars wundersames Amulett zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Nur wenige wissen, dass Shaffar seine magische Macht ausschließlich aus diesem Amulett bezieht. Ohne es ist er machtlos.\n\nWenn es sich also in Eurem Besitz befindet, lässt dies nur den Schluss zu, dass er tot ist.", completion = "<Eine Woge der Zufriedenheit scheint von dem Windhändler auszugehen.>\n\nGut, es freut mich, von seinem Ende zu hören. Wer weiß, vielleicht gelingt es mir sogar, die Geheimnisse des Amuletts für mich zu nutzen und wenn nicht, werde ich es zu einem angemessenen Preis verkaufen.\n\nIch schätze diese Belohnung ist mehr als ausreichend.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Seelenedelstein des Exarchen", description = "In dem Bestreben, die nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Auchindoun eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden.\n\nEiner meiner Kunden wünscht die Befreiung eines dieser gequälten Geister. Nach meinen Informationen ist dieser Geist in einem Seelenedelstein gefangen, der sich im Besitz von Exarch Maladaar befindet.\n\nSucht ihn mit gebotener Schnelligkeit in der Krypta auf und bringt mir seinen Edelstein.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Seelenedelstein des Exarchen zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Könnt Ihr Euch vorstellen, für alle Ewigkeit in einem Edelstein gefangen zu sein?", completion = "Ihr seid wahrlich ein Held, {name}. Ich bin mir sicher, dass mein Kunde einen Weg finden wird, um den Geist seiner Geliebten aus dem Edelstein zu befreien. Eure Belohnung für diese hervorragende Arbeit wartet bereits auf Euch.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Murmurs Flüstern", description = "Wenn ich Euch eingeweiht habe, werdet Ihr diesen Auftrag mit Sicherheit nicht mehr annehmen wollen.\n\nEiner meiner besonders exzentrischen Kunden befasst sich mit der Erforschung toter Existenzen. Wenn man diversen Gerüchten Glauben schenkt, zerstörte das als Murmur bekannte Wesen die letzte Welt von der es beschworen wurde vollständig. Der Professor würde gerne das so genannte 'Flüstern' dieser Kreatur analysieren, um zu verstehen, wie Murmur so eine Zerstörung verursachen konnte.\n\nWürdet Ihr für mich in das Schattenlabyrinth in Auchindoun eindringen und das 'Flüstern' für mich beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin mir nicht einmal sicher, welche Form ein Flüstern in der körperlichen Welt annimmt, aber der Professor versicherte mir, dass Ihr es erkennen werdet, wenn Ihr es seht.\n\nVielleicht ist es so etwas wie der Kehlkopf des Wesens?", completion = "Ich fürchtete schon, Ihr würdet nicht mehr zurückkehren. Ich hoffe doch, der Kampf gegen Murmur hat Euch nicht taub werden lassen?\n\nHier ist Eure Belohnung. Der Professor wird zweifellos sehr zufrieden sein. Ich fürchte mich nur davor, was er mit diesem Gegenstand anfangen wird.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Bösartige Ausbilderinnen", description = "Mah'duun hat vernommen, dass die Grausamkeit der sechsarmigen Dämonen im Schattenlabyrinth beispiellos ist.\n\nBegebt Euch nach Auchindoun, sucht und tötet sie alle.\n\nBemüht Euch nicht, mich ein zweites Mal aufzusuchen, wenn Ihr scheitert.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", progress = "Habt Ihr die Ausbilderinnen alle getötet? Nein?\n\nHabe ich Euch nicht aufgetragen, erst zurückzukehren, wenn alle tot sind?", completion = "Ich bin sehr zufrieden. Auch der, der über den Nether zu mir spricht, ist hoch erfreut. Mah'duun hat Eure Belohnung bereits vorbereitet.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist süß", description = "Heute Abend koche ich für eine ganz besondere Festgemeinschaft. Einer der Gäste flog vor Kurzem in Skettis herum, als er plötzlich von einem riesigen Kaliri erfasst wurde und zu Boden fiel. Er brach sich dabei sein Bein.\n\nFür seine 'Gute Besserungs'-Feier soll nun etwas ganz Besonderes auf dem Speiseplan stehen: Kalirieintopf.\n\nIch werde Euch meinen Topf zur Verfügung stellen und es wird Eure Aufgabe sein, den Eintopf zu kochen. Das Rezept ist an sich recht einfach, Ihr benötigt nur einen riesigen Kaliriflügel und einige Doppelwarper.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Rieche ich da etwas zu essen?", completion = "Oh, das riecht aber lecker! Ich hoffe, Ihr habt dem Vogel einen guten Kampf geliefert.\n\nBitte, nehmt Euch ruhig etwas von meinen speziellen Vorräten. Jemand mit Eurem Talent sollte damit etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Kopf des Epochenjägers", description = "Die Geschmäcker meiner Kunden variieren von banal zu sehr exotisch. Und manchmal wollen sie mit den exotischen Gegenständen, die ich ihnen beschaffe, sehr banale Dinge anstellen.\n\nMein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen.\n\n{class}, Ihr müsst einen Weg finden, um zurück durch die Zeit ins Alte Hügelland zu reisen und besagten Kopf für unseren Trophäen sammelnden Kunden beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Der Kopf des Epochenjägers... wie kommt jemand bloß auf die Idee, sich diesen an die Wand hängen zu wollen?\n\nSelbst wenn, dann geht man doch selbst auf die Jagd. Was soll man denn den eigenen Freunden erzählen, wenn sie einem Fragen über den Kampfverlauf stellen?\n\nBleibt höchstens eine Notlüge.", completion = "Wie ich sehe, seid Ihr wieder gesund und munter im Hier und Jetzt angekommen.\n\n<Der Windhändler sieht sich um.>\n\nMir scheint, dass sich nichts verändert hat. Auf der anderen Seite, würde ich es wahrscheinlich gar nicht merken.\n\nEin sauberer Schnitt, mein Kunde wird zufrieden sein. Hier ist Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superheißes Ragout", description = "Ich versuche gerade, etwas ganz Besonderes zu kreieren. Aber um ehrlich zu sein, bin ich mittlerweile eher ein Theoretiker geworden. Irgendwie ist mir mein Sinn für Abenteuer abhandengekommen.\n\nIhr aber... Ihr erinnert mich irgendwie an mich selbst in jungen Jahren. Bereit, sich der Welt mit Schwert und Bratpfanne zu stellen.\n\nIch möchte, dass Ihr meinen Lieblingskochtopf nehmt und Euch zum Schergrat aufmacht. Füllt ihn mit ein paar Rippchen und Knusperschlangen - natürlich gekocht, für die Extraportion Würze. Zum Schluss erhitzt Ihr das Ganze über einem abyssischen Leichnam. Dies ist die einzige Wärmequelle, die heiß genug ist, um dieses Gericht perfekt zu garen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Verlief mein kleines Experiment erfolgreich?", completion = "Nun sieh mal einer an...\n\n<Als der Rokk ein wenig von Eurem Gericht probiert, zeichnet sich auf seinem Gesicht eine Mischung aus Entzücken und abnormen Schmerzen ab.>\n\nHeiliger A'dal ist das lecker! Ein Koch mit Eurem Talent braucht stets die richtigen Zutaten! Hier, bedient Euch aus meinen Vorräten und macht mich stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaziös", description = "War ja klar! Ich denke meine Vorräte sind lückenlos und sofort kommt jemand um die Ecke, der etwas Ausgefallenes haben möchte: Manabeere Surprise.\n\nUnglücklichweise findet man Manabeeren nur in den Biokuppeln des Nethersturms. Aber macht Euch nicht die Mühe, auf der Sturmsäule zu suchen - dort ist alles abgeerntet.\n\nEs bedarf eines wahren Meisters der Kochkunst, um nur die besten Beeren zu pflücken, also enttäuscht mich nicht!", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt.", progress = "Hattet Ihr Erfolg?", completion = "Noch nie sah ich so saftige Beeren! Ich fühle mich schon vom bloßen Hingucken geistig gestärkt.\n\nWarum nehmt Ihr nicht etwas von meinen Fisch- und Fleischvorräten? Anscheinend habe ich eh keine Verwendung mehr dafür. Sicherlich werdet Ihr daraus etwas ganz Besonderes kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppe für die Seele", description = "Irgendetwas liegt in der Luft. Noch nie hatte ich so viele Bestellungen für meine berühmte Suppe - sie weckt die inneren Geister und streichelt die Seele.\n\nIch erkenne einen Koch, wenn ich einen sehe! Würdet Ihr mir im Austausch gegen eine kleine Gewinnbeteiligung ein wenig aushelfen?\n\nHier, nehmt meinen Kochtopf, sammelt etwas Grollhuffleisch und ich verrate Euch ein kleines Geheimnis. Was glaubt Ihr, macht meine Suppe so angenehm für die Seele? Es hat nichts mit Hühnchen zu tun! Es liegt daran, dass ich sie beim Ahnengrund in Nagrand koche, um alles Geisterhafte, das in der Luft schwebt, einzufangen.", sourceObjective = "Der Rokk im Unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Was riecht hier so gut?", completion = "Das ist eine feine Ladung spirituelle Suppe. Es fehlt nur noch etwas Pfeffer für den richtigen Geschmack!\n\nHier, wie versprochen, Euer Anteil. Und weil Ihr so gute Arbeit geleistet habt, dürft Ihr Euch noch an meinen Vorräten bedienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Aeonus' Stundenglas", description = "Einige meiner Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte!\n\nMein heutiger Kunde ist der Inbegriff von Größenwahn! Er verlangt nichts Geringeres als Aeonus' Stundenglas.\n\nJa, Ihr habt richtig gehört, das Stundenglas von Aeonus, seines Zeichens Angehöriger des ewigen Drachenschwarms!\n\nAber wer bin ich schon, dass ich widersprechen könnte? Insbesondere bei der Menge Gold, die er mir geboten hat. Also, seid Ihr bereit, die Höhlen der Zeit aufzusuchen und in den Schwarzen Morast zu reisen, um das Stundenglas zu beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "An Eurer Stelle wäre ich mit Zeitreisen sehr vorsichtig. Schließlich wollt Ihr ja nicht versehentlich einen Eurer eigenen Vorfahren töten und so Eure eigene Existenz in der Gegenwart auslöschen!", completion = "Seltsam, dass der Sand in diesem Ding noch immer aufwärts fließt. Ich schlage vor, wir schaffen es lieber schnellstmöglich zu seinem neuen Besitzer.\n\nIch muss Euch für diese gute Arbeit danken, {class}. Ihr habt Euch Eure Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Fürsten der Zeitenrisse", description = "Mah'duun weiß, was zu tun ist. Mah'duun weiß, dass Ihr Fürsten der Zeitenrisse töten müsst. Doch Mah'duun ist sich des Zeitpunkts nicht sicher.\n\nDas klingt alles sicherlich sehr seltsam für Euch, doch die Stimme im Wind sagte mir auch nicht viel mehr.\n\nBegebt Euch in die Höhlen der Zeit und reist in den Schwarzen Morast. Dort wird sich Euch alles offenbaren.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Anscheinend habt Ihr Euren Weg in die Vergangenheit und wieder zurück gefunden. Eure Fähigkeiten als {class} sind bemerkenswert. Die Belohnung gehört Euch.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Warpzweigsplitter", description = "Vor Kurzem trat eine Druidin der Kaldorei mit einer herzzerreißenden Bitte an mich heran. Gut, sie hatte auch eine ganze Menge Gold bei sich...\n\nEs scheint, als versuchten die Streitkräfte von Darnassus ein arkanes Urtum namens Warpzweig neu zu erschaffen. Dieses gigantische Baumwesen hat sich wohl verirrt oder wurde von der Verderbnis durchdrungen, naja, jedenfalls hält es sich zurzeit in der Botanika der Festung der Stürme auf.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Schwierigkeiten die Botanika zu finden? Ihr könnt sie gar nicht verfehlen, sie ist ein Teil der Festung der Stürme am östlichen Rand des Nethersturms.", completion = "Oh, Ihr habt es tatsächlich geschafft! Er ist so klein. Unglaublich, das Warpzweig aus diesem kleinen Ding neu erstehen soll und wie man mir sagte, ist es ein ziemlich langwieriger Prozess, den die Druiden da vor sich haben.\n\nEgal, wie versprochen, habe ich hier Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Kanalisierer der Sonnensucher", description = "Mah'duun wurde offenbart, dass die Kanalisierer der als Sonnensucher bekannten Kampfeinheit heute getötet werden müssen.\n\nIhr findet sie in der Botanika der Festung der Stürme.\n\nIhr wollt das Kopfgeld? Also tötet sie!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Mit den Kanalisierern ist es aus. Der, der aus dem Nether zu mir spricht ist zufrieden und Ihr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Pathaleons Projektionsgerät", description = "Ich habe stets angenommen, Pathaleon könnte sein Abbild nur mithilfe von Magie an die verschiedensten Orte in der Scherbenwelt projizieren. Offensichtlich lag ich damit falsch.\n\nMein neuester Kunde verriet mir, dass der Blutelf stattdessen ein mechanisches Gerät verwendet, um mit den diversen Offizieren von Kael'thas zu kommunizieren. Wenn ich es richtig verstanden habe, stahl er es von einigen Zaxxisrebellen im Nethersturm.\n\nMein Kunde wünscht, dieses Projektionsgerät zu besitzen. Also, warum stattet Ihr Pathaleon nicht einen Besuch ab? Ihr findet ihn in der Mechanar der Festung der Stürme.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es ist ja nicht so, dass die Projektionstechnologie alleine schon etwas Besonderes wäre, aber die Reichweite dieses Modells ist enorm und bisher unerreicht!", completion = "Ich bin versucht, es für mich zu behalten und meinem Kunden sein Geld zurückzuzahlen. Mit diesem Gerät könnte ich meine Geschäfte über noch größere Entfernungen abwickeln.\n\n<Der Windhändler seufzt.>\n\nAber ich kann meinen guten Ruf nicht so leichtfertig aufs Spiel setzen.\n\nWo wir schon von meiner Reputation reden, vielen Dank, dass Ihr mir dabei geholfen habt, sie zu wahren. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zerstörer der Sturmschmiede", description = "Im Inneren der Mechanar gibt es eine Vielzahl mechanischer Konstrukte und man hat Mah'duun mit ihrer Vernichtung beauftragt.\n\nBetretet die Festung der Stürme, sucht die Zerstörer der Sturmschmiede und vernichtet sie.\n\nKehrt anschließend zurück, um Eure Belohnung zu erhalten.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden.", progress = "<Der Netherpirscher scheint sich über Eure Anwesenheit zu wundern.>\n\nDie Zerstörer sind noch längst nicht alle vernichtet.", completion = "Mah'duun liebt es, gegen Konstrukte zu kämpfen! Sie sind nicht so fehlerbehaftet wie organische Lebewesen.\n\nIhr habt Euch die Belohnung verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Horizontiss' Schriftrolle", description = "Meinem heutigen Kunden verlangt es nach etwas besonders Ausgefallenem.\n\nMan erzählt sich, dass Herold Horizontiss ein Jünger der Alten Götter sei. Des Weiteren soll er stets eine Schriftrolle bei sich tragen, die die Anweisungen der Götter für ihn enthalten, alles Leben im Universum in ihrem Namen zu unterwerfen.\n\nObwohl er die Schriftsprache der Rolle nicht entziffern können wird, wünscht mein Kunde dennoch, diese zu besitzen.\n\nDringt in die Arkatraz der Festung der Stürme ein und beschafft sie für mich, {class}!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es muss ganz schön gefährlich sein, sich in die Angelegenheiten der Alten Götter einzumischen.\n\nNaja, besser Ihr als ich!", completion = "Bevor ich den Zorn der Alten Götter auf mich ziehe, hüte ich mich lieber davor, die Schriftrolle überhaupt zu berühren. Ich werde einen meiner Assistenten mit der Zustellung beauftragen.\n\nIhr habt Eure Belohnung mehr als verdient, {class}, und ich wünsche Euch für die Zukunft alles Glück der bekannten Welt!\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schildwachen der Arkatraz", description = "Die Schildwachen der Arkatraz sind wahnsinnig geworden. Die Gefangenen laufen Amok und die Wachen greifen all jene an, die helfen wollen.\n\nMah'duun vernimmt im Raunen des Netherwindes die Stimme des Sprechers. Der Sprecher befiehlt die Vernichtung der Schildwachen.\n\nBringt diese Aufgabe zu Ende und die heutige Belohnung gehört Euch!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das Untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Vielleicht wenden die Naaru sich nach der Vernichtung der Schildwachen an das Konsortium, um Ersatz anzufordern? Mah'duun weiß es nicht und es interessiert ihn auch nicht.\n\nIhr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kann fliegen!", description = "Tja, auf was wartet Ihr denn noch, es gibt viel zu tun!\n\nHier sind die Schlüssel zu unserer Flugmaschine. Schnappt Euch drei Säcke voller Relikte und befördert sie auf die Kranplattformen auf der Nord- und Südseite des Stählernen Tores. Ich werd' sie für Euch markieren.\n\nMacht schnell! Wir haben nicht den ganzen Tag Zeit!", sourceObjective = "Der Chefarchäologe des Stählernen Tores möchte, dass Ihr 3 Säcke voller Relikte vom Grund der Ausgrabungsstätte zu einer der Plattformen auf der Nord- oder Südseite des Stählernen Tores befördert.\n\nBenutzt den Enterhaken der Flugmaschine für diese Aufgabe.\n\nMeldet Euch bei ihm zurück, sobald Ihr damit fertig seid.", completion = "Gute Arbeit - ich mein' jedoch, dass Ihr über einen Auffrischungskurs in Sachen grundlegende Fliegerei nachdenken solltet.\n\nNun ja, macht nichts, einer ist so gut wie der andere. Hier ist Eure heutige Ausbeute.", sourceObjectiveStatus = "unverified-source-field" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouille am Stählernen Tor", description = "Äh? Heute wieder da zum Arbeiten?\n\nNun gut, hier sind die Schlüssel. Heute muss nichts mehr befördert werden, also haltet nur nach Dingen Ausschau, die verdächtig aussehen, okay?\n\nHab' ein paar Raketen und 'n Maschinengewehr auf sie draufgepackt - für den Fall der Fälle.", sourceObjective = "Für die Leute am Stählernen Tor seid Ihr jetzt ein Fliegerass, also will der Chefarchäologe des Stählernen Tores, dass Ihr über der Ausgrabungsstätte patrouilliert und alle Angreifer bekämpft.\n\nMeldet Euch wieder bei ihm zurück, wenn Ihr Eure Patrouille geflogen habt.", completion = "Gut geschossen, Ass.\n\nHier ist Euer Lohn. Kommt morgen wieder und dreht noch 'ne Runde, hört Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein.", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Forscher Jaren?", description = "{name}, mein Verlobter Jaren ging mit einer kleinen Gruppe Forscher nach Westen, um Gerüchten über Artefakte entlang der Küste des Frostmaares nachzugehen. Dort unten gibt es jedoch Murlocs und ich befürchte, dass ihnen das Schlimmste zugestoßen sein könnte.\n\nIhr hättet sicherlich Zeit um nachzusehen, ob es ihnen gut geht, oder? Gleich hier in der Nähe, im Südwesten, gibt es einen Weg hinunter zum Strand - hütet Euch jedoch vor den Worgs und anderen Dingen, die im Wald herumstreunen.", sourceObjective = "Vorarbeiterin Irena Zasterstein hat Euch gebeten, nach ihrem Verlobten Forscher Jaren zu suchen.", completion = "<Der Forscher wirf Euch ein Lächeln zu, als Ihr ihm erzählt, wer Euch geschickt hat. Mit gedämpfter Stimme fährt er fort.>\n\nIrena hat sich um mich Sorgen gemacht? Das hat sie von ihrem Vater, müsst Ihr wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", description = "Ich bin ursprünglich hierhergekommen, um ein paar Gerüchten über auszugrabende Artefakte nachzugehen. Ich hab' zwar gewusst, dass es entlang dieser Küste Murlocs gibt, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde.\n\n<Der Forscher reckt seinen Hals und späht hinter dem Baum hervor.>\n\nDie Diener der Geißel sind dort draußen und sie verwandeln Murlocs und überhaupt alles, was ihnen in die Finger gerät, in wandelnde Tote!\n\n{class}, ich denke, dass es unsere Pflicht ist, etwas dagegen zu unternehmen. Wäre es denkbar für Euch, einen guten Teil dieser Geißel zu beseitigen?", sourceObjective = "Forscher Jaren hat Euch gebeten, entlang der Küste des Frostmaares wahllos 15 Diener der Geißel zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", completion = "<Jaren wirkt sehr erfreut über Euren Erfolg, macht jedoch Zeichen, dass Ihr flüstern sollt.>\n\nGute Arbeit, {name}! Eure Kleidung hat jedoch eine Menge von diesem klebrigem Geißelzeugs abbekommen. Vielleicht solltet Ihr Euch über ein kurzes Bad Gedanken machen. Das Wasser ist zwar kalt, wird Euch jedoch im Nu von dem Dreck befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[11395] = { id = 11395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist eine Vorrichtung der Geißel", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nForscher Jaren würde sicherlich gerne einen Blick darauf werfen.", sourceObjective = "Liefert die Vorrichtung der Geißel bei Forscher Jaren an der Küste des Frostmaares ab.", progress = "Was für ein seltsam anzusehendes Gerät Ihr da habt, {class}. Lasst mich einmal einen besseren Blick drauf werfen.", completion = "Ich weiß, was das ist! {name}, es ist eine Steuerung für diese geißelnden Kristalle!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11396] = { id = 11396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schilde abschalten", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass man mithilfe der Steuerung dessen Schild abschalten könnte, wenn man nur nahe genug an einen der geißelnden Kristalle herankäme. Danach müsste das Ding nur rechtzeitig zerstört werden, bevor es seinen Schild wieder aktiviert.\n\nWas sagt Ihr dazu, {name}? Lust? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs ist das Mindeste, was wir tun können, um die Geißel daran zu hindern, noch mehr Ihresgleichen zu erschaffen.", sourceObjective = "Forscher Jaren an der Küste des Frostmaares hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", completion = "Sehr schön!\n\n<Jaren wendet seinen Blick hastig in alle Richtungen, um nachzusehen, ob auch niemand seinen Ausbruch bemerkt hat.>\n\nGut, Ihr habt es Euch redlich verdient, hiervon eines auszusuchen - ich fand sie, als ich dort unten war.\n\nUnd {name}, sagt Irena, dass ich sie liebe und dass es mir gut geht, falls Ihr wieder beim Stählernen Tor vorbeischauen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11397] = { id = 11397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, Murlocs würden schlecht riechen!", description = "Ich bin hierhergekommen, um ein Gerücht zu untersuchen, nach dem die Geißel hier in der Nähe präsent sei. Ich hatte zwar erwartet, entlang der Küste dort unten Murlocs vorzufinden, doch ich hätte nie und nimmer gedacht, dass ich so etwas sehen würde!\n\nDie Diener der Geißel sind dort unten und sie verwandeln Murlocs und überhaupt alles, was sie in die Finger bekommen, in wandelnde Tote!\n\n{class}, wir werden es nicht hinnehmen, dass sie noch mehr Ihresgleichen erschaffen - ganz besonders nicht aus Murlocs! Nicht weit weg vom Lager, im Nordwesten, befindet sich eine Rampe, die hinunter zum Strand führt. Seht zu, dass Ihr Euch rechtzeitig um die Geißel kümmert!", sourceObjective = "Apothekerin Anastasia möchte, dass Ihr entlang der Küste des Frostmaares wahllos 15 Diener der Geißel vernichtet. Kehrt zu ihr zurück, sobald Ihr Eure Aufgabe erledigt habt. Sie befindet sich im Apothekerlager.", completion = "<Anastasia scheint sich eine Zeit lang Gedanken über Euren Erfolg zu machen.>\n\nIhr habt Eure Aufgabe sicherlich zufriedenstellend erledigt, doch irgendwie habe ich das Gefühl, als müssten wir etwas anderes tun, um der Geißel auf diesem Strand Einhalt zu gebieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11398] = { id = 11398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist eine Vorrichtung der Geißel", description = "Der Diener der Geißel, den Ihr soeben erlegt habt, hielt in seinen Klauen dieses Gerät. In ihm eingefasst, befindet sich ein Juwel, ähnlich den Juwelen, welche die Spitze geißelnder Kristalle bilden.\n\nApothekerin Anastasia würde sicherlich gerne einen Blick darauf werfen.", sourceObjective = "Liefert die Vorrichtung der Geißel bei Apothekerin Anastasia im Apothekerlager ab.", progress = "Was habt Ihr denn da, {class}? Lasst mich einmal einen besseren Blick darauf werfen!", completion = "Ich kann Euch sagen, was das hier ist, {name}. Es ist ein Steuergerät für die geißelnden Kristalle dort unten!\n\nIch würde alles darauf verwetten, dass man mit ihrer Hilfe die Kraftfelder abschalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11399] = { id = 11399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schilde abschalten", description = "Seht Euch den Knopf an der Seite der Steuerung an - hier. Ich könnte wetten, dass, käme man nahe genug an einen der geißelnden Kristalle heran, man mithilfe der Steuerung dessen Schild abschalten könnte. Danach müsste man das Ding nur rechtzeitig zerstören, bevor es seinen Schild wieder aktiviert.\n\nMutig genug, einen weiteren Abstecher dort hinunter zu wagen, {name}? Ich kann Euch versprechen, dass eine nette Belohnung winken würde, brächtet Ihr es zustande, die Schilde abzuschalten und die Kristalle zu zerstören.\n\nEs würde weniger Diener der Geißel bedeuten und dazu noch aus Murlocs geschaffene: Wie könntet Ihr es dann auch ablehnen?", sourceObjective = "Apothekerin Anastasia im Apothekerlager hat Euch gebeten, 3 geißelnde Kristalle zu zerstören.", completion = "<Anastasia dreht sich um und wirft ihrer Sukkubus ein Lächeln zu.>\n\nAlso gut, {name}, ich gestehe, dass Ihr gewiss verdient habt, Euch hiervon eins auszusuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Pol Bernruh, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Pol Bernruh in der Nähe des Eingangs zum Braufestplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11402] = { id = 11402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clayton's Quest: Extreme!" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Durotar, Brill oder beim Falkenplatz.", progress = "Schön, Euch wiederzusehen, {name}. Ich bin sicher, die Kinder freuen sich schon auf die Geschichten über Eure Heldentaten.", completion = "Was sagt Ihr? Dieser heilige Foliant gehörte einst einem gefallenen Paladin der Allianz. War er der kopflose Reiter? Also wurde er endlich besiegt?\n\nWas für ein glorreicher Tag, {name}! Eure Legende wird wachsen! Möge man noch von Euch berichten, wenn die Schreckensherrschaft des kopflosen Reiters längst vergessen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11406] = { id = 11406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles muss bereit sein", description = "Hauptmann Adams erwartet, dass alle Vorbereitungen in Fort Wildervar getroffen sind, sobald das Expeditionskorps gen Norden zieht. Die dortigen Späher und Handwerker wurden damit beauftragt, die Ausrüstungen und Rationen unserer Männer für den Aufstieg in die Hügel bereitzustellen.\n\nDer Hauptmann ist für sein hitziges Temperament berüchtigt, also möchte ich jemanden vorausschicken, um nach den Vorbereitungen zu sehen. Fort Wildervar befindet sich weit im Nordosten, jenseits von Skorn, in dem schneebedeckten Gebiet, das an die Grizzlyhügel grenzt. Sucht dort nach Gil Grisert und sorgt dafür, dass er bereit ist.", sourceObjective = "Sprecht mit Gil Grisert in Fort Wildervar.", completion = "Der Rüstmeister hat Euch also geschickt?\n\n<Gil wirkt erleichtert.>\n\nUm ehrlich zu sein, hinken wir hier ein bisschen hinterher und bräuchten etwas Hilfe, wenn wir unsere Ziele erfüllen wollen.\n\n<Gil läuft es kalt den Rücken hinunter.>\n\nKeiner meiner Männer hat Lust, Hauptmann Adams' Zorn die Stirn bieten zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Brauerei Drohn!", description = "Ihr wollt dem Braufest also zu Stärke und Ehre verhelfen. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nWir werden Euch einen Rennwidder für 4 Minuten borgen. Hier, nehmt auch diese Rennzügel.\n\nSeid aber vorsichtig. Diese geizigen Goblins haben entlang der Strecke keine Apfelkisten aufgestellt.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt Euer Wort gehalten und die Kunde von unseren Braumeistern verbreitet. Vielen Dank. Wir haben Euch diese Lose versprochen, hier habt Ihr sie. Ich kann mir gut vorstellen, dass die Trolle ihre Lose nicht so einfach rausrücken...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für T'chalis Voodoobrauerei!", description = "Wir müssen alle wissen lassen, dass die Trolle auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nIch werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge. Hier, nehmt auch meine Rennzügel.\n\nSeid aber vorsichtig. Die Goblins haben entlang der Strecke keine Apfelkisten aufgestellt... so was von geizig.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt's wirklich gemacht! Wir müssen uns gleich auf den Ansturm der Besucher vorbereiten, die sicher schon auf dem Weg sind! Danke!\n\nOh, richtig, wir hatten Euch eine Belohnung versprochen. Das dürfen wir natürlich nicht vergessen...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", progress = "Kommt Ihr mit dem Reitwidder zurecht?", completion = "Hey, das war gar nicht schlecht... seid Ihr sicher, dass Ihr kein Zwerg seid?\n\nEs gibt noch viel mehr Rennen, nicht nur von meiner Seite. Ihr werdet auf dem gesamten Braufestplatz Leute finden, die nach einem ordentlichen Widderrennmeister suchen. Also dann, macht Euch selbst mal nützlich.\n\nOh! Nicht, dass Ihr's vergesst, diese Widder wurden auf legale Weise erworben. Nur damit wir uns verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11410] = { id = 11410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", description = "Die Barbe, die Ihr gebracht habt, sollte zwar ein guter Köder für die meisten Fische sein, doch ich befürchte, dass sie die Aufmerksamkeit eines Monsters erregen wird!\n\nAls ich das erste Mal hier war, brachte ich ein wenig von Nat Pagles Lieblingsköder an meinem Haken an und warf ihn ins Wasser aus. Allerdings klammerte sich ein riesiges Monster mit mächtigen Zähnen und Eiszapfen, die von seinen Flossen hingen, daran fest!\n\nEs hätte mich ins eisige Wasser gezogen, hätte ich die Leine nicht durchschnitten! Ich kann den neuen Köder nicht benutzen, solang' sich niemand um die alte Frostflosse kümmert. Nehmt diesen Köder und werft ihn in der Nähe des versunkenen Bootes in der Mitte des Sees aus. Frostflosse wird nicht widerstehen können!", sourceObjective = "Christopher Sloan in Fort Wildervar möchte, dass Ihr Frostflosse besiegt.", completion = "Endlich können wir in Ruhe fischen gehen! Aber es wird sowieso darauf hinauslaufen, dass sobald wir etwas fangen, das Expeditionskorps eintreffen und alles für sich beanspruchen wird.\n\nHabt unseren Dank, {name}. Fühlt Euch hier bei uns wie Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11411] = { id = 11411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager der Winterhufe", description = "Auf meinen Reisen als Kurier habe ich schon viele seltsame Bewohner des Heulenden Fjords gesehen, doch eine Gruppe stach mir besonders ins Auge. Aus der Ferne sehen sie aus wie Tauren, doch bei näherer Betrachtung kann man erkennen, dass sie völlig verschieden sind - stämmiger und zotteliger.\n\nIch fand eine ihrer Siedlungen weit im Norden, jenseits von Halgrind, Skorn und den nördlichen Wäldern. Das Lager der Winterhufe, so wird es genannt. Es liegt inmitten der Ausläufer des Gjalerhorn, nahe der Grenze zu den Grizzlyhügeln. Nehmt Kontakt mit ihnen auf und seht nach, ob sie für uns von Nutzen sein könnten.", sourceObjective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin und zurück", description = "Ich bin froh, dass Ihr hier seid. Wir haben einiges um die Ohren! Der Goblin, der uns mehr Gebräu bringen sollte, hatte auf seinem Weg von der Messerbucht hierher einen Unfall. Ihr müsst uns das Gebräu zustellen!\n\nIch werde Euch auf einen meiner Rennwidder setzen und Ihr folgt einfach der Straße zur Messerbucht.\n\nSobald Ihr nahe genug seid, wird man Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es einem meiner fähigen Assistenten zu. Wir brauchen drei Fässchen. Erledigt Eure Sache gut, dann haben wir eventuell weitere Aufträge für Euch.", sourceObjective = "Holt bei dem Goblin, der auf der Straße zur Messerbucht festsitzt, ein Fässchen ab und bringt es zu Widdermeister Rays Assistenten. Macht das Ganze dreimal, bevor Euer Widder verschwindet.", completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist, die Dunkeleisenzwerge immer wieder angreifen und unser Lieferant irgendwo feststeckt, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nHier sind die Marken, die wir Euch versprochen haben. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11414] = { id = 11414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat unter den Brüdern", description = "Behüterin Mondblatt ist in meinen Träumen erschienen! Ein Freund von ihr, ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und such' nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11415] = { id = 11415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat unter den Brüdern", description = "Weiser Nebelläufer ist in meinen Träumen erschienen! Ein Freund von ihm ist ein Freund von mir.\n\nBis zum letzten Vollmond war ich der Alphaworg meines Rudels, doch dann kam der weiße Worg Garwal aus dem Norden und mithilfe meiner einstigen Brüder stieg er sehr schnell zum Alphaworg auf. Er hat irgendetwas Unnatürliches an sich.\n\nUm mir zu helfen, musst du zuerst diejenigen töten, die mich verraten haben.\n\nBjomolf jagt nordwestlich eines Ortes, den man das Stählerne Tor nennt. Und suche nach Varg: Er befindet sich im Südosten, in der Nähe des Westspeerturms.\n\nDein Aussehen wird sie nicht täuschen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", completion = "Der Geruch von Blut auf deiner Schnauze gefällt mir. Brüder sollten sich nicht gegenseitig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11416] = { id = 11416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Adlers", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen oder riechen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren.", progress = "Hast du die Augen des Adlers dabei?", completion = "<Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.>\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", sourceObjectiveStatus = "unverified-source-field" }
quests[11417] = { id = 11417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Adlers", description = "Garwal verbirgt sich hinter einem Schleier unnatürlicher Magie. Niemand kann ihn sehen, außer er wünscht es. Eine Möglichkeit haben wir jedoch.\n\nMein Feind, der große Adler Klauenwürger, besitzt Augen, so sagt man, denen nichts entgeht. Nähmest du also seine Augen, würdest du Garwal sicherlich sehen können.\n\nKlauenwürgers Nest befindet sich am Ende des Wasserfalls, gleich südwestlich des Vrykuldorfs namens Skorn. Berührst du die Eier in seinem Nest, wird er vom Himmel kommen, um dich zu töten.\n\nHol' dir seine Augen.", sourceObjective = "Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.\n\nFalls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren.", progress = "Hast du die Augen des Adlers dabei?", completion = "<Ulfang heult lauthals, als er von Eurem Sieg über seinen Feind, den großen Adler, erfährt.>\n\nDass du ihn erlegt hast, macht dir alle Ehre. Ich wünschte, es wäre mein Maul gewesen, dessen Biss sein Ende herbeiführte.\n\nDas Opfer, welches er für uns erbrachte, soll nicht vergebens gewesen sein. Hier, friss!", sourceObjectiveStatus = "unverified-source-field" }
quests[11418] = { id = 11418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir nennen ihn Stahlfeder", description = "Wir konnten beobachten, wie ein mutiger Hippogryph über dem Fort kreist, schließlich im Sturzflug nach unten schnellt und Beute macht. Jethan dort drüben hat schon ein paar Schüsse auf ihn abgegeben, aber seine Pfeile prallten einfach ab!\n\nWir haben uns daran gewöhnt, diese bemerkenswerte Kreatur Stahlfeder zu nennen, doch weshalb es die Gegend um Fort Wildervar herum bevorzugt, wissen wir nicht. Die meisten Hippogryphen nehmen sich vor Menschen in Acht.\n\nForscher Aderan hat uns dabei geholfen, aus einer der Federn der Kreatur einen Glücksbringer herzustellen. Er behauptet, dass es dem Benutzer erlaubt, die Welt durch Stahlfeders Augen zu sehen.", sourceObjective = "Spürt Stahlfeder auf, der über Fort Wildervar kreist, und benutzt den gefiederten Glücksbringer, um hinter sein Geheimnis zu kommen. Berichtet Gil Grisert anschließend von dem, was Ihr herausgefunden habt.", progress = "Hat Aderans Glücksbringer funktioniert?", completion = "Ihr habt ein Nest mit Jungen gesehen? Hmm, also ist unser \"er\" eigentlich eine \"sie\", oder?\n\nIch denke, dass sich damit die Sache erledigt hat. Ich würde es auch nicht wollen, dass man ein Nest voller Jungen nur deswegen an einen anderen Ort bringt, weil es einen neuen Nachbarn gibt.\n\n<Gil wirft Fallensteller Jethan einen spöttischen Blick zu.>\n\nBin mir sicher, dass wir gut miteinander auskämen, wenn der gute Jethan nicht versuchen würde, aus ihr eine Trophäe zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Driz Purzelfix, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Driz Purzelfix in der Nähe des Eingangs zum Braufestplatz in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[11420] = { id = 11420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zur Vergeltung", description = "Vor zwei Wochen hat unser Chefingenieur eine Harpunenkanone der Vrykul in die Finger bekommen - dieselbe Art Kanone, die diese Vrykul benutzen, um unsere Schiffe auszuschalten. Durch die Studien dieser Waffe konnte er eine umfangreiche Betriebsanleitung zusammenstellen.\n\nLeider wurde er gefangen und in das Dorf Wyrmskol nördlich von hier verschleppt. Wir haben ihn dann letztendlich gefunden, doch da lag er im Sterben und hatte die Anleitung nicht mehr bei sich. Seine letzten Worte deuten darauf hin, dass die Anleitung in den Katakomben von Utgarde verloren gegangen ist - jenem Ort, der sich im nordwestlichen Teil von Wyrmskol befindet. Besorgt mir diese Anleitung!", sourceObjective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr die Harpunenbetriebsanleitung zurückholt.", progress = "Habt Ihr die Anleitung gefunden?", completion = "<Zorek blättert die Anleitung durch.>\n\nDer Anleitung nach haben die Vrykul ein Spezialwerkzeug, welches ihnen erlaubt, die Harpunen mit tödlicher Präzision zu bedienen. Es sieht ein bisschen wie das Rad eines unserer Schiffe aus. Zudem ist es tragbar und scheint wie ein Schlüssel in die Harpunen zu passen. Wir müssen eines davon in die Finger bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11421] = { id = 11421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt drehen wir mal richtig auf...", description = "Wir müssen zuschlagen, solange die Verwirrung unter den Truppen der Vrykul anhält! Nehmt den Harpunenkontrollmeachanismus an Euch und sucht entlang der Klippen das am nördlichsten gelegene Harpunengebäude des Dorfes.\n\nNehmt eine der vrykulschen Harpunenkanonen auf dem Dach des Gebäudes in Euren Besitz, sobald Ihr dort seid, und macht Wyrmskol die Hölle heiß! Zerstört das Lang- und Dockhaus, das Lager und sämtliche Verteidiger, die die Vrykul auf Euch hetzen könnten!\n\nSolltet Ihr dies vollbringen, wird die Dolchbucht ein viel sicherer Hafen sein!", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Langhaus der Drachenschinder, das Dockhaus der Drachenschinder, das Lager der Drachenschinder und 8 Verteidiger der Drachenschinder vernichtet.\n\nBringt den Harpunenkontrollmechanismus zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", progress = "Steht Wyrmskol in Flammen?", completion = "Ausgezeichnete Arbeit, {name}! Ihr habt einen guten Teil dieser Drachenreiter ausgeschaltet und ihre Führung richtig sauer gemacht.\n\nSeid Ihr bereit, nach Valgarde zurückzukehren und Zorek die guten Neuigkeiten zu überbringen? Falls dem so ist, dann hätte ich da eine verrückte Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[11422] = { id = 11422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreizack des Sohnes", description = "<Die Kratzer, die er in den Felsen ritzt, stellen mehrere Symbole dar: einen Dreizack, einen Mur'ghul, die Sonne, ein Schiffswrack und ein grobes Strichmännchen, welches Euch darstellt.>\n\n<Es braucht einige Zeit dahinterzukommen, was Euch der Murloc mitteilen möchte. Offensichtlich will er, dass Ihr ihm einen Dreizack von der Küste des Frostmaares besorgt, doch was das Bild der Sonne bedeuten soll, ist Euch ein Rätsel - zumindest bis Ihr erkennt, dass er damit seinen Sohn meint.>\n\n<Sein Sohn wurde in einen Mur'ghul verwandelt! Er möchte, dass Ihr nach Süden geht, in der Nähe des Schiffswracks nach ihm sucht und seinen Dreizack zurückbringt.>", sourceObjective = "Alte Eisflosse möchte, dass Ihr Rottkiems Dreizack zurückholt. Er wohnt auf der kleinen Insel an der Küste des Frostmaares.", progress = "<Alte Eisflosse beäugt Euch mit einem seiner toten Augen und sucht nach Zeichen des Dreizacks seines Sohnes.>", completion = "<Als er seine Hand ausstreckt, um den Dreizack von Euch in Empfang zu nehmen, zittert diese ein wenig. Könnte es sein, dass der gealterte Murloc trauert?>\n\n<Was sammelt sich da für eine Flüssigkeit in seinem Auge?>", sourceObjectiveStatus = "unverified-source-field" }
quests[11423] = { id = 11423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Feindes", description = "Während unsere Armeen durch Nordend marschieren, werden unsere Feinde nicht nur Niederlage um Niederlage erleiden müssen. Ihre Häuser werden in Flammen stehen, unsere Seuchen werden ihre Leichen zerfressen, jede Spur ihrer Existenz wird vom Erdboden getilgt sein.\n\nFür jemanden wie mich, den es nach Wissen dürstet, ist das beunruhigend. Niffelvar, die Stadt im Osten, wird bald von unseren Streitkräften aus dem Hafen der Vergeltung ausgelöscht werden. Helgus, der Barde der Vrykul, lebte dort und schrieb drei Sagen: Die Sage der Zwillinge, die Sage des Winterfluchs und die Sage der Val'kyr. Besorgt diese, bevor Niffelvar dem Erdboden gleich gemacht wird.", sourceObjective = "Reist nach Niffelvar nördlich des Geisterklingenpostens und sucht die Sage des Winterfluchs, die Sage der Val'kyr und die Sage der Zwillinge.", progress = "Die Schriftrollen, {name}? Habt Ihr sie?", completion = "Dies ist von enormem Wert, {name}. Ich muss meine Anstrengungen erneut aufnehmen, Texte der Vrykul zu übersetzen.\n\nVersteht mich nicht falsch. Unsere Feinde müssen vernichtet werden... nicht so ihr uraltes Wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11424] = { id = 11424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildhügel", description = "Meine Arbeit sollte in Kriegszeiten eigentlich ziemlich leicht sein - es müsste überall brauchbare Körperteile geben.\n\nDoch so einfach ist es nicht. Wenn diese Eierköpfe alles Mögliche an tödlichen Plagen in den feindlichen Dörfern freisetzen, werden dabei die meisten Materialien verunreinigt.\n\nEs gibt jedoch einen Ort, an dem sich brauchbare Exemplare finden lassen. Der Schildhügel südlich von hier ist ein alter Friedhof der Vrykul. Dort laufen die Toten noch herum, sind aber frei von irgendwelchen Seuchen - sowohl von unseren als auch denen des Lichkönigs. Besorgt mir ein paar Knochen und ich werd' Euch gut bezahlen.", sourceObjective = "\"Eisensäge\" Jenny möchte, dass Ihr 5 alte Knochen der Vrykul von den wiederauferstandenen Vrykul beim Schildhügel südlich von Neu-Agamand besorgt.", progress = "Habt Ihr nun meine Knochen?", completion = "Hmpf... die werden erstmal reichen. Irgendwas scheint mit ihnen nicht zu stimmen.\n\nIch sag's Euch, ich hantiere schon seit Jahren mit Körperteilen herum, aber ich hatte noch nie so'n komisches Gefühl im Bauch. Wie dem auch sei, Geschäft ist Geschäft. Hier ist Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11426] = { id = 11426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mechanismus ausfindig machen", description = "Macht Euch keine Sorgen, {name}; all dies wird zu etwas Großem führen! Etwas RIESIGEM! Ihr müsst mir nur erst einmal vertrauen und tun, wie ich es Euch sage.\n\nFür die nächste Stufe des Planes, müssen wir einen in der Anleitung erwähnten Mechanismus besorgen. Ich habe den starken Verdacht, dass Ihr einen bei einem dieser Vrykuls finden werdet, welche die Harpunenkanonen in Wyrmskol bedienen. Ihr werdet sie auf der Ostseite des Dorfes an den Docks bei den Langhäusern finden.", sourceObjective = "Wachoffizier Zorek bei Valgarde am Heulenden Fjord möchte, dass Ihr ihm einen Harpunenkontrollmechanismus bringt.", progress = "Habt Ihr den Mechanismus gefunden?", completion = "Überragend! Diese zu groß geratenen Affen werden bald merken, was es heißt, sich mit der Allianz anzulegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11427] = { id = 11427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Leutnant Eishammer", description = "Seht Ihr diese Gebäude der Vrykul auf den Klippen im Nordosten? Die Vrykul nennen diesen Ort Niffelvar. Von dort aus kommen die meisten Ihrer Harpunenangriffe auf unsere Fregatten.\n\nDoch wisst Ihr was? Es ist Zeit es ihnen heimzuzahlen, {name}. Nehmt diesen Harpunenkontrollmechanismus und trefft Euch mit Leutnant Eishammer, der sich in einem Gebäude der Vrykul im Nordwesten von Niffelvar versteckt hält.\n\nWenn Ihr bereit seid, könnt Ihr Euch auf einen meiner Greifen schwingen und Ihr werdet schnurstracks zu ihm gebracht!", sourceObjective = "Wachoffizier Zorek möchte, dass Ihr den Harpunenkontrollmechanismus zu Leutnant Eishammer außerhalb von Niffelvar bringt.", progress = "Was ist das denn? Sehe ich aus wie ein Kindermädchen?", completion = "<Leutnant Eishammer nimmt Euch den Harpunenkontrollmechanismus ab.>\n\nAh, Ihr bringt Geschenke!", sourceObjectiveStatus = "unverified-source-field" }
quests[11428] = { id = 11428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter Welkblatt", description = "Eure Freundschaft und Unterstützung haben uns schon viel geholfen, {name}. Es gibt jedoch noch eine Sache, um die ich Euch bitten muss.\n\nIhr habt sie gesehen, die Verderbnis, welcher die Siechende Lichtung und die dort lebenden Biester anheim gefallen sind. Die schwarzbeseelten Bewahrer werden diese Monstrositäten weiterhin aus den Wassern und der Erde unserer Lichtung auferstehen lassen, wenn wir nichts gegen sie unternehmen.\n\nDer mächtigste unter den schwarz beseelten Bewahrern wird Hüter Welkblatt genannt. Tötet ihn, {name}, und Ihr werdet damit den Weg zur Errettung der Lichtung ebnen, so wie Ihr einst den Weg zur Errettung meiner Schwestern ebnetet.", sourceObjective = "Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr Hüter Welkblatt tötet.", completion = "Als ich hörte, dass die Bewahrer sich gegen uns gewendet hatten, brach mir das Herz. Einst betrachteten wir sie als unsere Brüder und engsten Freunde.\n\nMeine Trauer gilt unseren verlorenen Brüdern und Schwestern, doch ohne Eure Hilfe gäbe es für uns keine Hoffnung auf die Zukunft. Ihr werdet hier unter uns immer willkommen sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11429] = { id = 11429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstellen und abrocken!", description = "Ich habe nicht die Absicht, das Schicksal dieser Mission in die Hände irgendeines Möchtegerns zu legen, der noch nicht auf die Probe gestellt wurde.\n\nWenn Ihr mir also beweisen wollt, dass Ihr das Zeug dazu habt, diese Mission auszuführen, werdet Ihr das machen müssen, was ich Euch sage.\n\nNehmt diese Schlachtstandarte und macht Euch auf den Weg nach Quälheim, gleich nördlich von hier. Begebt Euch zur Ortsmitte und stellt unsere Flagge auf, sobald Ihr dort angelangt seid. Wehrt sämtliche Vrykuldrecksäcke, die versuchen sollten, unsere geliebte Flagge zu beseitigen, ab und kehrt zu mir zurück, sobald Ihr die Vorherrschaft der Allianz gesichert habt.", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr das Banner der Allianz in Quälheim aufstellt und dieses gegen Angreifer verteidigt.\n\nKehrt gemeinsam mit dem Banner zu Leutnant Eishammer zurück, falls Ihr überleben solltet.", progress = "Noch immer am Leben, wie ich sehe. Offensichtlich strengt Ihr Euch nicht richtig an.", completion = "Für die Allianz! Ihr beweist Stärke, {name} - genug, um einigen Vrykul in Niffelvar die Schädel einzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11430] = { id = 11430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpunenmeister Yavus", description = "Das war eine ziemlich eindrucksvolle Vorstellung, die Ihr da geliefert habt, {name}. Doch bevor Ihr Euch selbst auf die Schulter klopft: In Niffelvar gibt es noch Arbeit zu erledigen.\n\nWir haben den Vrykul, der für die meisten Harpunenangriffe auf unsere Fregatten verantwortlich ist, ausfindig gemacht - nennt sich Yavus. Ihr findet ihn in der Hauptharpunenanlage an den Klippen von Niffelvar, südlich von hier.\n\nSpürt ihn auf und richtet ihn für seine Verbrechen gegen die Allianz!\n\nMacht mich stolz, {name}!", sourceObjective = "Leutnant Eishammer im Heulenden Fjord möchte, dass Ihr Harpunenmeister Yavus in Niffelvar tötet.", completion = "Sie werden einige Zeit brauchen, um Yavus zu ersetzen. Jetzt ist der perfekte Zeitpunkt, um Zoreks Plan in die Tat umzusetzen! Während sie sich eiligst darum kümmern, Niffelvar wieder unter ihre Kontrolle zu bringen, werdet Ihr ihre eigenen Harpunenkanonen in Besitz nehmen und gegen sie verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt die wilden Wolpertinger!", description = "Hey, Ihr da. Ich bin ein verrückter Zwerg! Wir Zwerge glauben, dass man unsichtbare Kreaturen sehen kann, wenn man nur mit ausreichend Gebräu versorgt ist. Wahrscheinlich wandern sie genau in diesem Moment auf dem Braufestplatz umher! Ihr könnt sie aber nur sehen, wenn Ihr betrunken seid.\n\nWir Zwerge finden immer einen Grund, um zu trinken.\n\nIhr wollt doch bestimmt auch einen Grund haben, um zu trinken... Also, bringt mir fünf Wolpertinger mithilfe dieses Netzes, das ich von einem wirklich betrunkenen Zwerg habe.\n\nWenn Ihr sie nicht sehen könnt, seid Ihr wahrscheinlich nicht betrunken genug.", sourceObjective = "Der \"Zwerg\" Glodrak Jägerspatz möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr entweder ordentlich betrunken sein oder eine Syntheholbrille tragen müsst, um die Biester sehen zu können.", progress = "Habt Ihr etwas für mich oder sucht Ihr nur wieder nach einem Grund, um Euch zu betrinken?", completion = "Was! Es gibt sie wirklich? Jetzt tut es mir richtig leid, dass ich diesem Zwerg gegen das Knie getreten habe...\n\nIch brauche eine Minute... und einen Schluck...\n\n<Er trinkt aus seinem Krug.>\n\nIch denke, ich überlasse Euch einen... als Beweis dafür, dass betrunkene Zwerge - gibt es überhaupt andere? - wirklich die Wahrheit sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11432] = { id = 11432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Riesen", description = "Ich habe zufällig mit anhören können, über was Ihr mit Vater Levariol gesprochen habt. Erlaubt mir, Euch darauf hinzuweisen, dass der Auftrag, den er Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", sourceObjective = "Magierleutnant Malister hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich in Westwacht.", completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass gewisse Leute das Töten Wehrloser als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11433] = { id = 11433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Riesen", description = "Ich habe zufällig mit anhören können, über was Ihr mit Großmutter Ankha gesprochen habt. Bei allem Respekt, aber ich meine, dass der Auftrag, den sie Euch erteilt hat, nicht weit genug geht.\n\nIhr müsst Euch auch um die Vrykul kümmern, die in den Hallen des Erwachens tief im Fels unter Gjalerbron im Schlaf liegen!\n\nIch hege keine Zweifel daran, dass die Rituale, mit deren Hilfe man sie erweckt, der Schlüssel zu ihrem Untergang sind. Die Nekrolords verfügen höchstwahrscheinlich über irgendeine Vorrichtung, mit der Ihr die Vrykul vorzeitig aus ihrem Schlaf reißen könnt.\n\nSolch eine Behelligung wird sich für die Vrykul als fatal erweisen.", sourceObjective = "Ahota Weißfrost hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich im Lager der Winterhufe.", completion = "Ihr habt getan, was getan werden musste. Es mag vielleicht sein, dass die Unklugen das Töten Hilfloser während sie aufwachen als unehrenhafte Tat betrachten, doch in diesem Fall wäre es töricht gewesen, nicht so zu handeln.\n\nUnd wir hätten sie doch nicht einfach so dort herumstehen lassen können, nur damit sie später durch ein Ritual erweckt werden, oder?\n\nEs war eine mutige Sache, die Ihr dort unten in den Katakomben für uns alle hier oben geleistet habt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11434] = { id = 11434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Schätze", description = "Ich hab' ein Vermögen gemacht, weil ich mich auf Schätze spezialisiert hab', auf die gewöhnliche Piraten keinen Wert legen: Kunst, Antiquitäten, Sammlerstücke.\n\nSüdlich von hier ist die Stelle, an der die Flotte vom schwarzen Konrad vor Jahren einmal sank. Doch Taucher haben alles an Gold und Juwelen weggeschafft - nichts ist übrig geblieben, bis auf zwei uralte Artefakte. Eins davon ist eine Amanivase in Museumsqualität, das andere ist eine Adlerfigurine.\n\nGeht, beschafft mir die Dinger und ich werd' ein gutes Wörtchen für Euch bei den anderen Piraten einlegen. Ich würd' sogar was beisteuern, damit sich Euer Unterwasserabenteuer etwas leichter bewältigen lässt.", sourceObjective = "Der hübsche Terry im Halunkeneck möchte, dass Ihr ihm 1 Amanivase und 1 Adlerfigurine aus dem Schiffswrack gen Süden holt.", progress = "Habt Ihr meine Relikte beschaffen können, {name}? Mit Schönheit alleine kommt man im Leben auch nicht über die Runden... selbst ich nicht!", completion = "Gemeinsam werden wir's zu was bringen, {name}. Mit meinem guten Aussehen und Eurem... unerschütterlichen Optimismus werden wir sicherlich ein dickes Geschäft machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11436] = { id = 11436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehen wir Harpunenreiten!", description = "An den steilen Klippen des Heulenden Fjords vorbeizunavigieren, kann ein nervenaufreibendes Unterfangen sein! Ich hab' jedoch herausgefunden, wie man mithilfe von Vrykultechnologie und zwergischer Raffinesse etwas herstellen kann, das die Sache einfacher gestalten wird. Es hat nur ein paar Einstellungen und Feinabstimmungen gebraucht und Eishammers Harpunensteuerung war fertig! Natürlich wurde sie noch nicht getestet, aber deswegen seid Ihr ja hier!\n\nNehmt die Steuerung, geht zur großen Kanone in Niffelvar und katapultiert Euch mit ihrer Hilfe nach Valgarde. Erstattet Zorek Bericht, falls Ihr Erfolg haben solltet. Oh ja, da fällt mir ein: Ihr könnt die Steuerung behalten.", sourceObjective = "Katapultiert Euch mithilfe der großen Harpunenkanone der Vrykul nach Valgarde. Erstattet Wachoffizier Zorek Bericht, falls Ihr Erfolg haben solltet.", progress = "<Zorek blickt Euch an und hebt eine Braue.>", completion = "Ihr seid verrückt, {name}! Jetzt mal ehrlich: Welcher Trottel würde eine Harpunenkanone als Beförderungsmittel verwenden?\n\nIch denke jedoch, dass man ein wenig verrückt sein muss, um das abzuziehen, was Ihr dort oben an den Klippen abgezogen habt! Fantastische Arbeit! Wir haben Nachricht erhalten, dass Ingvar, der Anführer der Drachenschinder, vor Wut nur so tobt! Vielleicht werdet Ihr ihn eines Tages in den Boden stampfen können - im Namen unserer geliebten Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Jetzt, da der kopflose Reiter in der Gegend ist, sind die mutigen Zwerge von Kharanos jederzeit für einen Einsatz der Brandwache bereit. Wollt auch Ihr helfen?\n\nDie Gebirgsjäger haben südlich von hier ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind die Friedensbewahrer jederzeit bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nDie Friedensbewahrer haben westlich von hier, in Richtung der Exodar, ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mithilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Eisenschmiede, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?" }
quests[11443] = { id = 11443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchgang in der Dolchbucht", description = "Hä... ähm... Was ist los? Was macht Ihr dort unten?\n\nIch? Oh... nun ja, seht Ihr... ich bin... ähm... Ich versuche hier ein wenig aufzuräumen! Befehl von Keller höchstpersönlich! \"Harry,\" hat er zu mir gesagt, \"ich will, dass du dir 'ne Tauchglocke aufsetzt und in den Schiffswracks in der Dolchbucht nach UNSEREM Zeugs suchst...\"\n\nHe, wenn Ihr schon mal hier unten seid, vielleicht könntet Ihr mir dann helfen. In der ganzen Bucht liegen allerhand Schmuckstü... ähh, ich meine Vorratskisten herum. Geht und bringt mir alles, was Ihr finden könnt. Setzt Euch den Taucherhelm auf, damit Euch die Luft nicht ausgeht.", sourceObjective = "Harold Lagras auf dem Grund der Dolchbucht möchte, dass Ihr ihm 10 Vorratskisten von Valgarde bringt.", progress = "Habt Ihr die Vorratskisten gefunden?", completion = "Super! Ihr seid mit Sicherheit sehr effizient. So ist's... Ach was, gebt mir einfach die Kisten. Ich muss sie in meinem Büchlein verzeichnen, Inventur machen und ein paar andere Sachen, die Ihr nicht versteht und für die Ihr nicht ausgebildet seid, an mich nehmen. Macht Euch keine Sorgen, ich werde Keller auf jeden Fall sagen, was für tolle Arbeit Ihr hier unten geleistet habt! - genau. M-hm, Ihr könnt jetzt gehen. Husch, husch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Orgrimmar, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen." }
quests[11448] = { id = 11448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten der Forscherliga", description = "Das ist alles ein Haufen kryptischer Unsinn! Trotz dieser Glyphe werde ich aus den Tafeln einfach nicht schlau. Zugegeben, Kryptografie ist nicht eine meiner Stärken.\n\nIhr werdet die Glyphe und Tafeln zu unserem Kryptografen Stanwad bringen müssen. Unglücklicherweise habe ich seit zwei Wochen nichts mehr von Stanwad gehört. Er nahm ein Team aus zwanzig Wissenschaftlern mit zur Ausgrabungsstätte an den südöstlichen Klippen des Fjords und seitdem hat man nichts mehr von ihm gehört. Das Beste, was ich machen kann, ist es, McGoyver da drüben zu sagen, dass er Euch auf seiner Flugmaschine mitnehmen soll.", sourceObjective = "Liefert McSorfs Bündel bei Stanwad im Außenposten der Forscherliga im Heulenden Fjord ab.", progress = "<Stanwad gibt seiner Unzufriedenheit mit einem Brummen Ausdruck.>", completion = "<Stanwad nimmt Euch das Bündel ab und fängt an, die Daten zu sortieren.>\n\nUnglaublich. Wie viele Leute meint Ihr, haben für diese Informationen ihr Leben gelassen?\n\n<Stanwad schüttelt seinen Kopf.>\n\nIhr werdet Euch wahrscheinlich darüber freuen, dass das, was McSorf und sein Trupp an ausgemachten Idioten herausgefunden haben, ein uraltes Rezept für einen Tundraeintopf ist. Hat er nicht bemerkt, dass die Symbole gewöhnliche Gemüsesorten darstellen und das Piktogramm einen Humanoiden zeigt, der besagtes Gemüse mampft? Man braucht keine verdammte Glyphe, um diesen Code zu knacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Todespirscher haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Weitere Schäden an den Gebäuden von Brill können wir uns nicht leisten - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nGeht Richtung Westen am Friedhof vorbei und folgt dem Straßenverlauf, bis Ihr das Übungslager erreicht.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Brill.", progress = "Habt Ihr ein paar Feuer gelöscht, {name}? Das Übungslager liegt westlich von Brill.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Wachen haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Wir können nicht zulassen, dass der kopflose Reiter alles zunichte macht, was wir in harter Arbeit wieder aufgebaut haben - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nVerlasst die Stadt durch das südliche Tor in Richtung der Kreuzung. Dort werdet Ihr das Übungslager finden.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone beim Falkenplatz.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicias Gedicht", description = "Hi! Ich habe für meine Freundin Caylee ein Gedicht verfasst. Sie verbringt Ihre Zeit gerne bei den Aldor in Shattrath. Ihr wisst schon, in der Scherbenwelt!\n\nWärt Ihr so freundlich und würdet ihr das Gedicht bringen? Meine Mutter sagt, ich sei noch zu jung, um selbst nach Shattrath zu reisen!", sourceObjective = "Man hat Euch gebeten, Alicias Gedicht zu Caylee Dak in Shattrath in der Scherbenwelt zu bringen.", progress = "Oh, ein Gedicht?", completion = "Was für ein anrührendes Gedicht. Habt vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[11452] = { id = 11452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlummernde König", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", sourceObjective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt nach Westwacht zurück, falls Euch dies gelingen sollte, und setzt Hauptmann Adams über Euren Erfolg in Kenntnis.", completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11453] = { id = 11453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlummernde König", description = "Ein Bündel Pergament fällt aus der regungslosen Hand des Oberanführers. Auf ihm könnt Ihr die Umrisse der Rituale erkennen, die in den Katakomben unter Euch vonstattengehen.\n\nEs scheint jedoch, als hätte die Königin der Vrykul Angerboda Schwierigkeiten, König Ymiron zu erwecken. Das Ritual findet auf der Terrasse des Winters, einer großen Kammer am nördlichen Ende von Gjalerbron, statt.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht aufhalten, bevor es zu spät ist.", sourceObjective = "Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt zum Lager der Winterhufe zurück, falls Euch dies gelingen sollte, und berichtet Häuptling Aschtotem über Euren Erfolg.", completion = "Ich bin mir nicht sicher, aber der eine Teil hört sich gar nicht gut an! Dass sich der Lichkönig mit Ymiron davonmacht, kann nur Schwierigkeiten bedeuten. Bedauerlich nur, dass Ihr nicht imstande wart, ihn gemeinsam mit seiner Königin zu töten.\n\nNichtsdestotrotz, Ihr habt ihnen einen großen Strich durch die Rechnung gemacht und uns die nötige Zeit verschafft.\n\nUnd wer weiß, so viel wie Ihr herumkommt, ist es gut möglich, dass Euch König Ymiron noch einmal über den Weg laufen wird. Ich bin mir sicher, dass es ihm bei Eurer nächsten Begegnung nicht so gut ergehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Saboteure", description = "Die Angreifer der Dunkeleisenzwerge scheinen diesen Papierfetzen versehentlich zurückgelassen zu haben.\n\nObwohl die Pläne in einem verfremdeten zwergischen Dialekt verfasst worden sind, ist die Unterschrift \"Coren Düsterbräu\" eindeutig genug, genauso wie die Erwähnung der Taverne 'Zum Grimmigen Säufer', tief in den Schwarzfelstiefen. Ihr solltet den Überfällen ein Ende bereiten und den Organisator der Überfälle aufsuchen.", sourceObjective = "Sucht nach Coren Düsterbräu im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11455] = { id = 11455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft des Goldes", description = "Wir Piraten sind zwar für allerhand Dinge bekannt, doch Hygiene gehört nicht dazu. Auf den meisten Piratenschiffen befinden sich fünf oder sechs Mal so viele Ratten wie Leute.\n\nFührt man sich das vor Augen, ist es kein Wunder, dass gleich nachdem wir hierher gezogen sind, die Bären auf dieser Insel an Tollwut erkrankten. Lange Rede, kurzer Sinn: Der Boss will sie alle tot sehen.\n\nZufälligerweise hab' ich ein Rezept für ein Bärenmoschusparfüm, das unter Sturmwinds Edelleuten beliebt ist. Wir töten die Bären und verkaufen den Moschus: Das ist DIE Geschäftsmöglichkeit für uns. Was meint Ihr dazu?", sourceObjective = "Der hübsche Terry im Halunkeneck im Heulenden Fjord möchte, dass Ihr 4 Einheiten Bärenmoschus von den tollwütigen Braunbären in der Gegend besorgt.", progress = "Habt Ihr mir den Bärenmoschus gebracht, Kumpel?", completion = "Ausgezeichnete Arbeit! Es mag vielleicht nicht ganz so waghalsig sein wie das Beutemachen auf hoher See, doch ich soll verdammt sein, mir diese Gelegenheit entgehen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11456] = { id = 11456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Überlebenden zu essen geben", description = "In Sachen Nahrung sind wir Tuskarr größtenteils auf den Fischfang angewiesen. In Zeiten großer Not werden wir jedoch gelegentlich auch auf Landtiere Jagd machen.\n\nDas in der Nähe gelegene Iskaal wurde erst kürzlich von Piraten angegriffen und es kommen ständig neue Überlebende aus dem Dorf zu uns herüber.\n\nWir haben diese Woche keinen großen Fang gemacht - es gibt jedoch genug fleischbepackte Schaufelhauer auf der Insel.\n\nHelft meinem Volk bei der Jagd auf diese großen Biester und bringt uns deren Fleisch.", sourceObjective = "Urahn Atuik in Kamagua im Heulenden Fjord möchte, dass Ihr zur Insel der Speere geht und ihm 6 Stück Fleisch eines Inselschaufelhauers beschafft.", progress = "Habt Ihr das benötigte Fleisch bekommen können?", completion = "Ich danke Euch, {name}. Mein Volk erlebt Zeiten großer Not.", sourceObjectiveStatus = "unverified-source-field" }
quests[11457] = { id = 11457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamagua bewaffnen", description = "Issliruk, der Geist des Krieges, wird von meinem Volk als silberner Adler dargestellt. Unsere Geschichten über ihn berichten davon, wie er gegen einhundert Worgs kämpfte, um seine Jungen zu beschützen.\n\nAuch für uns ist nun die Zeit gekommen, dem Feind im Kampfe zu begegnen und unsere Brüder zu beschützen. Die Hörner der Frostflügelschimären, die sich in den verschneiten Teilen der Insel eingenistet haben, sind scharf und können mühelos zu Speerspitzen weiterverarbeitet werden. Bringt mir die besten Hörner, die Ihr finden könnt.", sourceObjective = "Urahn Atuik möchte, dass Ihr ihm 3 Schimärenhörner beschafft.", progress = "Schön, Euch wiederzusehen, {race}.", completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, {name}. Wir werden nicht vergessen, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11458] = { id = 11458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Iskaal", description = "Das Totem von Issliruk ist bereit, {name} - wofür ich Euch danken möchte. Fürs Erste müssen wir unsere friedlichen Sitten ablegen und einen Schlag gegen jene ausführen, die sich auf unser Land und unsere Sippe gestürzt haben.\n\nDie freibeuterischen Sklavenhändler, die für den Überfall auf Iskaal verantwortlich sind, haben ihren Verstand verloren und all ihre Gefangenen abgeschlachtet. Geht in Richtung Osten nach Iskaal und erledigt, was erledigt werden muss. Nehmt dieses Horn und ruft nach meinen Brüdern, solltet Ihr Unterstützung benötigen.", sourceObjective = "Urahn Atuik möchte, dass Ihr nach Iskaal geht und 8 Sklavenhändler des Nordmeeres niederstreckt. Macht von dem Horn von Kamagua Gebrauch, solltet Ihr Unterstützung benötigen.", completion = "Ihr seid ein großartiger Verbündeter, {name}. Mein Volk steht für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11459] = { id = 11459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeh'gehn sachd", description = "Na lucks mal so än, Mann. Bis' du schaäf drouf, unsr'oins unnä di Floss'n zu graifn un' de olle Mackreilä ans Däch zu spül'n, di moi Crew sai Gut begrapscht hät?\n\nDu wiäst mia ne Kröide aus'm Wassä zieh'n müssn, Kamerad. Jo, un' dänn wüäd mainerainer dia zaichn, wer de Radde is, Mann. Nei, nei, de Kröide wiäd's dia zaichn. Du wiäst's woul mit di eich'nen Glupschä säin müss'n.\n\nSchaff ouch mol'n richdich's Mässä rübbä, baim Klabaudamann. Nu lous, Freundschen.", sourceObjective = "Kehrt zum hübschen Terry zurück, um herauszufinden, was Zeh'gehn von Euch will.", completion = "Ihr habt kein Wort von dem verstanden, was Zeh'gehn gesagt hat? Tja, das war klar.\n\nDann lasst uns doch mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11460] = { id = 11460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen will verdient sein", description = "Der erste und wichtigste Aspekt der Falknerei ist die Bindung zwischen <dem Falkner/der Falknerin> und <seinem/ihrem> Vogel. Doch Vertrauen will <vom Herren/von der Herrin> verdient werden!\n\n<Hidalgo deutet auf die Falken im Käfig zu seinen Füßen.>\n\nUm ihr Vertrauen zu gewinnen, werdet Ihr zuerst ihre Bäuche füllen müssen.\n\nAuf dem Speiseplan der Fjordfelsenfalken, wie man diese Vögel nennt, befinden sich hauptsächlich Larven. Diese Insekten nisten unter losen Steinen, die im gesamten Fjord verstreut liegen. Findet eine Larve, kehrt hierher zurück und verfüttert sie an die Falken im Käfig.", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr nach einer Fjordlarve sucht und sie an einen der Falken im Käfig zu seinen Füßen verfüttert.", progress = "Das ist eine wichtige Übung, {name}. Wenn Ihr ein Falkner werden wollt, müsst Ihr lernen, wie man einen Vogel ernährt.", completion = "Gut, {name}. Wie ich sehe, seid Ihr schon im Begriff, Freunde zu werden - er hat Euch als Herr akzeptiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11464] = { id = 11464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielschulden", description = "Ich habe gehört, Ihr habt für Terry ein paar Sachen geregelt. Ich habe darauf gehofft, dass hier mal jemand Verlässliches auftauchen würde.\n\nWisst Ihr, Piraten lieben das Glücksspiel. Jedoch bezahlen sie nicht gern ihre Spielschulden.\n\nWenn Ihr daran interessiert seid, für mich ein paar Münzen einzukassieren, wär' ich gewillt, Euch einen Anteil abzugeben.\n\nArbeiten wir Euch mit etwas Einfachem ein. \"Silbermond\" Harry ist ein kleiner Exzentriker, bewahrt in seinem Zelt allerlei teuren Blutelfenschnickschnack auf - aber wenn ich ihn treffe, tut er immer so, als wäre er pleite. Holt mein Gold.", sourceObjective = "Taruk im Halunkeneck möchte, dass Ihr die Schulden von \"Silbermond\" Harry eintreibt.", progress = "Ihr seid zurück. Habt Ihr, was mir gehört?", completion = "Eine gut gemachte Arbeit. Hier ist Euer Anteil, {name}. Wo der herkommt, gibt es noch mehr.\n\nAuf dieser Insel gibt es keinen Mangel an herumgammelnden Piraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11465] = { id = 11465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geplünderte Karawane", description = "Ich führte eine Karawane von Valgarde hierher, doch sie wurde von Drachenschindern angegriffen. Ich bin der einzige Überlebende dieses Hinterhalts. Zu allem Unglück habe ich es nicht geschafft, die Ladung Fjordtruthahn mit mir zu nehmen. Das ist die perfekte Gelegenheit für Euch, gemeinsam mit Eurem Falken den Sprung ins kalte Wasser zu wagen.\n\n<Hidalgo reicht Euch einen Käfig.>\n\nNehmt diesen Falkenkäfig und begebt Euch gen Westen die Straße entlang, die aus diesem Lager herausführt. Fangt mithilfe des Falkens die freilaufenden Truthähne ein und kehrt anschließend hierher zurück, sobald Ihr genug habt.\n\nVergesst nicht, die Falken zu füttern!", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe des dressierten Steinfalkens 5 Fjordtruthähne einfangt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt den Käfig mit.", progress = "Euer Falke muss ständig gefüttert werden, sonst wird er die Jagdbeute, die er für Euch fangen soll, auffressen.", completion = "Die Dreckskerle sind gewieft - und geduldig! Wir dürfen unseren Feind nicht länger unterschätzen. Diese Vrykul sind tödliche Jäger!\n\nTrotzdem: Mission abgeschlossen. Vielleicht ist die Zeit reif für Euch, auf etwas Jagd zu machen, das schwieriger zu fangen ist, als ein fetter Truthahn, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[11466] = { id = 11466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack hebt gern' mal einen", description = "Unser nächster Kunde, Jack Adams, wird nicht so leicht zu besiegen sein wie Harry. Er verbringt den ganzen Tag damit, gemeinsam mit seinen Freunden, die allesamt harte Piratenjungs sind, einen zu heben. Lasst uns diesmal keine Gewalt anwenden - könnte sonst schlimm ausgehen.\n\nVersucht, seine Trinkgewohnheiten zu Eurem Vorteil zu nutzen - denn ab 'ner bestimmten Menge Alkohol kippt jeder um.\n\nVielleicht könnte ja eine der Schankmaiden behilflich sein. Sobald er weggetreten ist, könntet Ihr ja Eure Hand in seine Tasche gleiten lassen und an das herankommen, was eigentlich mir gehört.", sourceObjective = "Taruk im Halunkeneck im Heulenden Fjord möchte, dass Ihr Jack Adams' Schulden eintreibt.", progress = "Habt Ihr bekommen können, was mir gehört, {name}?", completion = "Ich bin beeindruckt, {name}. Und ich gehör' nicht gerade zu der Sorte, die sich leicht beeindrucken lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11467] = { id = 11467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des toten Mannes Schulden", description = "Ihr habt vielleicht vom Schwarzen Konrad gehört, er ist ein berühmter Pirat in dieser Gegend.\n\nEr hat sehr gern auf meine Kämpfe gewettet. Er hat allerdings auch sehr gern nicht gezahlt.\n\nIch würde mein Geld gern haben, aber das Problem ist... er ist tot.\n\nIch war schon drauf und dran, die ganze Sache abzuschreiben, als ich das hier gefunden habe...\n\n<Taruk faltet eine Karte von der Insel der Speere auf, das nordöstliche Plateau ist mit einem roten X markiert.>\n\nEr hat seinen Schatz im Land der Tuskarr versteckt. Ich möchte, dass Ihr ihn holt. Ich will verdammt sein, wenn ich diesen Brackschlürfer ohne zu bezahlen davonkommen lasse.", sourceObjective = "Taruk im Halunkeneck will, dass Ihr auf dem Plateau am nordöstlichen Ende der Insel der Speere gleich nördlich von Iskaal auf die Suche nach dem Schatz des Schwarzen Konrad geht.", progress = "Habt Ihr den Schatz gefunden, {name}?", completion = "Ich werde das Gold nehmen. Es ist, was Konrad mir geschuldet hat. Den Rest könnt Ihr behalten.\n\nWenn Ihr mal eine Festanstellung braucht, bin ich mir sicher, ich könnte da etwas arrangieren. Möget Ihr in der Zwischenzeit stets Wind in den Segeln haben, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[11468] = { id = 11468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falke gegen Habicht", description = "Spürt Ihr die Nähe, {name}? Ihr fühlt sicherlich bereits, wie sich eine echte Bande zwischen Euch und Eurem Falken entwickelt. Würdet Ihr mir glauben, wenn ich Euch sage, dass es Zeit ist, durch die Augen Eures Vogels zu sehen? Ja, das ist der Meistergrad der Falknerei.\n\nDoch zuerst müsst Ihr mehr jagen! Der Vogel muss seine Reflexe verbessern und beschleunigen. Lasst es ihn mit einem anspruchsvolleren Gegner aufnehmen! Die Fjordhabichte der Region haben die Baumkronen über uns zu ihrer Heimat gemacht. Sie sind Euer nächstes Ziel!", sourceObjective = "Hidalgo am Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euren dressierten Steinfalken nutzt, um 10 Fjordhabichte zu erbeuten.\n\nKehrt mit dem Käfig zu Hidalgo zurück, wenn Ihr die Aufgabe Abgeschlossen habt.", progress = "Euer Falke muss stetig gefüttert werden, sonst wird er auch die Beute fressen, die er lediglich töten soll.", completion = "Ja, die Habichte weisen ein starkes territoriales Verhalten auf und fliegen oft im Schwarm. Ich schätze, das hätte ich Euch auch erzählen können, bevor ich Euch rausgeschickt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11469] = { id = 11469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrubbseife", description = "Jo, ich muss das Deck blitzeblank geschrubbt haben, bevor der verrückte Jonah wiederkommt. Un' ich werd das nicht auf meinen Knien machen!\n\nProblem: Wir ham keine Seife mehr. Das is' aber mehr Euer Problem als meins. Ihr seid <der Neue/die Neue> un' ich hab 'nen Spezialauftrag für Euch.\n\nOben an der Nordwestküste der Insel gibt's nen ganzen Haufen Seelöwen. Auf den Eisschollen in der Nähe findet Ihr den Alphabullen, den fetten Roy. Ihr bringt mir seinen Tran und ich zauber die beste Seife, die Ihr je geseh'n habt!", sourceObjective = "Lukchen Frostbug will, dass Ihr Tran vom fetten Roy besorgt, als Hauptbestandteil ihrer magischen Schrubbseife. Kehrt zu ihr auf das östliche Piratenschiff beim Halunkeneck zurück, wenn Ihr ihn habt.", progress = "Wo is' der Tran? Un' versucht nich' mir zu sagen, dass er keinen hat.\n\nDer fette Roy is' so verdammt fett, is'n Wunder, dass er überhaupt noch rumflanier'n kann!", completion = "Iiäh, das is' mal 'n Gestank!\n\nMacht schon, legt ihn dort hin. Ich wirk' meinen Zauber und dann wird mit Sicherheit Schrubbseife draus!", sourceObjectiveStatus = "unverified-source-field" }
quests[11470] = { id = 11470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Vogelvieh gibt es keine Ehre", description = "Ihr seid definitiv für den nächsten Schritt in der Falknerei bereit, {name}.\n\nNehmt Euren dressierten Falken und geht zum Vrykulfalkennest in der Nähe des Aufzugs am Steinwall östlich von hier. Von dort aus werdet Ihr Euren Falken aussenden, um die Eier des Habichts zu sammeln. Ihre Nistplätze liegen in den abgelegenen Bereichen der Klippen um das Nest herum. Findet diese Nester und ergattert mithilfe Eures Falkens die Eier!\n\nNehmt Euch jedoch vor den Fjordhabichtmatriarchinnen in Acht, {name}. Merkt Euch, dass Ihr mithilfe der Flucht- und Gleitfähigkeiten Eures Falkens Angriffen entgehen könnt.", sourceObjective = "Hidalgo im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr mithilfe Eures dressierten Steinfalkens 8 Eier eines Fjordhabichts sammelt.\n\nKehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und nehmt den Käfig mit.", progress = "Ihr habt Euren Vogel jetzt unter Kontrolle, {name}. Zeigt Eurem Falken, wohin er fliegen soll, und bringt mir diese Eier.", completion = "Bravo, {name}! Bravo! Die Bande zwischen Euch und Eurem Falken sind stark! Vielleicht könnt Ihr in absehbarer Zukunft auch ein paar Aufklärungsmissionen in Vrykulgebiet unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11471] = { id = 11471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt geht's lo-os", description = "Ich weiß, weshalb du hier bist, {name}. Du sollst unseren Anführer Jonah Sterling töten.\n\nIch würde dir in dieser Angelegenheit gerne meine Hilfe anbieten, denn Jonahs Führungsstil bringt unsere Mission in Gefahr.\n\nGleichzeitig die Flotten der Horde und Allianz anzugreifen: purer Selbstmord. Die Tuskarr in die Sklaverei verkaufen zu wollen, obwohl sie schon nach ein paar Tagen außerhalb dieses Klimas sterben: katastrophal.\n\nJonahs Unterschlupf befindet sich in einer Höhle westlich von hier. Bringt mir sein Handfernrohr als Beweis und meine erste Handlung als neue Anführerin wird es sein, alle Feindseligkeiten gegen unsere Verbündeten einzustellen.", sourceObjective = "Annie Bonn im Halunkeneck möchte, dass Ihr Jonah Sterlings Handfernrohr zu ihr bringt.", progress = "Tja, {name}. Hast du Jonahs Handfernrohr bekommen können?\n\nDein Wort alleine genügt mir nicht, verstehst du? Schließlich bin ich eine Piratin.", completion = "Jonah Sterlings Tage sind endlich gezählt! Er hätte niemals gedacht, dass es diese \"Magd\" mal zu was bringen würde.\n\nIch werde die Zeit, in der sich die Neuigkeiten über Jonahs Tod unter den Piraten verbreiten, dazu nutzen, meine Führung zu festigen. Meine Crew wird deinen Verbündeten keine Probleme mehr bereiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11472] = { id = 11472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zu seinem Herzen...", description = "Die Nordmeerpiraten haben den fetten Roy, den Alphabullen der Seelöwen dieser Insel, abgeschlachtet. Dann haben sie aus ihm Seife gemacht, um die Decks ihrer Schiffe sauber zu schrubben!\n\n<Anuniaq seufzt.>\n\nJetzt werden sich die Seelöwen nicht paaren. Helft mir, ihre Zahl aufrecht zu erhalten.\n\nDie Riffbullen halten sich südöstlich von hier an der Zwillingsküste auf. Sie mögen ganz besonders die schmackhaften Rifffische, die am östlichen und westlichen Ufer zu finden sind.\n\nNehmt dieses Netz hier und sammelt genug Fische, mindestens ein Dutzend - vielleicht mehr -, um einen Bullen durch die Meerenge zu einer Riffkuh zu locken.", sourceObjective = "Werft einem Riffbullen schmackhafte Rifffische zu, um ihn zu einer Riffkuh zu führen. Habt Ihr den Zweien verholfen, wahre Liebe zu finden, dann kehrt zu Anuniaq in Kamagua zurück.", completion = "Das sind gute Neuigkeiten! Jetzt werden mehr Bullen durch die Meerenge schwimmen, um sich mit den Kühen zu paaren. Schon bald werden wir viele Jungtiere auf den Inseln haben.\n\nDank Euch, {race}. Was auch immer Ihr in der Vergangenheit getan haben mögt, wisst, dass Ihr der Zukunft von Kamagua einen Dienst erwiesen habt!\n\nWir müssen so weitermachen, wenn wir dafür sorgen wollen, dass sich ihre Population erholt. Kommt morgen bitte wieder, damit wir ein weiteres Paar zusammenbringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11473] = { id = 11473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verräter unter uns", description = "Unser Kapitänleutnant, Annie Bonn, tut in letzter Zeit ziemlich paranoid. Sie scheint sich sicher, dass wir einen Spion unter uns haben, könnt'er das glauben?\n\nNa jedenfalls haben wir hier 'ne narrensichere Methode, Ratten zu jagen. Wisst Ihr, der gute Zeh'gehn dort drüben ist ein echter Hexendoktor. Hat einen Stammbaum bis nach Zul... Dingens oder so.\n\nGeht und sagt ihm, dass wir seine Wahrsagerkünste brauchen. Ich muss Euch warnen, {name}, nur ein oder zwei von uns können auch nur irgendetwas von dem verstehen, was Zeh'gehn sagt.", sourceObjective = "Sprecht mit Zeh'gehn im Halunkeneck.", completion = "Hia drüban, Maan. Du komman, um mich zu seh'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[11474] = { id = 11474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am hohen Kliff", description = "Wie immer müssen meine Crew und ich die eigentliche Arbeit erledigen. Zum Glück ist McSorfs Team nicht umsonst gestorben. Die Glyphe, die sie geborgen haben, wird uns bei der Entschlüsselung der Funde, die wir hier gemacht haben, helfen - das heißt, wenn wir jemals wieder in ihre Nähe kommen! Diese verdammten Eisenzwerge sind überall wie Pilze aus dem Boden geschossen und versuchen nun die Ausgrabungsstätten zuzuschütten! Ist das zu fassen? Die Dreckskerle wollen unsere Funde unter einem Haufen Erde begraben!\n\nWie dem auch sei, sprecht mit Walt dort drüben. Er wird Euch einweisen.", sourceObjective = "Sprecht mit Walt.", completion = "Über die Hälfte unseres Teams ist tot oder wird vermisst, Kleiner. Das ist unsere letzte Stellung hier oben auf dem hohen Kliff. Diese verdammten Eisenzwerge haben uns aus Ivalds und Baelguns Ruine vertrieben. Ich hab' jedoch einen Plan auf Lager, mit dessen Hilfe wir dort wieder reinkommen, bevor sie all unsere tollen Sachen unter der Erde begraben und wir unsere gesamten Daten für immer verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11475] = { id = 11475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das nötige Werkzeug für den Job", description = "Ich hab' dieses deaktivierte Konstrukt schon seit Tagen untersucht, {name}. Denke, dass ich eine passable Kopie des Golems anfertigen kann, die genug Platz für einen Passagier haben wird. Dahinter steckt die Idee, dass sich damit die Eisenzwerge täuschen lassen und wir Zutritt zu Baelguns Ruine erhalten.\n\nNun, ohne Hammer und Schüreisen werde ich gar nichts machen können. Ich brauch' mein Werkzeug! Unglücklicherweise hab' ich es in Ivalds Ruine zurückgelassen, als die Eisenzwerge das erste Mal angriffen. Beschafft mir mein Werkzeug!\n\nIvalds Ruine befindet sich weit im Nordosten.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr seine Bauwerkzeuge beschafft.", progress = "Schritt Nummer Eins: Walts Werkzeug besorgen.", completion = "Da ich mein Werkzeug nun wieder habe, kann die Arbeit beginnen. Das heißt, sobald ich ein paar Materialien habe. Die werdet Ihr mir nämlich als nächstes besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11476] = { id = 11476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Frosch und ein Messer", description = "Einige der Piraten hier... wir haben unsere ganz eigener Art zu sprechen. Zeh'gehn hat... sehr viele spezielle Arten zu reden... alles zusammengemischt.\n\nSoweit ich es verstehe, will er einen Frosch und ein Messer.\n\n\"Silbermond\" Harry könnte ein Messer für lau haben. Frösche rennen hier überall durch den Ort, schnappt Euch einfach einen und bringt ihn zusammen mit dem Messer zu ihm.\n\nAlso, ich will nicht in den Schuhen von dem armen Viech stecken, wenn Ihr wisst, was ich mein'.", sourceObjective = "Besorgt Euch ein glänzendes Messer von \"Silbermond\" Harry und fangt einen Ganovenfrosch. Bringt dann beides zu Zeh'Gehn im Halunkeneck.", progress = "Dia hat da Frosch un' Schnitza bekom, Mann?", completion = "Gut Dank, Bruddah. Da Frosch is' echt krass!", sourceObjectiveStatus = "unverified-source-field" }
quests[11477] = { id = 11477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in meinem Element?", description = "Leiser, {race}, leiser. Die Finger der Eisenzwerge sind schnell am Abzug. Nun, lasst Euch nicht von den Geschehnissen dort unten in der Grube täuschen. Diese stählernen Monstrositäten sind nicht dabei, irgendwas auszugraben! Nein, <Herr Kamerad/Frau Kameradin> - ganz im Gegenteil: Sie schütten die Stätte zu! Aus irgendeinem verrückten Grund wollen sie verhindern, dass irgendjemand diesen Ort findet.\n\n\"Was muss das für ein Zwerg sein, der uralte Relikte und Ausgrabungsstätten unter der Erde begraben will\", frage ich Euch. Nun, das will ich Euch verraten: Es ist die Art von Zwerg, die man mit rücksichtsloser Hingabe um die Ecke bringt! Geht dorthin und schaltet sie aus!", sourceObjective = "Donny in Ivalds Ruine im Heulenden Fjord möchte, dass Ihr 10 Eisenrunenzerstörer, 5 Eisenrunenhilfsarbeiter und 2 Eisenrunenweise tötet.", progress = "Ihr werdet so viele töten müssen, bis Ihr Euren Teil erfüllt habt.", completion = "Gute Arbeit, {name}. Das wird ihre Vergrabungsaktion ein wenig verlangsamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11478] = { id = 11478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenposten dort drüben...", description = "Ich sehe, dass Ihr noch nicht im Außenposten der Forscherliga im Süden wart und meinen Bruder besucht habt. Wieso tut Ihr Donny nicht einen Gefallen und überbringt Stanwad diese Nachricht. Es wird ihn interessieren, darüber zu erfahren, was die Eisenzwerge hier oben treiben.\n\nWie ich bereits sagte: Setzt auf und begebt Euch in Richtung Süden. Kurz bevor Ihr Baelguns Ruine erreicht, werdet Ihr den Außenposten sehen.", sourceObjective = "Überbringt Donnys Brief an Stanwad im Außenposten der Forscherliga.", progress = "Nachrichten von Donny?", completion = "Tja, nichts, das wir nicht schon wüssten. Zumindest wissen wir jetzt, dass Donny noch immer am Leben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11479] = { id = 11479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Krähenbein\" Dan", description = "Kröide hat geplabbärt, Kamerad. \"Krähenbein\" Dan is' uff de Kuddä da druiben.\n\nAm bestän geis'du da rübbä un' souchst nach de Radde, Mann. Gei z'rück zum Terry, wenn de Kielhaulerai fäddich is'.", sourceObjective = "Konfrontiert \"Krähenbein\" Dan. Er befindet sich auf einem der Schiffe im Halunkeneck. Sprecht mit dem hübschen Terry, sobald diese Aufgabe erfüllt ist.", progress = "Ich kann's gar nicht fassen, dass es Dan war. Habt Ihr Euch schon drum gekümmert?", completion = "Das sind mal traurige Neuigkeiten. Dan war'n alter Freund von mir... UND hat mir Gold geschuldet. Egal, wenn er mit diesen Südmeerbastarden gemeinsame Sache gemacht hat, dann hat er bekommen, was er verdient.\n\nWas Euch betrifft, mein Freund... Würde mal sagen, dass Ihr auf dem Weg nach oben seid, und zwar buchstäblich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11480] = { id = 11480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nummer Zwei kennenlernen", description = "Es ist nicht unbeachtet geblieben, was für gute Arbeit Ihr bis jetzt für uns geleistet habt, {name}. Unsere Zweitkommandierende, die charmante Annie Bonn, ist überaus beeindruckt von dem, was Ihr bisher getan habt, und will Euch kennenlernen.", sourceObjective = "Sprecht mit Annie Bonn im Halunkeneck.", completion = "Aber, aber, aber... Wenn das nicht {name} ist. Ihr taucht hier im Halunkeneck auf, niemand hat von Euch gehört, außer irgend so ein Goblin, den dieser Schwachkopf Terry seinen Freund nennt.\n\nSagen wir einfach mal, dass ich ein wenig... skeptisch bin... was Eure Absichten hier angeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krise am Sonnenbrunnen", description = "Bei den Naaru, ich danke Euch, {race}, für Euer Bemühen.\n\nUnsere Arbeit hier ist jedoch noch lange nicht beendet, weswegen ich Euch darum bitten muss, eine entscheidende Mission auszuführen - eine Mission so wichtig wie alle, mit denen ich Euch jemals beauftragt habe.\n\nUnsere Streitkräfte sind weit verteilt. Und um das Ganze noch schlimmer zu machen, mussten wir ein Kontingent nach Azeroth abbestellen, das die Entwicklung der Dinge auf dem Sonnenbrunnenplateau untersuchen soll.\n\nIhr werdet dort gebraucht, {name}. Meldet Euch bei Larethor und richtet ihm aus, ich wünschte, wir könnten mehr Männer entbehren.", sourceObjective = "Adyen der Lichtwächter auf der Aldorhöhe in Shattrath hat Euch gebeten, zum Sonnenbrunnenplateau zu reisen und dort mit Larethor zu sprechen.", completion = "Noch ein Soldat aus Shattrath? Welch willkommener Anblick!\n\nWünschte es gäbe mehr wie Euch, aber wir müssen mit dem auskommen, was uns gegeben ist. Was auch immer dort draußen geschieht, es wird nicht darauf warten, dass wir vorbereitet sind.\n\nSeht Euch ein wenig um, {class}. Es gibt viel zu erledigen. Packt mit an und tut Euren Teil.\n\nOh, ich vergaß: Macht Euch nicht über die Anfänger... ähhm, Anhänger der Seher lustig. Sieht aus, als würden wir in dieser Sache am selben Strang ziehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11482] = { id = 11482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflicht ruft", description = "Hört mich an, {race}.\n\nDie Pflicht verlangt, dass Ihr Euch zurück nach Azeroth begebt. Ein jeder, der dazu im Stande ist zu kämpfen, soll sich umgehend auf dem Sonnenbrunnenplateau melden.\n\nIch fürchte, dass ich Euch keine weiteren Informationen geben kann als diese:\n\nFür diese Mission werdet Ihr Euch mit den Aldor zusammentun. Sprecht mit einem Draenei namens Larethor, sobald Ihr dort ankommt.\n\nAnscheinend fordert die Situation, dass wir unsere Differenzen beiseite legen und uns zusammenschließen.\n\nMacht Euch bereit. Das hier klingt ernst.", sourceObjective = "Dathris Sonnensturm auf der Sehertreppe in Shattrath besteht darauf, dass Ihr umgehend nach Azeroth reist und Euch bei Larethor am Sonnenbrunnen meldet.", completion = "Willkommen auf dem Sonnenbrunnenplateau, Anfänger der... Wie bitte? Oh - Anhänger der Seher, natürlich. Habe ich das nicht gesagt?\n\nNun, gut, kommen wir gleich zur Sache. Hinter diesen Mauern geht es ernsthaft zur Sache, und das ist für unsere beiden Völker von großem Interesse. Und da keiner von uns über genügend Streitkräfte verfügt, um die Sache alleine anzugehen, werden wir ZUSAMMENARBEITEN. Verstanden?\n\nNa dann fangen wir doch einmal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[11483] = { id = 11483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir können es nachbauen", description = "Werkzeug? - vorhanden. Materialien? - nicht vorhanden.\n\nWenn wir dieses Ding bauen wollen, dann werdet Ihr mir die Materialien besorgen müssen.\n\nEins nach dem anderen, {name}. Für das Skelett benötige ich ein großes Fass aus Niffelvar, ein paar Dunkeleisenblöcke aus Valgarde und ein Seil in Industriestärke aus Quälheim.\n\nDie Vrykulorte Niffelvar und Quälheim liegen nordwestlich von hier; Valgarde befindet sich in der Dolchbucht - was auch im Nordwesten liegt. Sprecht mit McGoyver, um die Blöcke zu bekommen. Er wird Euch hierher zurückfliegen, wenn Ihr alles besorgt habt.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm ein großes Fass, ein Seil in Industriestärke und Dunkeleisenblöcke bringt.", progress = "Habt Ihr die Materialien für das Skelett dabei?", completion = "Ausgezeichnet. In Kombination mit der Haut wird daraus ein makelloser Klon des Konstrukts, das von den Eisenzwergen verwendet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11484] = { id = 11484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Technik", description = "Für eine Maschine wie diese ist der Unterbau zwar wichtig, doch wir dürfen die Wichtigkeit der Verkleidung des Konstrukts nicht unterbewerten. Wenn wir die Eisenzwerge zum Narren halten wollen, dann muss das Abbild perfekt sein!\n\nIch kann dafür sorgen.\n\nBringt mir einen makellosen Schaufelhauerbalg von den Schaufelhauern dieser Region und ein Stück Rippenstahl von den Vrykul in Niffelvar oder Quälheim gen Nordwesten.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr ihm einen makellosen Schaufelhauerbalg und ein Stück Rippenstahl bringt.", progress = "Wir werden im Nu weiter nach unseren Relikten suchen können!", completion = "Ich werde dafür sorgen, dass das Konstrukt einsatzbereit ist, sobald der Unterbau steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11485] = { id = 11485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Raketensprünge", description = "Nun gut, {name} - die Zeit ist gekommen, dass Ihr in dieses Ding klettert und den Umgang mit seinen grundlegenden Fähigkeiten lernt. Steigt auf die Werkbank, wenn Ihr bereit seid, und ich werde Euch ins Innere des Konstrukts setzen.\n\nEure erste Lektion dreht sich um die Bedienung des Transportsystems des Konstrukts. Ihr werdet bemerken, dass sich überall in der Ausgrabungsstätte spezielle Gravuren der Eisenzwerge befinden. Diese Runen werden von ihren Konstrukten dazu verwendet, sich aufzuladen und von einem Punkt zum nächsten zu fliegen. Versucht es einmal mit meiner Runengravur hier.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und dessen Fähigkeit 'Raketensprung' bei Walts Eisenrunengravur ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", progress = "Lasst Euch von diesen Schwarzmalern nichts gefallen!", completion = "Ihr seid schon fast bereit, mit diesem Kunstwerk ins Feld zu ziehen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Willkommen am Sonnenbrunnen, {class}. Macht Euch mit der Umgebung vertraut und legt dort Hand an, wo Ihr nur könnt. Es gibt viel zu tun!\n\nIch? Ja, ich hätte da eine Kleinigkeit, die erledigt werden müsste, aber ich bin mir nicht sicher, ob Ihr der Aufgabe gewachsen wäret.\n\nWir hatten einen Kontaktmann auf der Terrasse der Magister im Einsatz, der uns diverse Informationen zukommen ließ. Er hat jedoch vor Kurzem versäumt, uns Bericht zu erstatten, weswegen ich mir zunehmend Sorgen mache.\n\nDie Terrasse befindet sich gleich im Osten, die Anhöhe hoch. Die Informationen, die er gesammelt hat, sind entscheidend für unsere Mission.\n\nDenkt Ihr, dass Ihr damit zurecht kommt, {race}?", sourceObjective = "Exarch Larethor beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die Terrasse der Magister absucht und einen Blutelfenspion namens Tyrith findet.", completion = "...Kommt näher, {race}... Hört genau auf meine Worte...", sourceObjectiveStatus = "unverified-source-field" }
quests[11489] = { id = 11489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Daten sammeln", description = "Während Ihr das Konstrukt bedient, wird Eure wichtigste Aufgabe das Sammeln von Daten sein. Ich habe ein Eisenzwergrelikt in den Karren dort drüben gelegt - es geht um den schwebenden blitzerfüllten Kristall.\n\nSteigt auf die Werkbank und ich werde Euch wieder in das Konstrukt setzen. Führt die Datensammlungsfähigkeit des Konstrukts aus, sobald Ihr wieder hinterm Steuer sitzt, und sammelt die Testdaten auf.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Daten sammeln' in der Nähe des Eisenzwergrelikts ausführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", progress = "Passt wie angegossen, oder?", completion = "Perfekt! Funktioniert einwandfrei!", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seher der Seher", description = "Geht zur Terrasse... benutzt die Kugel.\n\n<Tyrith ringt nach Luft.>\n\nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...\n\n<Tyrith stirbt.>", sourceObjective = "Tyrith möchte, dass Ihr die Kugel auf dem Balkon in der Terrasse der Magister benutzt.", completion = "Ich denke, dass es kein Zufall ist, dass sich unsere Wege heute kreuzen.\n\nIch meine zu erkennen, dass dies eine Fügung des Schicksals ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11491] = { id = 11491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenrunenkonstrukte und du: Täuschung", description = "Man muss immer einen Notfallplan auf Lager haben, für den Fall, dass der Hauptplan fehlschlagen sollte! Das ist auch der Grund, weshalb ich das Konstrukt mit ein paar Antispionagesystemen ausgestattet habe.\n\nEs könnte sein, dass, sobald Ihr Euch in Baelguns Ausgrabungsstätte befindet, Euer toller, neuer Schlitten Verdacht erregt. Und genau dafür ist die Täuschungsfähigkeit da! Macht einfach bei jeder Konfrontation davon Gebrauch und Euch wird kein Leid zugefügt.\n\nVersucht es einmal an Lebronski und steigt auf seinen Teppich. Führt die Fähigkeit aus, sobald er Euch anschnauzt!\n\nSteigt auf die Werkbank, wenn Ihr bereit seid anzufangen.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Bluffen' auf Lebronski ausführt, nachdem Ihr über seinen Teppich gestiegen seid.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Ihr habt's ihm gezeigt! Nun ist es an der Zeit, Euch ins Feld ziehen zu lassen!\n\nHoffe, Ihr seid Euch der Sache sicher...", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Der Sonnenbrunnen heißt Euch willkommen, Sterbliche. Ihr trefft in der Tat zur rechten Zeit ein.\n\nWie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Findet ihn, Sterbliche. Noch einmal muss er aufgehalten werden.\n\nAndere Angelegenheiten von gleicher Dringlichkeit erfordern meine sofortige Aufmerksamkeit. Ich lege Kaels Schicksal in Eure Hände. Ihr dürft nicht versagen.\n\nMit etwas Glück werden wir uns wieder sprechen.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor am Sammelpunkt der Zerschmetterten Sonne treffen.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.\n\nWelch Kunde bringt Ihr mir?", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten auf der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.\n\nIch habe Euch unterschätzt, {race}. Bitte, nehmt dies im Namen der Sonnenbrunnenoffensive - eine Gabe, die eines Helden, wie Ihr einer seid, würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11494] = { id = 11494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzerfüllte Relikte", description = "Euer Konstrukt ist nun einsatzbereit. Alle Fähigkeiten wurden einer kurzen Prüfung unterzogen und ich habe die Maschine so programmiert, dass sie die Sprache der Titanen verstehen und sprechen kann.\n\nBegebt Euch mit dem Konstrukt zu Baelguns Ausgrabungsstätte genau südlich von hier, findet die dort überall verstreut liegenden blitzerfüllten Relikte und sammelt deren Daten. Erinnert Euch daran, jeglichen Eisenzwerg zu täuschen, der Verdacht an der Echtheit Eures Konstrukts hegt. Und vergesst nicht, per Raketensprung von Rune zu Rune zu springen und auf diese Weise mobiler zu sein!\n\nSteigt auf den Tisch, wenn Ihr bereit seid!", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und mit der Fähigkeit 'Daten sammeln' 15 Lesungen von Eisenrunendaten durchführt.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Und wieder einmal beweist Walt, dass er in der Tat der beste Zwerg ist! Was hältst du jetzt von meinem Konstrukt, Lebronski!\n\nIch danke Euch, {name}. Diese Daten werden sich zweifellos als unbezahlbar erweisen - wenn ich erst einmal herausbekommen habe, wie man sie aus dem Konstrukt herausbekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11495] = { id = 11495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zarte Knall des Donners", description = "Die Höhle, die wir in Baelguns Ausgrabungsstätte freigelegt haben, war DER Ort, vor dem sich die meisten fernhielten... Kann nicht sagen, dass ich ihnen das vorwerfe. Der Schlund der Höhle spuckte krachenden Donner, {name}! Ohrenbetäubender Donnerknall war es!\n\nIch denke, dass gegen Ende ein jeder die Höhle aufgegeben hatte. Denjenigen, die sich hineinwagten, um den Ort zu erkunden, widerfuhr Schlimmstes - und meistens kamen sie nicht zurück.\n\nIch möchte, dass Ihr Euch diese Höhle einmal anseht, wenn Ihr in Baelguns Ausgrabungsstätte seid. Begebt Euch ins Innere, erkundet die Gegend um die Titanenstatue und meldet Euch dann mit den Funden wieder bei mir zurück.", sourceObjective = "Walt im Außenposten der Forscherliga im Heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die donnernde Höhle in Baelguns Ausgrabungsstätte erkundet.\n\nÜber das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Unglaublich! Was könnten diese Eisennervensägen im Schilde führen? Was machen sie auf den Sturmgipfeln? Und wer ist dieser Loken?! Ich werde die Informationen an unsere zentrale Operationsbasis in der Drachenöde weiterleiten, {name}. Auch werde ich sie wissen lassen, dass Ihr bei der Beschaffung besagter Infos außerordentlich wertvoll gewesen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barrieren des Sanktums", description = "Zuerst müssen wir das Sanktum der Sonnenweiten einnehmen. Sobald wir es gesichert haben, werden wir in der Lage sein, seine Energien für die Öffnung eines Portals nach Shattrath zu nutzen.\n\nDas Sanktum quillt über von Getriebenen - frühere Blutelfen, die zu hirnlosen Schatten ihrer selbst verkümmert sind. Die Verteidigungsanlangen hätten dieses Eindringen normalerweise verhindert, aber die Getriebenen haben die Energiequellen der Schutzbarrieren gestohlen.\n\nStellt den Getriebenen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt sie, um die Barrieren des Sanktums aufzuladen.", sourceObjective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche den Osten des Sanktums der Sonnenweiten umgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, der sein eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch zur Wildhammerfeste im Südwesten des Schattenmondtals begeben, und dort Ilsa Trubelbräu nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Ilsa Trubelbräu in der Wildhammerfeste im Schattenmondtal.", completion = "Ach, Nutral hat Euch also hierher geschickt? Sehr gut... Erinnert mich daran, dass ich ihm einen Krug Bier zum Dank für all die Fluglehrlinge, die er zu mir schickt, zukommen lasse.\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Niemand fliegt besser als die Wildhammer und diejenigen, die von uns ausgebildet wurden. Für ein Entgelt, ein nicht zu kleines wohlgemerkt, lehre ich Euch die Kunst des Fliegens!\n\nUnd wenn Ihr fertig seid, dann vergesst nicht mit Brunn zu sprechen - er hat ein paar schöne Greifen zur Auswahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, <der sein/die ihr> eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch nach Schattenmond im Nordwesten des Schattenmondtals begeben, und dort Olrokk nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Olrokk in Schattenmond im Schattenmondtal.", completion = "Blut und Donner, Nutral hat mir schon wieder einen Boden-Grunzer geschickt! Sehr gut... für einen Draenei.\n\n<Olrokk spuckt auf den Boden neben Euch.>\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Für einen großen Sack Gold bringe ich Euch genug bei, um nicht unehrenhaft in den Tod zu stürzen.\n\nUnd wenn Ihr fertig seid, dann vergesst nicht, Dama Wildmähne einen unserer Windreiter abzukaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Siegelring von Prinz Kael'thas", description = "Heute werde ich das Unmögliche von Euch verlangen, {class}. Denn heute müsst Ihr mir den Siegelring von Kael'thas Sonnenwanderer, Lord der Blutelfen, beschaffen!\n\nEs ist wahr, die Gerüchte von seinem Tod waren aus der Luft gegriffen. Er ist nun einmal mehr erschienen - und diesmal auf der Terrasse der Magister auf der Insel von Quel'Danas. Was er dort macht, soll Euch jemand anderes berichten. Was ich weiß ist, dass es unzählig viele Sammler gibt, die an diesem Prinzenring interessiert sind. Und ich will ihnen diesen Ring beschaffen.\n\nOder, um genau zu sein will ich, dass Ihr ihn für mich beschafft.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Siegelring von Prinz Kael'thas zu beschaffen. Bringt diesen zu ihm ins Untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf der Terrasse der Magister und nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Terrasse der Magister muss in der Tat ein gefährlicher Ort sein - so nahe am Sonnenbrunnen, wie sie ist.\n\nIhr habt doch keine Bedenken, oder?", completion = "Der Blutelfenprinz ist also diesmal wirklich tot? Wie schade, ich dachte immer, dass er Klasse besäße. Wenn man sich denkt, dass jemand so erhaben für solch einen lumpigen Betrag zur Strecke gebracht werden konnte.\n\nAber es ist nun einmal so, wie man sagt: Geschäft ist Geschäft. Eure Belohnung ist verdient, Abenteuerer.\n\nKommt morgen wieder und ich werde einen anderen Auftrag für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schwestern der Qual", description = "Mah'duun vernahm eine Stimme, die ihm zuflüsterte, dass die Schwestern der Qual in die Hölle zurückgeschickt werden müssen, aus der sie kommen.\n\nMah'duun weiß, dass sich die Dämonen auf der Terrasse der Magister auf der Insel Quel'Danas befinden.\n\nIhr werdet Euch des Kopfgeldes wegen auf dieses Unterfangen einlassen oder auch nicht.", sourceObjective = "Netherpirscher Mah'duun möchte, dass Ihr 4 Schwestern der Qual erschlagt. Kehrt zu ihm in das Untere Viertel in Shattrath zurück, sobald Ihr sie getötet habt, um das Kopfgeld einzufordern.", completion = "Wer weiß, weshalb die dämonischen Schwestern den Tod finden müssen? Sorgt Ihr Euch darum?\n\nMah'duun denkt, dass Ihr Euch jedoch genug darum sorgt, um das Kopfgeld einzustreichen.\n\nKommt morgen wieder und die Winde werden wieder zu Mah'duun gesprochen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11501] = { id = 11501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues aus dem Osten", description = "Die Leute in Westwacht müssen erfahren, was hier vor sich geht, {name}. Ich möchte, dass Ihr persönlich Hauptmann Adams die Nachricht überbringt.\n\nSagt mir Bescheid, sobald Ihr bereit seid, und ich werde Euch die Maschine für einen letzten Flug bereitstellen. Sie wird Euch zwar nach Westwacht tragen, jedoch höchstwahrscheinlich dabei in die Luft fliegen.\n\nEs war mir ein Vergnügen...", sourceObjective = "Sprecht mit Hauptmann Adams in Westwacht.", completion = "Herrlich... Als ob es nicht schon genug wäre, dass uns die Geißel am - na Ihr wisst schon - klebt, nun müssen wir uns auch noch mit einem wütenden uralten Titanenkonstrukt herumschlagen!\n\nIch werde etwas Zeit brauchen, um das zu verarbeiten, {race}. In der Zwischenzeit werdet Ihr hier genug Arbeit finden, die getan werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung von Halaa", description = "Wir sind kein kriegerisches Volk, {race}. Wenn der Krieg jedoch über unser Land kommt, rennen wir nicht vor ihm davon.\n\nDie Allianz und die Horde bekämpfen sich in der Stadt Halaa im Nordwesten. Wir wissen nicht, was die Blutelfen vorhaben, aber jeder Sieg, den die Horde erringt, wäre katastrophal. Die gemeinsame Geschichte unseres Volks mit den Orcs ist eine des Blutvergießens und des Verrats.\n\nGeht nun, streckt den Feind in Halaa nieder und Ihr werdet mit Münze, Ehre und Ruhm belohnt.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Lakoor in Telaar zurück.", completion = "Ich danke Euch, {name}. Eure Mühen werden nicht unbeachtet bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde - alte und neue", description = "Unser uralter Feind, die Draenei, sind mit mächtigen Verbündeten wiedergekehrt. Sie führen Krieg in Halaa, südwestlich von hier.\n\nSie dürfen nicht siegreich sein, denn Garadar wäre gewiss als nächstes dran.\n\nGeht und erschlagt diejenigen, die es wagen, unserem uralten Feind beizustehen.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Karrtog in Garadar zurück.", completion = "Ihr macht unserem Volk große Ehre. Ihr habt unseren Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[11504] = { id = 11504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten stehen auf!", description = "Der Pfad östlich von uns gehört zu den wichtigsten Jagdgebieten der Tuskarr. Zumindest war das einmal so...\n\nWenn in jüngerer Zeit unsere Jäger nach Kamagua zurückkehren, behaupten sie, dass die Toten wiederauferstanden seien und nach Blut trachten! Aus diesem Grund sind mein Sohn und ich hierhergekommen. Urahn Atuik hat uns dazu aufgefordert, an der Steilküste nach einer Lösung des Problems zu suchen.\n\nWerdet Ihr uns in diesen Zeiten der Not zur Seite stehen? Ich suche nach Helden, die gewillt sind, den Gefahren des im Südosten gelegenen Schildhügels ins Auge zu blicken. Sucht in den entweihten Gräbern nach Hinweisen und kehrt mit den Funden zu mir zurück.", sourceObjective = "Orfus von Kamagua am Uralten Aufzug im Heulenden Fjord möchte, dass Ihr nach Fengirs Hinweis, Rodins Hinweis, Isuldofs Hinweis und Windans Hinweis sucht.", progress = "Die Tuskarr brauchen Eure Hilfe!", completion = "<Orfus' Barthaare sträuben sich.>\n\nPiraten... kennt ihre Verworfenheit keine Grenzen?\n\nWir müssen die gestohlenen Artefakte wiederbeschaffen und sie an diesen verwunschenen Ort zurückbringen, damit mein Volk einmal mehr erleben kann, was das Wort 'Frieden' bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Auchindouns Geister sind zwar nicht am Konflikt zwischen Allianz und Horde beteiligt, sollten wir sie jedoch auf unsere Seite ziehen können, hätten wir unseren Feinden gegenüber einen Vorteil in dieser Region.\n\nEin uralter Brauch führt die Lebenden auf den Pfad zu den Geistertürmen in der Knochenwüste, um den Geistern dort ihre Ehre zu erweisen - jedoch nur zu speziellen Tageszeiten. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werdet Ihr dadurch die Geister auf unsere Seite ziehen.\n\nSollten wir Erfolg damit haben, die Gunst der Geister zu erlangen, werden sie uns eine Wohltat erweisen, die unsere Bestrebungen unterstützen wird.", sourceObjective = "Helft der Allianz, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister sind ruhelos, {name}. Habt Ihr Eure Aufgabe vollbracht?", completion = "Die Geister sind ihrer Ruhe einen Schritt näher. Es ist gut, ihre Gunst zu erlangen - besonders dann, wenn so nahe an ihrer Ruhestätte Krieg geführt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Die Draenei mögen unsere Feinde sein, aber die Geister ihrer Urahnen in Auchindoun sind rastlos und niemandem untertan.\n\nEin uralter Brauch der Draenei verlangt von ihnen, dass sie zu verschiedenen Tageszeiten bei den Geistertürmen in der Knochenwüste ihren Urahnen Respekt zollen. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werden dadurch die Geister in Auchindoun zur Ruhe kommen.\n\nDie Allianz wird versuchen, die Türme einzunehmen, um die Gunst der Geister zu erlangen. Wir müssen sicherstellen, dass die Horde hier erfolgreich ist.", sourceObjective = "Helft der Horde, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister von Auchindoun sind um uns. Werden sie uns eine Wohltat zuteilwerden lassen?", completion = "Die Geister sind einen Schritt näher daran, ihre Ruhe zu finden, und haben uns deswegen ihre Gunst verliehen.\n\nEs muss eine Demütigung für unseren Feind sein, dass sich seine eigenen Urahnen gegen ihn wenden - auch, wenn es nur vorübergehend ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11507] = { id = 11507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahn Atuik und Kamagua", description = "<Orfus packt die Hinweise, die Ihr ihm mitgebracht habt, zu einem Bündel zusammen.>\n\nMein Volk befindet sich in einer verbitterten Auseinandersetzung mit den Freibeutern des Nordmeeres, von der es keinen Ausweg zu geben scheint. Wenn irgendein Tuskarr uns helfen und die Schandtaten der Piraten ungeschehen machen kann, dann ist das Urahn Atuik von Kamagua. Ihr müsst diese Hinweise schleunigst zu ihm bringen.\n\nUm nach Kamagua zu gelangen, müsst Ihr den Uralten Aufzug hinter mir nehmen. Lasst Euch von ihm direkt nach Kamagua befördern und sucht Urahn Atuik auf.", sourceObjective = "Orfus von Kamagua im Heulenden Fjord möchte, dass Ihr Orfus' Bündel nach Kamagua zu Urahn Atuik bringt.", progress = "Neuigkeiten von Orfus?", completion = "Orfus ist ein guter Tuskarr - einer unserer stärksten Krieger. Ich wusste, dass er uns nicht im Stich lassen würde.\n\nErlaubt mir, einen Blick auf das zu werfen, was Ihr mir mitgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11508] = { id = 11508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezzix Achsenbruch", description = "Das Halunkeneck weit im Süden dient den Piraten als Hafen. Unglücklicherweise haben sie in ihrem Lager viele tödliche Verteidigungsanlagen aufgestellt.\n\nEs gibt jedoch jemanden, der uns vielleicht dabei helfen könnte, den Ort zu infiltrieren.\n\nVor Kurzem kam ein Piratensöldner namens Grezzix Achsenbruch in unser Dorf. Er ist auf der Suche nach Verpflegung und Unterkunft. Als Gegenleistung würde er uns Informationen über unsere Feinde geben und unseren Feinden Fehlinformationen über unsere Angriffspläne zukommen lassen. Sucht ihn auf, {name}. Er befindet sich auf seinem Schiff südwestlich von hier.", sourceObjective = "Sprecht mit Grezzix Achsenbruch.", completion = "Harr, Kamerad. Grezzix hat's nie gemocht, sich die Hände schmutzig zu machen! Grezzix findet das Piratenleben toll, solange er keine von den Arbeiten machen muss.\n\nIch hab' diese Artefakte gesehen. Sie sind der Grund dafür, wieso ich hier bin und nicht im Halunkeneck! Schlimme, schlimme Dinger sind das...\n\nHe, ist doch dein Leben, oder? Du willst ins Lager rein und Grezzix kann dir dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11509] = { id = 11509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich einen Ruf machen", description = "Alle Freibeuter des Nordmeeres fürchten und respektieren Grezzix. Ich denke mal, dass sie meine besonderen Talente achten und mein tolles Schiff beneiden. Alles, was du machen musst, ist, hinter meinem Kabinenjungen Lou hinterher zu latschen, und du bist in... in wie Zinn, sozusagen. Piraten lieben Zinn.\n\nRed' einfach mit Lou, wenn du fertig bist, und er wird dich zum Halunkeneck bringen.\n\nOh ja, als Erstes wirst du wohl mit \"Silbermond\" Harry sprechen müssen. Er wird mehr über das Zeugs Bescheid wissen, das sie mitgehen haben lassen. Pass bloß auf, was du vor ihm sagst. Das is'n Verrückter... verrückt nach Blutelfen ist er.", sourceObjective = "Sprecht mit \"Silbermond\" Harry im Halunkeneck über die verschwundenen Vrykulartefakte.", completion = "<Harry blickt Euch an und zieht eine Augenbraue hoch.>\n\nSo, du bist also wie ich, hm? Ein wenig exzentrisch.\n\n<Harry flüstert Euch zu.>\n\nNiemand zieht sich hier so an.\n\nWas diese Artefakte angeht... Jeder, der mit den Dingern in Berührung kam, ist am Ende entweder tot gewesen, verschwunden oder gleich beides.\n\nWenn du noch immer mehr erfahren willst, kann ich dir weiterhelfen - wird dich aber was kosten.\n\n<Harry zwinkert Euch zu.>\n\nDu tust mir 'nen Gefallen und ich lass dich am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11510] = { id = 11510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Bodo von der Hermannsklause\"", description = "Das Erste, was Jonah Sterling gemacht hat, nachdem er durchgedreht ist, war, meinen hoch geschätzten Wahrsagerkristall der Sin'dorei zu nehmen und ihn an \"Bodo von der Hermannsklause\", den Orca und Fluch meines Lebens, zu verfüttern.\n\nNein, ich hab' dem verdammten Ding nicht den Namen gegeben. Ich weiß nur, dass er an den Schiffen im Halunkeneck vorbei in Richtung Südosten geschwommen ist. Bring diesen übergroßen Goldfisch um und reiß ihm meinen schönen Sin'doreikristall aus dem Bauch.\n\nMach das und wir kommen ins Geschäft.", sourceObjective = "\"Silbermond\" Harry im Halunkeneck möchte, dass Ihr den Orca \"Bodo von der Hermannsklause\" tötet und den Wahrsagerkristall der Sin'dorei wiederbeschafft.", progress = "Hast du dich verirrt?", completion = "<Harry nimmt Euch den Kristall ab und fängt an, ihn zu liebkosen.>\n\nOh, mein Schatz! Hat dir der große, böse Wal wehgetan? Alles wird gut. Ich werde dich nie wieder aus den Augen lassen!\n\n<Harry blickt zu Euch auf.>\n\nSo, wo waren wir stehen geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[11511] = { id = 11511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab des Sturmfurors", description = "Diese Artefakte sind verflucht und es wäre purer Wahnsinn, auf die Suche nach ihnen zu gehen, {race}. Ich weiß mit Sicherheit, dass ein jeder, der mit einem der Gegenstände in Berührung gekommen ist, entweder verrückt geworden ist oder getötet wurde.\n\nDieser Stab hier zum Beispiel: Das Letzte, was ich gehört habe, war, dass das Schiff, auf dem er sich befand, aufgegeben wurde und man es irgendwo im Osten der Insel der Speere, die sich nördlich von hier befindet, sich selbst überließ.\n\nÜberprüf mal den Frachtraum des Schiffs, wenn du das Ding wirklich willst.\n\nAber was auch immer du machst, bring den Stab bloß nicht wieder hierher! Und mach um Abdul einen großen Bogen! Er wird dir das Herz herausreißen.", sourceObjective = "Beschafft den Stab des Sturmfurors und bringt ihn zu Orfus von Kamagua im Heulenden Fjord.", progress = "Habt Ihr den Stab?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11512] = { id = 11512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gefrorene Herz Isuldofs", description = "Einige sagen, dass Jonah nie ganz richtig im Kopf war, doch ich weiß, was wirklich passiert ist. Es war das Herz. Dieses verdammte gefrorene Herz! In dem Moment, als er es aus dem Grab nahm, sah ich, wie es ihn veränderte - konnte sehen, wie das Blut in seinen Adern gefror... Es war damals, als ihn wirklich der Wahnsinn packte.\n\nEr verließ uns, um sich in seiner Höhle auf der Nordseite der Insel zu verkriechen. Das Letzte, was ich gehört habe, war, dass er das Herz in den hinteren Teil seiner Bärenhöhle verbannt hat. Doch das ist nicht genug und es kommt viel zu spät...\n\nIch werde dich eigenhändig umbringen, wenn du das Herz mit hierher nimmst!", sourceObjective = "Beschafft das gefrorene Herz Isuldofs und bringt es zu Orfus von Kamagua im Heulenden Fjord.", progress = "Das... das gefrorene Herz Isuldofs?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manazellen abfangen", description = "Ich habe mir einen Plan ausgedacht, wie wir an eine Energiequelle kommen können, die stark genug ist, um unser Portal zu erschaffen.\n\nDie Streitmächte der Astralen auf dem Landeplatz von Bash'ir im Nordwesten des Schergrats schmuggeln Manazellen aus der Festung der Stürme heraus und schaffen sie in Kael'thas' Namen zum Sonnenbrunnen.\n\nSie haben die Zellen zwar versteckt, aber es gibt einen Weg, wie Ihr sie finden könnt. Die Astralen tragen Phasenvorrichtung bei sich, mit deren Hilfe Ihr die eingeschmuggelten Waren entdecken könnt.\n\nHütet Euch jedoch vor den Phasenwyrm, den Wächtern der Manazellen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sonnenbrunnenportal aufrechterhalten", description = "Wir müssen den Energiefluss zu unserem Portal aufrechterhalten oder es wird kollabieren. Die versteckten Manazellen der Astralen auf dem Landeplatz von Bash'ir werden den Zweck erfüllen. Der Landeplatz befindet sich weit im Norden auf dem Hochplateau in der nordwestlichen Ecke des Schergrats.\n\nBeschafft Euch eine Phasenvorrichtung von einem der Astralen und benutzt sie, um die Schmuggelwaren zu finden.\n\nNehmt Euch nur vor den Phasenwyrm in Acht, von denen sie die Manazellen bewachen lassen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", progress = "{name}, wie steht es um die Manazellen, die Ihr heute für uns beschaffen wollt?", completion = "Diese Manazellen werden unser Portal weiterhin mit Energie speisen.\n\nKehrt morgen wieder zurück und ich werde Euch wieder auf Manazellensuche schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut für Blut", description = "Als Kaels Streitmacht durch das Portal schritt, wurden seine loyalsten Lakaien auf eine entsetzliche Weise belohnt: Sie blieben zurück und soffen tagelang Dämonenblut.\n\nDas Blut hat sie verändert und ihnen neue Kräfte verliehen - es wird jedoch auch ihr Verderben sein.\n\nNehmt Blutproben von anderen Dämonen und benutzt sie, um den Teufelstrinker zu speisen und diese arroganten Narren ihrer Macht zu berauben. Tötet sie, sobald sie geschwächt sind. Kehrt dann zu mir zurück.", sourceObjective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe des Teufelstrinkers 4 ausgemergelte Getriebene des Teufelsbluts tötet. Um den Teufelstrinker zu speisen, benötigt Ihr das Dämonenblut von Racheherolden, die sich in der Nähe befinden.", progress = "Diese Monster sind eine Schande für unser Volk. Wir müssen sie vernichten, {name}.", completion = "Narren. Sie haben gelernt, wie man Teufelsenergie entzieht, aber nicht, wie man sie behält.\n\nWir haben Glück, {name}. Ein erfahrener Streiter des Teufelsbluts hätte gewiss einen beeindruckenden Gegner abgegeben.", sourceObjectiveStatus = "unverified-source-field" }
